// ═══ SEQUENCER — pure function, not an AI call ═══
// §B.1–B.5 of unit-context-system-v1.md. Given the student's memoryStore,
// returns { unitRecord, lessonInUnit, isFirstLesson, isConsolidating }.
function getUnitAssignment(store) {
  const u = store.currentUnit || 1;
  const l = store.lessonInUnit || 1;
  const status = store.unitStatus || "not_started";
  const record = UNIT_RECORDS.find(r => r.unit === u) || UNIT_RECORDS[0];
  const isFirstLesson = (store.lessonsCompleted || 0) === 0;
  return { unitRecord: record, lessonInUnit: l, isFirstLesson, isConsolidating: status === "consolidating" };
}

// Check unit completion conditions (§B.3). Returns { complete, unmet }.
function checkUnitCompletion(store, unitNum) {
  const record = UNIT_RECORDS.find(r => r.unit === unitNum);
  if (!record) return { complete: true, unmet: [] };
  const l = store.lessonInUnit || 1;
  const unmet = [];

  // Condition 1: at least 2 lessons
  if (l < 2) unmet.push("fewer than 2 lessons");

  // Condition 2: every can-do practised at least once
  const addressed = (store.unitCanDosAddressed && store.unitCanDosAddressed[unitNum]) || [];
  const missedCanDos = record.canDo.filter(c => !addressed.includes(c));
  if (missedCanDos.length) unmet.push("can-dos not practised: " + missedCanDos.join(", "));

  // Condition 3: ≥75% core vocabulary presented
  const presented = (store.unitVocabPresented && store.unitVocabPresented[unitNum]) || [];
  const threshold = Math.ceil(record.coreVocab.length * 0.75);
  if (presented.length < threshold) unmet.push(`vocab presented ${presented.length}/${record.coreVocab.length} (need ${threshold})`);

  // Condition 4: grammar taught and practised
  const grammarDone = store.unitGrammarTaught && store.unitGrammarTaught[unitNum];
  if (!grammarDone) unmet.push("grammar not yet taught");

  return { complete: unmet.length === 0, unmet };
}

// Advance the sequencer after a lesson. Mutates and returns updated store fields.
function advanceSequencer(store) {
  const u = store.currentUnit || 1;
  const l = store.lessonInUnit || 1;
  const status = store.unitStatus || "in_progress";
  const { complete, unmet } = checkUnitCompletion(store, u);

  if (complete) {
    // Unit complete — advance to next
    const history = [...(store.unitHistory || []), {
      unit: u, lessonsSpent: l, status: "complete",
      completedDate: new Date().toISOString().slice(0, 10)
    }];
    const nextUnit = Math.min(u + 1, 22);
    return {
      currentUnit: nextUnit, lessonInUnit: 1,
      unitStatus: nextUnit > 22 ? "complete" : "not_started",
      unitHistory: history
    };
  }

  if (l >= 5) {
    // Force-complete after 5 lessons — unmet items enter fragile list
    console.warn(`[Sequencer] Unit ${u} force-completing after 5 lessons. Unmet:`, unmet);
    const history = [...(store.unitHistory || []), {
      unit: u, lessonsSpent: l, status: "force_complete",
      completedDate: new Date().toISOString().slice(0, 10), unmet
    }];
    const nextUnit = Math.min(u + 1, 22);
    return {
      currentUnit: nextUnit, lessonInUnit: 1,
      unitStatus: nextUnit > 22 ? "complete" : "not_started",
      unitHistory: history
    };
  }

  if (l >= 4 && !complete) {
    // Move to consolidating after 4 lessons if not complete
    return { lessonInUnit: l + 1, unitStatus: "consolidating" };
  }

  // Continue in current unit
  return { lessonInUnit: l + 1, unitStatus: "in_progress" };
}

// Build the recycle list for a lesson (§D.3).
function buildRecycleList(unitRecord, store) {
  const items = [];
  for (const src of (unitRecord.recyclesFrom || [])) {
    const srcRecord = UNIT_RECORDS.find(r => r.unit === src.unit);
    if (!srcRecord) continue;
    // Only recycle from units the student has completed or assumed
    const completed = (store.unitHistory || []).some(h => h.unit === src.unit);
    const skipped = (store.skippedUnits || []).includes(src.unit);
    if (!completed && !skipped) continue;
    // Check wordMastery — skip items already mastered
    const activeItems = src.items.filter(item => {
      const mastery = store.wordMastery && store.wordMastery[item];
      return !mastery || mastery.stage !== "mastered";
    });
    if (activeItems.length) {
      items.push({ unit: src.unit, theme: srcRecord.theme, items: activeItems, type: src.type || "vocabulary" });
    }
  }
  return items;
}

// Build the unit-context prompt block (§A.2). Prepended to the merged
// student-and-needs prompt between teacherCtx and PART ONE.
function buildUnitContext(unitRecord, lessonInUnit, store) {
  const u = unitRecord;
  const recycleItems = buildRecycleList(u, store);
  const recycleBlock = recycleItems.length
    ? "RECYCLING FROM EARLIER UNITS:\n" + recycleItems.map(r =>
        `From Unit ${r.unit} (${r.theme}): ${r.items.join(", ")} [${r.type}]`
      ).join("\n")
    : "No specific recycling targets for this lesson.";
  const feedsForwardBlock = (u.feedsForward || []).length
    ? "WHERE TODAY'S LANGUAGE RETURNS:\n" + (u.feedsForward || []).map(f =>
        `Unit ${f.unit}: ${f.items.join(", ")} \u2192 ${f.what}`
      ).join("\n")
    : "";
  const pAnswers = store.personalisationAnswers && store.personalisationAnswers[u.unit];
  const pBlock = pAnswers
    ? "What Leo already knows:\n" + Object.entries(pAnswers).map(([k,v]) => `${k}: ${v}`).join("\n")
    : "Leo has not yet asked the personalisation questions for this unit. Ask them naturally within the lesson \u2014 do not interview the student.";
  const isFirst = (store.lessonsCompleted || 0) === 0;
  const firstNote = isFirst ? "\nThis is the student's first lesson with Leo. Do not reference prior Leo interactions." : "";

  return `\n\u2550\u2550\u2550 TODAY'S UNIT \u2550\u2550\u2550\n\nUnit ${u.unit}: ${u.theme} (Block: ${u.block})\nLesson ${lessonInUnit} of this unit.\n\nCAN-DO OUTCOMES for this unit:\n${(u.canDo || []).map(c => "- " + c).join("\n")}\n\nGRAMMAR FOCUS: ${(u.grammar || {}).point}\n${((u.grammar || {}).relatedPoints || []).length ? "Related (recycled, NOT new): " + ((u.grammar || {}).relatedPoints || []).join(", ") : ""}\n${(u.grammar || {}).homeUnit ? "This unit is the HOME UNIT for this grammar point \u2014 teach it as new." : "This grammar point was introduced in an earlier unit \u2014 recycle it, do not re-teach from scratch."}\n\nCORE VOCABULARY (teach to every student, 4\u20138 per lesson from this pool):\n${(u.coreVocab || []).join(", ")}\n\nEXTENSION VOCABULARY (teach only when the personalisation test passes):\n${(u.extensionVocab || []).join(", ")}\n\nExpected cards this lesson: ${u.expectedCards}. Do not pad beyond this range.\n\nFUNCTIONAL LANGUAGE: ${(u.functionalLanguage || []).join(" \u00b7 ")}\n\nPRONUNCIATION FOCUS: ${(u.pronunciation || {}).focus} \u2014 ${(u.pronunciation || {}).detail}\n\n${recycleBlock}\n\n${feedsForwardBlock}\n\nPERSONALISATION: ${u.personalisationNotes}\n${pBlock}${firstNote}\n\nYOUR FREEDOM WITHIN THIS UNIT: Choose the communicative SITUATION that brings the can-do outcomes alive for THIS student. The unit says WHAT to teach; you decide the scenario, the authentic material, the memorable moment, and the mission.\n\nYOUR CONSTRAINT: do not teach grammar, vocabulary, or pronunciation outside what this unit specifies. If today's student needs something outside this unit, note it in your analysis as \\"needed but belongs in Unit X\\" \\u2014 the sequencer will get them there.\\n\\nPERSONALISATION CHECK: before choosing today's situation, name ONE specific fact about THIS student from what you know about them (an interest, their job, something from a recent lesson or diary entry, a mission they tried) \\u2014 then let it visibly shape the scenario. If there is genuinely nothing specific to draw on yet (a very new student), say so plainly and choose the most useful generic version of the unit's theme instead of inventing a personal detail. Never fabricate a fact about the student.\\n\\nAUSTRALIAN TEXTURE CHECK: a scenario is not Australian because it contains Australian vocabulary. It is Australian because of what actually happens \\u2014 the specific small moment a person in this exact situation would experience here and nowhere else. Before finalising today's scenario, name the ONE detail that makes it unmistakably a Melbourne/Sydney/Perth/regional kitchen, supermarket, GP visit, rental inspection \\u2014 not a generic version of that situation. Examples of texture, not vocabulary: a new kitchenhand is handed a laminated allergy chart on day one and asked to read it back; a checkout operator's first 'how's your day going' comes from a customer, not a script; a GP receptionist asks for a Medicare card before anything else. If you cannot name a genuine textural detail for today's situation, that is a signal the scenario is too generic \\u2014 choose a narrower one.\\n`;
}



// ═══ PLACEMENT → ENTRY UNIT MAPPING (§E.4, §E.5) ═══
// Pure lookup table. Score thresholds from §E.4 — starting values,
// Genesis will confirm finals once placement scoring defect is resolved.
function placementToEntryUnit(grammarScore, vocabScore) {
  // grammarScore and vocabScore are normalised 0–1 or band strings.
  // Use grammar as primary signal, vocab as tiebreaker.
  const g = typeof grammarScore === "number" ? grammarScore : 0;
  // A1-low: cannot produce "be" reliably → Unit 1
  if (g < 0.3) return 1;
  // Early A1: can handle be, possessives, simple nouns → Unit 5
  if (g < 0.5) return 5;
  // Mid A1: present simple productive, daily vocabulary → Unit 9
  if (g < 0.7) return 9;
  // Late A1: present simple, can, basic past → Unit 15
  return 15;
}

// Mark skipped units and their vocabulary as "assumed known" (§E.3).
function applyPlacementEntry(store, entryUnit) {
  const skipped = [];
  const wordMastery = { ...(store.wordMastery || {}) };
  for (const rec of UNIT_RECORDS) {
    if (rec.unit >= entryUnit) break;
    skipped.push(rec.unit);
    // Mark all core + extension vocab as assumed
    for (const w of [...rec.coreVocab, ...rec.extensionVocab]) {
      if (!wordMastery[w]) wordMastery[w] = { stage: "assumed", source: "placement" };
    }
  }
  return {
    ...store,
    currentUnit: entryUnit,
    lessonInUnit: 1,
    unitStatus: "not_started",
    entryUnit,
    skippedUnits: skipped,
    wordMastery,
    unitHistory: skipped.map(u => ({
      unit: u, lessonsSpent: 0, status: "assumed",
      completedDate: new Date().toISOString().slice(0, 10)
    })),
  };
}

async function loadMemoryStore() {
  const s = await loadKey("esl-memory-store", DEFAULT_MEMORY_STORE);
  const o = s && typeof s === "object" ? s : {};
  // Migration: stores written before the split still carry the log inline.
  // It is read from there once, then moves to its own key on the next save.
  const separate = await loadKey(LESSON_LOG_KEY, null);
  const log = Array.isArray(separate) ? separate : (Array.isArray(o.lessonLog) ? o.lessonLog : []);
  // Coerce every field to its expected type. `{...DEFAULT, ...s}` only backfills
  // MISSING keys — a corrupted or tampered store where a field is the wrong type
  // (e.g. wordMastery:null, questionLog:42) would otherwise crash the helpers.
  return {
    wordMastery: o.wordMastery && typeof o.wordMastery === "object" ? o.wordMastery : {},
    lessonLog: log,
    diaryFeedbackLog: Array.isArray(o.diaryFeedbackLog) ? o.diaryFeedbackLog : [],
    questionLog: Array.isArray(o.questionLog) ? o.questionLog : [],
    // Migration: a store written before these existed falls back to the log,
    // which is no worse than the old behaviour and self-corrects from the next
    // lesson onwards.
    lessonsCompleted: Number.isFinite(o.lessonsCompleted) ? o.lessonsCompleted : log.length,
    firstLessonDate: typeof o.firstLessonDate === "string" ? o.firstLessonDate
      : (log.length ? (log[log.length - 1] || {}).date || null : null),
  };
}
/* The log is written ONLY when it has actually changed. Every mem* helper
   spreads the store, so lessonLog keeps its array reference unless
   memRecordLesson replaced it — a reference check is therefore exact. */
function saveMemoryStore(store, prev) {
  const { lessonLog, ...rest } = store;
  saveKey("esl-memory-store", rest);
  if (!prev || prev.lessonLog !== lessonLog) saveKey(LESSON_LOG_KEY, lessonLog || []);
  // Server-side sync (Part 4/5 of the persistence build): every memory
  // update — word mastery, lesson log, sequencer state — schedules a
  // debounced push to Supabase. Covers lesson-complete automatically,
  // since finish() advances the sequencer through this same function.
  if (currentStudentId) scheduleMemoryPush(currentStudentId);
}

// A word progresses new -> seen -> practised -> confident -> mastered on a
// streak of correct answers, and steps back to "seen" (not all the way to
// "new") on a miss — one slip shouldn't erase that they've met the word before.
function memBumpWordMastery(store, term, ok, date) {
  const key = (term || "").trim().toLowerCase();
  if (!key) return store;
  const cur = store.wordMastery[key] || { stage: "new", correctStreak: 0, timesSeen: 0, lastSeen: null };
  const timesSeen = cur.timesSeen + 1;
  const correctStreak = ok ? cur.correctStreak + 1 : 0;
  const stage = MASTERY_STAGES[Math.min(correctStreak, 4)] === "new" ? (timesSeen > 0 ? "seen" : "new") : MASTERY_STAGES[Math.min(correctStreak, 4)];
  return { ...store, wordMastery: { ...store.wordMastery, [key]: { stage, correctStreak, timesSeen, lastSeen: date } } };
}
// Registers a word Leo hasn't scored yet (e.g. just looked up) without
// touching its stage if it's already being tracked.
function memTouchWord(store, term) {
  const key = (term || "").trim().toLowerCase();
  if (!key || store.wordMastery[key]) return store;
  return { ...store, wordMastery: { ...store.wordMastery, [key]: { stage: "new", correctStreak: 0, timesSeen: 0, lastSeen: null } } };
}
function memMasteryStage(store, term) {
  const e = store.wordMastery[(term || "").trim().toLowerCase()];
  return e ? e.stage : "new";
}
// Weakest-first ordering, so review and lesson generation can prioritise
// words that actually need practice over ones already mastered.
function memSortByMasteryAsc(items, store, getTerm) {
  return [...items].sort((a, b) => MASTERY_RANK[memMasteryStage(store, getTerm(a))] - MASTERY_RANK[memMasteryStage(store, getTerm(b))]);
}
function memRecordLesson(store, entry) {
  const today = todayStr();
  return {
    ...store,
    /* Bug fix: this was the one lessonLog write site in the file that
       never guarded against the field being absent, unlike every read
       site (`memoryStore.lessonLog || []` appears throughout). A
       student whose memory store lacks this field hit an uncaught
       "not iterable" TypeError at the exact moment a lesson finished —
       a render-time throw that blanks the whole screen with no way
       forward. Same guard as everywhere else, just applied here too. */
    lessonLog: [{ ...entry, date: today }, ...(store.lessonLog || [])].slice(0, LESSON_LOG_CAP),
    lessonsCompleted: (store.lessonsCompleted || 0) + 1,
    firstLessonDate: store.firstLessonDate || today,
  };
}
function memRecordDiaryFeedback(store, fb) {
  // Same fix, same reason — this had the identical unguarded pattern,
  // just never triggered yet.
  return { ...store, diaryFeedbackLog: [{ ...fb, date: todayStr() }, ...(store.diaryFeedbackLog || [])].slice(0, DIARY_FEEDBACK_CAP) };
}
// M6: remember what the learner asks Leo about, so future lessons can reference
// their real questions. Deduped (case-insensitive) and capped so nothing bloats.
function memRecordQuestion(store, text) {
  const q = (text || "").trim();
  if (!q) return store;
  const log = (store.questionLog || []).filter((e) => e.text.toLowerCase() !== q.toLowerCase());
  return { ...store, questionLog: [{ text: q.slice(0, 120), date: todayStr() }, ...log].slice(0, 12) };
}

function computeStreak(dates) {
  const set = new Set(dates);
  let streak = 0;
  const d = new Date();
  if (!set.has(d.toISOString().slice(0, 10))) d.setDate(d.getDate() - 1);
  while (set.has(d.toISOString().slice(0, 10))) {
    streak++;
    d.setDate(d.getDate() - 1);
  }
  return streak;
}

/* ---------------- Loading indicator ---------------- */

/* MOTION CHARACTER SPEC §3 — the drawn rule.
   One element wherever the app waits: the completion tick's own mechanism at
   smaller scale. stroke-dashoffset travels from full length to zero, once,
   then rests. It never loops — a looping animation says "waiting", and Leo
   does not need to fill silence, because Leo can talk. If the wait continues
   the SENTENCE changes and the rule redraws BECAUSE the sentence changed, so
   movement is always the consequence of something actually happening. */

/* Loading lines now come from LOADING_MESSAGES (lesson-tightening item 4), pulled per student level by WaitIndicator. The old tool-apologising lines were retired — they failed the Toolbox Test. */

/* §3.2 timing table. 0-400ms: nothing at all — a loader that flashes for a
   fifth of a second is noise. 400ms: the rule draws once. 4s and 9s: the
   line changes. No fourth stage; that would be fidgeting in words.
   The ladder is NOT suppressed under reduced motion (§5) — a changing
   sentence is information, not movement. */
function useWaitStage() {
  const [stage, setStage] = useState(0);
  useEffect(() => {
    const a = setTimeout(() => setStage(1), 400);
    const b = setTimeout(() => setStage(2), 4000);
    const c = setTimeout(() => setStage(3), 9000);
    return () => { clearTimeout(a); clearTimeout(b); clearTimeout(c); };
  }, []);
  return stage;
}

function DrawnRule({ inline }) {
  const len = inline ? 28 : 48;
  const w = inline ? 2.5 : 3;
  return (
    <svg className="drawn-rule" width={len} height={w * 2} viewBox={`0 0 ${len} ${w * 2}`} aria-hidden="true">
      <line x1="0" y1={w} x2={len} y2={w} className="drawn-rule-line"
        strokeWidth={w} style={{ strokeDasharray: len, strokeDashoffset: len }} />
    </svg>
  );
}

/* The rule and the sentence together. Changing the key remounts both, which is
   what redraws the rule when the line changes (§3.2).
   §6: the mark is always aria-hidden and the sentence always live — the motion
   is never the announcement. */
function WaitIndicator({ label, inline, className, stage: forced, level }) {
  const own = useWaitStage();
  const set = LOADING_MESSAGES[level] || LOADING_MESSAGES.A2 || [];
  const [offset] = useState(() => (set.length ? Math.floor(Math.random() * set.length) : 0));
  const stage = forced === undefined ? own : forced;
  if (stage === 0) return null;
  // Leo preparing (lesson-tightening item 4): rotate the level's set; stages 2 and 3 never repeat the same line.
  const text = stage >= 2 && set.length
    ? set[(offset + (stage - 2)) % set.length]
    : label;
  const cls = (inline ? "wait-inline" : "wait-block") + (className ? " " + className : "");
  return (
    <div className={cls} role="status" aria-live="polite">
      <DrawnRule key={stage} inline={inline} />
      {text && <p className="wait-label text-leo" key={"t" + stage}>{text}</p>}
    </div>
  );
}

function LeoLoader({ label, level }) {
  return <WaitIndicator label={label} level={level} />;
}

/* Lesson Planning Wait Specification v1 (NEWDESIGN, 9 Aug 2026), §3.3.
   A separate pool and dwell timer from LOADING_MESSAGES / WaitIndicator's
   4s/9s ladder (§4) — that ladder is tuned for short waits (section retries,
   chat typing) and stays untouched. This pool is for the ~2-minute blueprint
   wait: the same "text changes -> DrawnRule redraws" mechanism, given more
   sentences to say over a much longer silence. */
const PLANNING_WAIT_LINES = [
  "Let me plan something for you…",
  "Thinking about what you need most today.",
  "Choosing words you'll actually use.",
  "Picking examples from real life.",
  "Building today around where you're headed.",
  "Getting the right words ready for you.",
  "Making sure today follows on from last time.",
  "Shaping this around your life.",
  "Good lessons take a moment — nearly there.",
  "Putting today together, just for you.",
  "Thinking like your teacher, not a machine.",
  "Finding the version of this that fits you.",
];

function shuffleOnce(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

/* §3.3: one line visible at a time, 8s dwell, DrawnRule redraws on every
   change via the key. Pool order is shuffled once per lesson load so two
   students starting together don't see identical timing. Wraparound never
   repeats the immediately-preceding line — guaranteed here because every
   pool entry is a distinct string, so index i and i+1 (mod length) can never
   read the same text, including the wrap from last back to first.
   §3.5: reduced motion is handled entirely by the existing .wait-label /
   .drawn-rule-line media query — the interval still advances every 8s
   regardless, so the line keeps changing; only the entrance transform and
   the stroke-draw animation are suppressed. No new CSS needed here. */
function PlanningWaitCycle() {
  const [order] = React.useState(() => shuffleOnce(PLANNING_WAIT_LINES));
  const [idx, setIdx] = React.useState(0);
  React.useEffect(() => {
    const t = setInterval(() => setIdx((i) => (i + 1) % order.length), 8000);
    return () => clearInterval(t);
  }, [order.length]);
  return (
    <div className="wait-block" role="status" aria-live="polite">
      <DrawnRule key={idx} />
      <p className="wait-label text-leo" key={"pw" + idx}>{order[idx]}</p>
    </div>
  );
}

/* §3.2: Path B keeps the existing 400ms/4s/9s ladder untouched (rendered by
   LeoLoader/WaitIndicator below), then hands off to PlanningWaitCycle once
   that ladder would otherwise have gone static. */
function PlanningWaitPathB({ label, level }) {
  const [handoff, setHandoff] = React.useState(false);
  React.useEffect(() => {
    const t = setTimeout(() => setHandoff(true), 9000);
    return () => clearTimeout(t);
  }, []);
  if (handoff) return <PlanningWaitCycle />;
  return <LeoLoader label={label} level={level} />;
}

/* The whole row is gated, not just the rule: an empty padded bubble with an
   avatar beside it IS an indicator, and §3.2 says nothing at all appears
   under 400ms. The stage is owned here and passed down so the inner rule
   does not restart the clock. */
function ChatTypingRow() {
  const stage = useWaitStage();
  if (stage === 0) return null;
  return (
    <div className="bubble-row row-bot">
      <span className="bot-avatar-leo">L</span>
      <div className="bubble bubble-bot typing"><WaitIndicator inline stage={stage} /></div>
    </div>
  );
}

/* ---------------- small UI bits ---------------- */

function Spinner({ label }) {
  return <WaitIndicator label={label || "Thinking…"} inline />;
}

function Card({ children, className }) {
  return <div className={"card " + (className || "")}>{children}</div>;
}

function SectionTitle({ children, sub }) {
  return (
    <div className="section-title">
      <h2>{children}</h2>
      {sub && <p className="sub">{sub}</p>}
    </div>
  );
}

/* ================= PAGES ================= */

/* ---- Sydney skyline: Leo's own artwork, recoloured to black ---- */
const SKYLINE_IMG = "data:image/png;base64,";

function SkylineSketch({ animate }) {
  return (
    <img
      src={SKYLINE_IMG}
      className={"sky-img" + (animate ? " sky-anim" : "")}
      alt="Line drawing of the Sydney skyline: Sydney Tower, Crown, the Opera House and the Harbour Bridge"
    />
  );
}

/* ---------------- Today's journey (Phase 3 & 7) ----------------
   ONE place that defines what "today" consists of, in order, and how each
   step's completion/gating is decided. Adding, reordering or gating a daily
   activity means editing this array — HomeScreen just renders it. */
const DAILY_JOURNEY = [
  { key: "diary", label: "Diary page", icon: PenLine, page: "diary", isDone: (t) => t.diaryFilled, ctaLabel: "Write today's diary" },
  { key: "task", label: "Leo's Lesson", icon: GraduationCap, page: "task", isDone: (t) => t.taskDone, ctaLabel: "Start today's lesson" },
  { key: "vocab", label: "Word review", icon: RotateCcw, page: "vocab", isDone: (t) => t.vocabDone, isGated: (t) => t.wordCount < 3, gateLabel: "Save a word first", ctaLabel: "Review your words" },
];

/* Written-out date, composed rather than localised so it always reads
   "Tuesday, 21 July" in British English regardless of device locale. */
const DAY_NAMES = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const longDate = (d) => `${DAY_NAMES[d.getDay()]}, ${d.getDate()} ${MONTH_NAMES[d.getMonth()]} ${d.getFullYear()}`;

/* Greeting is English, not L1: an Australian teacher greets a student in
   English every morning, and that is the immersion the student came for.
   L1 keeps its real jobs elsewhere — the "Hi, I'm Leo" page, dictionary
   glosses, pronunciation notes.
   NOTE: there is deliberately no "Good night". In English that is a
   farewell, never a greeting; a student sitting down to study at 10pm
   would be said goodbye to, and would learn the phrase wrong. Evening
   covers the whole night. */
const timeGreeting = (d) => {
  const h = d.getHours();
  if (h < 12) return "Good morning";
  if (h < 18) return "Good afternoon";
  return "Good evening";
};

const clockTime = (d) => {
  const h = d.getHours();
  const h12 = h % 12 === 0 ? 12 : h % 12;
  return `${h12}:${String(d.getMinutes()).padStart(2, "0")} ${h < 12 ? "am" : "pm"}`;
};

/* Isolated so the minute tick redraws ONLY this block. The continuity line
   and the Today card sit outside it and are never recomputed by the clock.
   Once per minute, not per second: a per-second counter is the most noticed
   motion possible on a still screen, and motion should be felt, not noticed.
   The first tick is aligned to the next minute boundary so the displayed
   time is never up to 59 seconds stale. */
function HomeGreeting({ name }) {
  const [now, setNow] = useState(() => new Date());
  useEffect(() => {
    let interval;
    const align = setTimeout(() => {
      setNow(new Date());
      interval = setInterval(() => setNow(new Date()), 60000);
    }, 60000 - (Date.now() % 60000));
    return () => { clearTimeout(align); if (interval) clearInterval(interval); };
  }, []);
  return (
    <>
      <h1 className="greet-hello">{timeGreeting(now)}, {name}</h1>
      <p className="greet-date">{longDate(now)} <span className="greet-clock">{clockTime(now)}</span></p>
    </>
  );
}

/* Line 3 of the greeting. Sourced from the lesson log — never invented, never
   generic. Returns null whenever Leo has nothing specific to say, and the line
   is then omitted entirely (spec A3.2). "Yesterday" is a factual claim, so the
   wording is derived from the real gap rather than assumed. */
function continuityLine(lessonLog) {
  const last = (lessonLog || [])[0];
  if (!last || !last.date) return null;
  const gap = Math.round((new Date(todayStr()).getTime() - new Date(last.date).getTime()) / 86400000);
  if (gap < 1 || gap > 13) return null;            // today, future, or too long ago
  const when = gap === 1 ? "Yesterday" : "Last time";
  const tc = (last.tomorrowConnection || "").trim();
  if (tc) return `${when} I said today would build on this: ${tc}`;
  const sc = (last.scenario || "").trim();
  if (sc) return `${when} we practised ${sc.charAt(0).toLowerCase() + sc.slice(1)}. Let's build on that.`;
  return null;
}

/* "What Leo has noticed" — prose, not statistics. Omitted entirely when there
   is nothing true to say, on the same principle as the continuity line.

   PERMANENT DESIGN RULE — DO NOT REMOVE THIS COMMENT:
   There must never be a streak counter widget, badge, flame icon, or any
   visual element that displays the numeric streak to the student in any
   tab, card, banner, or component. The streak is used ONLY as a gate here
   (stats.streak >= 2) to decide whether to include one prose sentence.
   A counter widget was explicitly prohibited by the Psychological Design
   Audit (Genesis, Aug 2026) and that ruling does not expire. If a future
   session proposes adding streak UI in any form, this comment is the
   standing record of why it must not happen. */
function noticedLine(stats) {
  const bits = [];
  const top = ((stats && stats.errorTally) || [])[0];
  if (top && top[0]) bits.push(`You're working on ${top[0]} at the moment.`);
  if (stats && stats.streak >= 2) bits.push(`${stats.streak} days running.`);
  return bits.length ? bits.join(" ") : null;
}

// The single source of truth for "did the student do X today?" — every page
// that needs this reads it from here rather than keeping its own copy.
function computeTodayProgress({ diaryPages, todayDone, words, heard }) {
  const tp = diaryPages[todayStr()];
  return {
    diaryFilled: !!(tp && ((tp.skills && tp.skills.length) || tp.homework || tp.notes || tp.skillsDetail)),
    taskDone: !!todayDone.task,
    vocabDone: !!todayDone.vocab,
    wordCount: words.length + heard.length,
  };
}

/* ── Navigation (A1) ──
   Four persistent destinations replacing the nine-tile grid (spec A4).
   Diary, Leo's Lesson and Word review are NOT tiles — they live in the Today
   card. Diary and Leo's Lesson are sub-screens of Today; Word review is a
   section of Words, so a student can return to it after today's row is done.
   Tabs whose `sections` length is 1 render no segmented control. */
const TABS = [
  { id: "today", label: "Today", icon: Home, sections: [{ page: null, label: "Today" }] },
  { id: "ask", label: "Ask Leo", icon: MessageCircle, sections: [
    { page: "questions", label: "English" },
    { page: "australia", label: "Australia" },
  ] },
  { id: "words", label: "Words", icon: Book, sections: [
    { page: "dictionary", label: "Dictionary" },
    { page: "vocab", label: "Word review" },
    { page: "heard", label: "Heard today" },
  ] },
  { id: "progress", label: "Progress", icon: TrendingUp, sections: [
    { page: "progress", label: "Progress" },
    { page: "placement", label: "Level Check" },
  ] },
];

/* Screens that belong to a tab but are not sections of it — reached from the
   Today card, and returned from via the header back control. */
const TAB_SUBSCREENS = { diary: "today", task: "today" };

const tabOfPage = (p) => {
  if (TAB_SUBSCREENS[p]) return TAB_SUBSCREENS[p];
  const t = TABS.find((x) => x.sections.some((sec) => sec.page === p));
  return t ? t.id : "today";
};
const defaultPageOfTab = (id) => (TABS.find((t) => t.id === id) || TABS[0]).sections[0].page;

function TabBar({ tab, onSelect }) {
  return (
    <nav className="tab-bar" role="navigation" aria-label="Main">
      {TABS.map(({ id, label, icon: Icon }) => (
        <button key={id} className={"tab-item" + (tab === id ? " tab-item-on" : "")}
          aria-current={tab === id ? "page" : undefined} onClick={() => onSelect(id)}>
          <Icon size={22} />
          <span className="tab-item-label">{label}</span>
        </button>
      ))}
    </nav>
  );
}

function SectionSwitch({ sections, page, onSelect }) {
  return (
    <div className="seg-control" role="tablist">
      {sections.map((sec) => (
        <button key={String(sec.page)} role="tab" aria-selected={page === sec.page}
          className={"seg-item" + (page === sec.page ? " seg-item-on" : "")}
          onClick={() => onSelect(sec.page)}>{sec.label}</button>
      ))}
    </div>
  );
}

/* Genesis ruling, 2nd-pass walkthrough: "app open" was always meant to
   trigger the resume moment (§1.5), not just navigating in from home —
   Phase 7 only built the latter half. Rather than touching the app's
   boot-sequence routing (auth/onboarding/placement gating, a different
   risk class), this is a self-contained banner on the home screen
   itself: it reads the SAME storage key LessonPage already reads, and
   is the first thing the student sees on reopening the app, without
   changing what decides that HomeScreen renders in the first place. */
function ContinueLessonBanner({ onOpen }) {
  const [pending, setPending] = useState(null); // { stageLabel } | null
  const [dismissed, setDismissed] = useState(false);
  useEffect(() => {
    let cancelled = false;
    (async () => {
      const saved = await loadKey("esl-task:" + todayStr(), null);
      if (cancelled || !saved || !saved.blueprint) return;
      const done = !!(saved.status && saved.status.done);
      if (done || !(saved.stage > 0)) return;
      const stage = LESSON_STAGES[saved.stage];
      setPending({ stageLabel: (stage && stage.label) || "your lesson" });
    })();
    return () => { cancelled = true; };
  }, []);
  if (!pending || dismissed) return null;
  return (
    <div className="continue-banner leo-accent">
      <p className="continue-banner-line text-leo">
        {/* §1.5 — names only the held stage, never invents progress. */}
        Welcome back. We were in the middle of {String(pending.stageLabel).toLowerCase()} — let's pick it up from there.
      </p>
      <div className="continue-banner-actions">
        <button className="primary-btn" onClick={() => onOpen("task")}>Continue</button>
        <button className="ghost-btn" onClick={() => setDismissed(true)}>Not now</button>
      </div>
    </div>
  );
}

function HomeScreen({ profile, onOpen, animate, todayInfo, continuity, noticed }) {
  const nextItem = DAILY_JOURNEY.find((item) => !item.isDone(todayInfo) && !(item.isGated && item.isGated(todayInfo)));
  return (
    <div className="home-screen">
      {/* The mark is unanchored: deleting this one element leaves the layout intact. */}
      <div className="brand-mark-sm"><WhiteboardLogo width={132} /></div>

      <ContinueLessonBanner onOpen={onOpen} />

      <div className="home-greet">
        <HomeGreeting name={profile.name} />
        {continuity && <p className="greet-cont leo-accent">{continuity}</p>}
      </div>

      <div className="leo-card today-card">
        {DAILY_JOURNEY.map((item) => {
          const done = item.isDone(todayInfo);
          const gated = item.isGated && item.isGated(todayInfo);
          const Icon = item.icon;
          return (
            <button key={item.key} className="tc-row" disabled={gated}
              onClick={() => onOpen(item.page)}
              aria-label={done ? `${item.label} — done. Open again.` : item.label}>
              <Icon size={20} className="tc-icon" />
              <span className="tc-label">{item.label}</span>
              {done && <span className="tc-done"><Check size={16} /> Done</span>}
              {!done && gated && <span className="tc-gate">{item.gateLabel}</span>}
            </button>
          );
        })}
        {nextItem ? (
          <button className="primary-btn wide tc-cta" onClick={() => onOpen(nextItem.page)}>{nextItem.ctaLabel}</button>
        ) : (
          <p className="tc-alldone">That's everything for today. See you next time.</p>
        )}
      </div>

      {noticed && (
        <button className="noticed-card" onClick={() => onOpen("progress")}>{noticed}</button>
      )}

      <div className="home-skyline"><SkylineSketch animate={animate} /></div>
    </div>
  );
}

/* ---------------- Progress ---------------- */

function ProgressPage({ stats }) {
  const hasData = stats.entries > 0 || stats.words > 0 || stats.tasks > 0;
  return (
    <div>
      {/* Item 6 — Psychological Design Audit (Genesis, Aug 2026):
          §4.2 descriptive/no-numerics/no-CTA empty state.
          Stat-grid only renders when at least one count is real.
          A grid of zeroes is a numeric empty state, not a progress report. */}
      {hasData && (
        <div className="stat-grid">
          <Card className="stat">
            <div className="stat-num">{stats.streak}</div>
            <div className="stat-label">day streak</div>
          </Card>
          <Card className="stat">
            <BookOpen size={20} className="euca" />
            <div className="stat-num">{stats.entries}</div>
            <div className="stat-label">diary pages</div>
          </Card>
          <Card className="stat">
            <Book size={20} className="euca" />
            <div className="stat-num">{stats.words}</div>
            <div className="stat-label">words learnt</div>
          </Card>
          <Card className="stat">
            <Gamepad2 size={20} className="euca" />
            <div className="stat-num">{stats.tasks}</div>
            <div className="stat-label">tasks done</div>
          </Card>
        </div>
      )}

      {stats.skillTally && stats.skillTally.length > 0 && (
        <Card>
          <h3>Your skills balance</h3>
          <p className="muted">Which skills you practise most. A balanced picture means stronger English overall.</p>
          {stats.skillTally.map(([skill, count]) => (
            <div key={skill} className="bar-row">
              <span className="bar-label">{skill}</span>
              <div className="bar-track">
                <div className="bar-fill" style={{ width: Math.min(100, (count / stats.skillTally[0][1]) * 100) + "%" }} />
              </div>
              <span className="bar-count">{count}</span>
            </div>
          ))}
        </Card>
      )}

      {stats.errorTally.length > 0 && (
        <Card>
          <h3>Your language patterns</h3>
          <p className="muted">The areas Leo's feedback mentions most — watch them shrink over time.</p>
          {stats.errorTally.map(([type, count]) => (
            <div key={type} className="bar-row">
              <span className="bar-label">{type}</span>
              <div className="bar-track">
                <div className="bar-fill" style={{ width: Math.min(100, count * 20) + "%" }} />
              </div>
              <span className="bar-count">{count}</span>
            </div>
          ))}
        </Card>
      )}

      {!hasData && (
        <Card>
          <p className="muted">This is where your progress lives — lessons, words, and skills, building up over time.</p>
        </Card>
      )}
    </div>
  );
}

/* ---------------- Diary ---------------- */

const EMPTY_PAGE = { skills: [], skillsDetail: "", homework: "", notes: "", feedback: null, resources: null };
const SKILLS = [
  ["Reading", "📖"], ["Listening", "🎧"], ["Speaking", "🗣️"], ["Writing", "✍️"],
  ["Grammar", "🧩"], ["Vocabulary", "📚"], ["Pronunciation", "🔊"],
];

function formatDate(d) {
  return new Date(d + "T12:00:00").toLocaleDateString("en-AU", { weekday: "long", day: "numeric", month: "long", year: "numeric" });
}

function DiaryPage({ profile, memory, leoMemory, pages, setPages, markActivity, addErrors }) {
  const today = todayStr();
  const dates = React.useMemo(() => {
    const s = new Set(Object.keys(pages));
    s.add(today);
    return [...s].sort();
  }, [pages, today]);

  const [current, setCurrent] = useState(today);
  const [dir, setDir] = useState("left");
  const touchX = React.useRef(null);

  const page = pages[current] || EMPTY_PAGE;
  const i = dates.indexOf(current);

  const [homeworkDraft, setHomeworkDraft] = useState(page.homework);
  const [notesDraft, setNotesDraft] = useState(page.notes);
  const [detailDraft, setDetailDraft] = useState(page.skillsDetail || "");

  /* ── Draft autosave ──────────────────────────────────────────────────────
     A student's own writing is the most personal thing Ask Leo holds, and
     before this a mistap on the tab bar discarded it. Drafts are stored
     SEPARATELY from the diary page, never merged into it, because
     computeTodayProgress treats any text on the page as a finished entry —
     autosaving into the page would mark the day's Diary row Done on the first
     keystroke and tell the student they had finished something they had not.
     Save alone commits, and Save alone completes the day.
     The net stays silent: no "draft saved" indicator. The Save button
     remaining enabled is the only signal that work is uncommitted. */
  const DRAFTS_KEY = "esl-diary-drafts";
  const draftsRef = React.useRef({});           // a ref, not state: writing a
  const [draftsLoaded, setDraftsLoaded] = useState(false); // draft must not re-render mid-typing

  useEffect(() => { (async () => {
    draftsRef.current = (await loadKey(DRAFTS_KEY, {})) || {};
    setDraftsLoaded(true);
  })(); }, []);

  // Apply the stored draft for this date, falling back to the saved page.
  useEffect(() => {
    if (!draftsLoaded) return;
    const d = draftsRef.current[current];
    setHomeworkDraft(d ? d.homework : page.homework);
    setNotesDraft(d ? d.notes : page.notes);
    setDetailDraft(d ? d.detail : (page.skillsDetail || ""));
  }, [current, draftsLoaded]);

  // Latest values, so the unmount flush writes what is actually on screen.
  const latestRef = React.useRef(null);
  latestRef.current = { date: current, page, homework: homeworkDraft, notes: notesDraft, detail: detailDraft };

  const writeDraft = async (v) => {
    if (!v) return;
    const differs = v.detail !== (v.page.skillsDetail || "") || v.homework !== v.page.homework || v.notes !== v.page.notes;
    if (differs) draftsRef.current[v.date] = { homework: v.homework, notes: v.notes, detail: v.detail };
    else delete draftsRef.current[v.date];
    await saveKey(DRAFTS_KEY, draftsRef.current);
  };

  useEffect(() => {
    if (!draftsLoaded) return;
    const t = setTimeout(() => { writeDraft(latestRef.current); }, 800);
    return () => clearTimeout(t);
  }, [homeworkDraft, notesDraft, detailDraft, current, draftsLoaded]);

  // Final write on leaving: without it, a mistap inside the debounce window
  // still loses the last sentence typed — the one most likely to matter.
  useEffect(() => () => { writeDraft(latestRef.current); }, []);

  const [busy, setBusy] = useState(null);
  const [saved, setSaved] = useState(null); // 'hw' | 'notes'

  const flashSaved = (which) => { setSaved(which); setTimeout(() => setSaved(null), 2000); };

  const update = async (patch, activity) => {
    const next = { ...pages, [current]: { ...page, ...patch } };
    setPages(next);
    await saveKey("esl-diary-pages", next);
    if (currentStudentId) scheduleMemoryPush(currentStudentId);
    if (activity) await markActivity();
  };

  const goto = (delta) => {
    const n = dates[i + delta];
    if (!n) return;
    setDir(delta > 0 ? "left" : "right");
    setCurrent(n);
  };

  const toggleSkill = (s) => {
    const cur = page.skills || [];
    const next = cur.includes(s) ? cur.filter((x) => x !== s) : [...cur, s];
    update({ skills: next }, true);
  };
  const dirty = detailDraft !== (page.skillsDetail || "") || homeworkDraft !== page.homework || notesDraft !== page.notes;
  const savePage = async () => {
    await update({ skillsDetail: detailDraft, homework: homeworkDraft, notes: notesDraft }, true);
    // Committed: drop the draft so it can never shadow the saved page.
    delete draftsRef.current[current];
    await saveKey(DRAFTS_KEY, draftsRef.current);
    flashSaved("page");
  };

  const getResources = async () => {
    setBusy("resources");
    try {
      const skillsDesc = (page.skills || []).length ? `Skills practised: ${page.skills.join(", ")}${page.skillsDetail || detailDraft ? ` — in detail: "${page.skillsDetail || detailDraft}"` : ""}.` : "Skills practised: none listed.";
      const raw = await askClaude(
        `An adult ${levelFor(profile)} ESL student in Australia (first language: ${LANGS[profile.lang].english}) logged today's English class work.\n${skillsDesc}\nHomework: "${page.homework || homeworkDraft || "none listed"}".\nRecommend 3-4 free online study resources matched to these exact topics, prioritising anything they found hard. ONLY use these trusted sites: learnenglish.britishcouncil.org, bbc.co.uk/learningenglish, dictionary.cambridge.org, perfect-english-grammar.com, test-english.com, writeandimprove.com. Prefer stable section or hub URLs (e.g. the grammar reference section) over deep article links that might not exist. Respond ONLY with JSON, no fences: {"resources":[{"title":"short name","site":"e.g. British Council","url":"https://...","why":"one line linking it to their task, in simple English"}]}`,
        { intent: "diary_resources" }
      );
      await update({ resources: parseJSON(raw).resources }, true);
    } catch { alert("I'm having trouble with that one — let me try again."); }
    setBusy(null);
  };

  const inviteFeedback = async () => {
    setBusy("feedback");
    try {
      const raw = await askClaude(
        `You are Leo, a kind, encouraging Australian English teacher who knows this student well (${memory}). Celebrate strengths before mistakes, and only mention the mistakes that matter most. Teach like an expert: rather than only correcting, give a gentle HINT that helps them fix one thing themselves, and where their English is already good, UPGRADE it to more natural or more Australian phrasing. The student wrote this diary entry:\n\n"${notesDraft}"\n\nRespond ONLY with JSON, no markdown fences, exactly this shape:\n{"praise":"one specific, genuine thing they did well in English — name or quote the actual words you are praising, so it could not have been written about anyone else's entry","reformulation":"a natural, native-like version of their entry, keeping their meaning and first person voice","errorTypes":["up to 3 items from this list only: ${ERROR_TYPES.join(", ")}, or an empty array if none"],"tip":"one short, friendly coaching tip in simple English that either prompts them to self-correct ONE specific thing (a hint, not the full answer) or upgrades a good sentence into more natural English"}${narrationGuidance(profile.level, "corrective")}`,
        { intent: "diary_feedback" }
      );
      const fb = parseJSON(raw);
      await update({ notes: notesDraft, feedback: fb }, true);
      if (fb.errorTypes && fb.errorTypes.length) await addErrors(fb.errorTypes);
      leoMemory.recordDiaryFeedback({ praise: fb.praise, tip: fb.tip, errorTypes: fb.errorTypes || [] });
    } catch { alert("I'm having trouble with that one — let me try again."); }
    setBusy(null);
  };

  const canSuggest = homeworkDraft || page.homework || (page.skills || []).length > 0;

  return (
    <div
      onTouchStart={(e) => { touchX.current = e.touches[0].clientX; }}
      onTouchEnd={(e) => {
        if (touchX.current === null) return;
        const dx = e.changedTouches[0].clientX - touchX.current;
        if (dx < -60) goto(1);
        if (dx > 60) goto(-1);
        touchX.current = null;
      }}
    >
      <div className="diary-nav">
        <button className="page-arrow" onClick={() => goto(-1)} disabled={i === 0} aria-label="Previous day">
          <ChevronLeft size={22} />
        </button>
        <div className="date-wrap">
          <span className="date-hand">{formatDate(current)}</span>
          {current === today && <span className="today-badge">Today</span>}
        </div>
        <button className="page-arrow" onClick={() => goto(1)} disabled={i === dates.length - 1} aria-label="Next day">
          <ChevronRight size={22} />
        </button>
      </div>

      <div key={current} className={"diary-page2 page-" + dir}>
        {/* -------- Skills practised -------- */}
        <section className="diary-section" aria-labelledby="lbl-skills">
          <h4 id="lbl-skills" className="diary-label">✅ Skills I practised today</h4>
          <p className="diary-help">Tick everything you worked on today.</p>
          <div className="skills-grid" role="group" aria-labelledby="lbl-skills">
            {SKILLS.map(([s, icon]) => {
              const on = (page.skills || []).includes(s);
              return (
                <button key={s} className={"skill-chip" + (on ? " skill-on" : "")} aria-pressed={on} onClick={() => toggleSkill(s)}>
                  <span aria-hidden="true">{icon}</span> {s} {on && <Check size={15} />}
                </button>
              );
            })}
          </div>
          {(page.skills || []).length > 0 && (
            <>
              <label className="input-label" htmlFor="skills-detail">What did you do, in detail?</label>
              <textarea
                id="skills-detail" className="big-input" rows={2}
                placeholder="e.g. Listened to a podcast about travel, practised ordering food in pairs…"
                value={detailDraft}
                onChange={(e) => setDetailDraft(e.target.value)}
              />
            </>
          )}
        </section>

        {/* -------- Homework -------- */}
        <section className="diary-section" aria-labelledby="lbl-hw">
          <h4 id="lbl-hw" className="diary-label">📚 Homework</h4>
          <p className="diary-help">What do you need to do before next class?</p>
          <label className="sr-only" htmlFor="hw-input">Homework</label>
          <textarea
            id="hw-input" className="big-input" rows={2}
            placeholder="e.g. Workbook page 34, write a paragraph using linking words…"
            value={homeworkDraft}
            onChange={(e) => setHomeworkDraft(e.target.value)}
          />
        </section>

        {/* -------- My diary -------- */}
        <section className="diary-section" aria-labelledby="lbl-notes">
          <h4 id="lbl-notes" className="diary-label">📖 My diary</h4>
          <p className="diary-help">Your private space. How did today go? Leo only reads this if you ask him to.</p>
          <label className="sr-only" htmlFor="notes-input">Diary entry</label>
          <textarea
            id="notes-input" className="big-input ruled-input" rows={5}
            placeholder="How was your day? Write your thoughts in English — what went well, and what was tricky?"
            value={notesDraft}
            onChange={(e) => setNotesDraft(e.target.value)}
          />
          {notesDraft.trim() && !page.feedback && (
            <div className="save-row">
              <button className="ghost-btn" onClick={inviteFeedback} disabled={busy === "feedback"}>
                {busy === "feedback" ? <Spinner label="Leo is reading…" /> : <><Sparkles size={14} /> Ask Leo for feedback</>}
              </button>
            </div>
          )}
          {page.feedback && (
            <div className="feedback">
              <p className="leo-feedback-head"><strong>Leo's feedback</strong></p>
              <p><strong>👏 {page.feedback.praise}</strong></p>
              <p className="muted small">A native speaker might say:</p>
              <p className="reform">{page.feedback.reformulation}</p>
              {page.feedback.errorTypes?.length > 0 && <p className="small">Focus areas: {page.feedback.errorTypes.join(" · ")}</p>}
              <p className="small tip">💡 {page.feedback.tip}</p>
            </div>
          )}
        </section>
      </div>

      <div className="save-page-bar">
        <button className="primary-btn wide" onClick={savePage} disabled={!dirty}>
          {dirty ? <>Save entry <Check size={16} /></> : <>Saved <Check size={16} /></>}
        </button>
        <span className="saved-flash center-flash" role="status">{saved === "page" ? "✓ Your whole page is saved" : ""}</span>
      </div>

      <p className="swipe-hint">← Swipe or use the arrows to turn the pages →</p>

      {canSuggest && !page.resources && (
        <button className="primary-btn wide" onClick={getResources} disabled={busy === "resources"}>
          {busy === "resources" ? <Spinner label="Leo is finding good resources…" /> : <><Sparkles size={15} /> Ask Leo for study resources</>}
        </button>
      )}
      {page.resources && (
        <Card>
          <h3>Leo's study resources for today</h3>
          {page.resources.map((r, j) => (
            <a key={j} className="resource-card" href={r.url} target="_blank" rel="noopener noreferrer">
              <span className="resource-title">{r.title} <span className="pos">{r.site}</span> <ExternalLink size={13} /></span>
              <span className="muted small">{r.why}</span>
            </a>
          ))}
          <button className="ghost-btn" style={{ marginTop: 10 }} onClick={getResources} disabled={busy === "resources"}>
            {busy === "resources" ? <Spinner label="Refreshing…" /> : "Refresh suggestions"}
          </button>
        </Card>
      )}
    </div>
  );
}

/* ---------------- Leo's Lesson (scenario-based) ---------------- */

function diarySummary(pages) {
  const p = pages[todayStr()];
  if (!p) return "";
  const parts = [];
  if (p.skills && p.skills.length) parts.push("Skills practised: " + p.skills.join(", ") + (p.skillsDetail ? ` (detail: ${p.skillsDetail})` : ""));
  if (p.homework) parts.push("Homework: " + p.homework);
  return parts.join(". ");
}

const SCENARIOS = [
  "Ordering at a caf\u00e9", "Enrolling at university", "A visit to the doctor",
  "Renting a flat", "A job interview", "Meeting a new neighbour",
  "Shopping at the supermarket", "Opening a bank account",
  "Catching a train or bus", "Asking for directions in the city",
  "Returning an item to a shop", "Buying medicine at a pharmacy",
  "Booking a haircut", "Calling in sick to work",
  "Asking your manager for time off", "Making small talk at a barbecue",
  "Reporting a problem to your landlord", "Asking a question in class",
  "Booking a GP appointment by phone", "Buying an Opal card",
  "Attending a rental inspection", "Posting a parcel",
  "Being invited to a weekend event", "Ordering food at a food court",
  "Speaking to student support", "Asking about phone plans in a store",
];

/* ---------------- Leo's Lesson: shared building block ---------------- */

// One shared feedback line so all three exercises show Leo's ok/bad
// response the exact same way, instead of each re-implementing it.
/* The same mark as the completion tick, at reading size: one open polyline,
   round cap and join, drawn by stroke-dashoffset, ease-out, once. A student
   meets this after every answer — far more often than the stage tick — so it
   is the highest-frequency mark in the app and it was appearing, not drawn.
   currentColor is deliberate: it inherits .ok exactly as the icon did.
   The cross is NOT drawn. Animating a wrong answer stroke by stroke gives an
   error a flourish and holds the student's eye on it; the tick earns the
   gesture, the cross does not. */
/* SUPERSEDED by ExerciseTick (§2c.1) as of Phase 1 — LeoFeedback was its
   last call site. Kept because it is the small inline tick shape and
   later phases (§3f's correct MCQ row, §2b.6's evidence list) may want
   a mark smaller than 24px. If no phase claims it, delete it then —
   do not let it drift as unread code. */
function DrawnTick({ size = 15 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" className="drawn-tick" aria-hidden="true">
      <path d="M5 12.5 L10 17.5 L19 7" className="drawn-tick-mark" />
    </svg>
  );
}

/* ================================================================
   PHASE 1 — FEEDBACK SYSTEM + SHARED EXERCISE CHROME
   Master Design Specification §2c and §2b.0.

   One feedback language across every exercise type. Built here once so
   the eight (in practice nine) exercise types consume it rather than
   each inventing its own.

   §2c.2, ruled once and applied everywhere:
     - the CORRECT answer appears in --leo-green weight-600, in the
       place where language lives
     - --marker-orange marks LOCATION, never verdict
     - error-red DOES NOT EXIST in the exercise system
     - the student's wrong attempt is de-emphasised, never struck
       through, never shaken
   ================================================================ */

/* §2c.1 — the correct-moment mark. One mark, product-wide: the drawn
   tick at exercise scale. Same paths and same animations as
   StageComplete's tick, in a 24x24 box. NO NEW KEYFRAMES — it reuses
   scRing/scMark, so reduced motion is already handled by the existing
   .sc-tick-ring/.sc-tick-mark media query. */
function ExerciseTick({ size = 24 }) {
  return (
    <svg viewBox="0 0 52 52" width={size} height={size} className="ex-tick" aria-hidden="true">
      <circle className="sc-tick-ring" cx="26" cy="26" r="23" fill="none" strokeWidth="2.5" />
      <path className="sc-tick-mark" fill="none" strokeWidth="3.5" strokeLinecap="round" strokeLinejoin="round" d="M15 27 l7.5 7.5 L38 19" />
    </svg>
  );
}

/* §2b.2 — product-wide input ruling, made once.
   An A1 student typing "are" and receiving "Are" or "arena" from their
   phone is being marked wrong by their keyboard. Spread onto EVERY
   exercise input. The two deliberate exceptions (Type 7 "your own
   word", and the name exchange) use EXERCISE_INPUT_PROPS_PROPER_NOUN
   instead, where the keyboard genuinely helps. */
const EXERCISE_INPUT_PROPS = {
  autoCorrect: "off",
  autoCapitalize: "none",
  spellCheck: false,
  autoComplete: "off",
};
const EXERCISE_INPUT_PROPS_PROPER_NOUN = {
  autoCorrect: "on",
  autoCapitalize: "words",
  spellCheck: false,
  autoComplete: "off",
};

/* §2b.0 — the shared chrome. `Question N of M` plus the dot row, in the
   same grammar the student already learned on the word card.
   M is the LIVE queue length, so a re-queued item makes `7 of 8`
   become `8 of 9` with no announcement (§2c.3). */
function ExerciseChrome({ index, total, label = "Question" }) {
  return (
    <div className="ex-chrome">
      <p className="ex-count">{label} {index + 1} of {total}</p>
      <span className="wc-dots" aria-hidden="true">
        {Array.from({ length: total }, (_, i) => (
          <span key={i} className={"wc-dot" + (i < index ? " wc-dot-done" : i === index ? " wc-dot-current" : "")} />
        ))}
      </span>
    </div>
  );
}

/* §2b.0 — the "I don't know" path, turned into teaching.
   Reveals the answer styled exactly as the wrong-moment: the answer
   arrives as a gift, not a penalty. Counts as not-correct, and
   re-queues on the same rule as any other miss. */
function ShowMeLink({ onShow, shown }) {
  if (shown) return null;
  return (
    <button type="button" className="ex-showme" onClick={onShow}>Show me</button>
  );
}

/* §2c.2 — the wrong-moment, as a component so no call site invents its
   own. The correct answer in the teacher's colour, in the place where
   language lives. Leo's note names the rule. */
function CorrectAnswerReveal({ answer, note, prefix = "The answer is" }) {
  return (
    <p className="ex-reveal text-leo">
      {prefix} <strong className="ex-answer">{answer}</strong>{note ? "." : ""}
      {note ? <span className="ex-reveal-note"> {note}</span> : null}
    </p>
  );
}

/* §2c.3 — the re-attempt rule: wrong once, re-queued once, unannounced.
   The queue is the source of truth for BOTH ordering and the `N of M`
   the chrome displays, which is what lets the count grow silently.
   A second miss retires the item: never a third pass, and never
   "let's try that one again" framing — announcement converts practice
   into remediation, and remediation is a verdict. */
function useExerciseQueue(items) {
  const [queue, setQueue] = useState(() => items.map((it, i) => ({ item: it, key: i, attempt: 1 })));
  const [idx, setIdx] = useState(0);
  const advance = React.useCallback((wasCorrect) => {
    setQueue((q) => {
      const current = q[idx];
      if (wasCorrect || !current || current.attempt >= 2) return q;
      // Re-queue once, at the end of the set, with no ceremony.
      return q.concat([{ item: current.item, key: current.key, attempt: current.attempt + 1 }]);
    });
    setIdx((i) => i + 1);
  }, [idx]);
  return {
    current: queue[idx] ? queue[idx].item : null,
    isRepeat: queue[idx] ? queue[idx].attempt > 1 : false,
    index: idx,
    total: queue.length,
    finished: idx >= queue.length,
    advance,
  };
}


/* §2c.1 / §2c.2 — the single feedback seat.
   Correct: the drawn tick, inline-left of Leo's rule-naming note.
   Wrong: NO icon at all. An X is a verdict, and the wrong-moment is a
   teaching moment — the correct answer in green is what marks it, not
   a cross against the student's attempt. */
function LeoFeedback({ ok, children }) {
  return (
    <p className={(ok ? "ok" : "bad") + " text-leo"} aria-live="polite">
      {ok ? <ExerciseTick size={24} /> : null}
      <span className="lf-text">{children}</span>
    </p>
  );
}

/* ---------------- Vocabulary system (interactive tokens + bottom-sheet card) ---------------- */


// Wraps a single vocabulary item as a tappable token.
// Dotted eucalyptus underline signals interactivity without overwhelming the text.
function VocabToken({ word, onTap }) {
  return (
    <span
      className="vocab-token"
      role="button"
      tabIndex={0}
      aria-label={`Vocabulary: ${word}. Tap to see meaning.`}
      onClick={() => onTap(word)}
      onKeyDown={(e) => (e.key === "Enter" || e.key === " ") && onTap(word)}
    >
      {word}
    </span>
  );
}

// Splits plain text and wraps each vocab match in a VocabToken.
// Multi-word items (e.g. "traffic lights") are sorted longest-first so they
// match before their component words.
function VocabText({ text, vocab = [], onTap }) {
  if (!vocab.length || !text) return <>{text}</>;
  const escaped = [...vocab].sort((a, b) => b.length - a.length)
    .map((w) => w.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  const pattern = new RegExp(`\\b(${escaped.join("|")})\\b`, "gi");
  const parts = text.split(pattern);
  return <>
    {parts.map((part, i) => {
      const match = vocab.find((v) => v.toLowerCase() === part.toLowerCase());
      return match ? <VocabToken key={i} word={part} onTap={onTap} /> : part;
    })}
  </>;
}

// Bottom-sheet vocabulary card — slides up over the lesson content.
function VocabCardSheet({ card, lesson, onClose, onSave, isSaved }) {
  /* Same fix as GrammarBoardSheet, same reason: this sheet shares the
     identical vocab-overlay mechanism and would show the identical
     scroll-trap symptom on a real phone. Hook runs before the early
     return, per React's rules — active only while a card is showing. */
  useBodyScrollLock(!!card);
  if (!card) return null;
  const { word, data, loading } = card;
  const isTarget = lesson && lesson.useWord && lesson.useWord.word.toLowerCase() === word.toLowerCase();
  return (
    <div className="vocab-overlay" onClick={onClose} role="dialog" aria-modal="true" aria-label={`Vocabulary card for ${word}`}>
      <div className="vocab-sheet" onClick={(e) => e.stopPropagation()}>
        <div className="vocab-sheet-handle" />
        <div className="vocab-sheet-scroll">
          <div className="vocab-header">
            <h2 className="vocab-word">{word}</h2>
            {data && (
              <div className="vocab-meta">
                <span className="vocab-ipa">{data.ipa}</span>
                <span className="vocab-chip">{data.pos}</span>
                <span className="vocab-chip vocab-chip-cefr">{data.cefr}</span>
              </div>
            )}
          </div>

          {loading && <LeoLoader label={`I'm looking up "${word}"…`} />}

          {data && !loading && (
            <>
              <p className="vocab-def">{data.definition}</p>

              <div className="vocab-section">
                <p className="vocab-section-title">Examples</p>
                {isTarget && lesson.useWord.example && (
                  <p className="vocab-example vocab-example-today">
                    <span className="vocab-today-tag">Today's lesson</span>
                    {lesson.useWord.example}
                  </p>
                )}
                {data.lessonExample && !isTarget && (
                  <p className="vocab-example vocab-example-today">
                    <span className="vocab-today-tag">Today's lesson</span>
                    {data.lessonExample}
                  </p>
                )}
                {(data.examples || []).map((ex, i) => (
                  <p key={i} className="vocab-example">{ex}</p>
                ))}
              </div>

              {(data.related || []).length > 0 && (
                <div className="vocab-section">
                  <p className="vocab-section-title">Related words</p>
                  <div className="vocab-related">
                    {data.related.map((r, i) => (
                      <span key={i} className="vocab-related-chip">{r}</span>
                    ))}
                  </div>
                </div>
              )}

              <button
                className={isSaved ? "vocab-save-btn vocab-save-btn-saved" : "vocab-save-btn"}
                onClick={isSaved ? undefined : onSave}
                aria-label={isSaved ? `${word} is already in your Word Bank` : `Save ${word} to Word Bank`}
              >
                {isSaved ? "Saved to Word Bank ✓" : "Save to Word Bank"}
              </button>
            </>
          )}
        </div>
        <button className="vocab-close" onClick={onClose} aria-label="Close vocabulary card">✕</button>
      </div>
    </div>
  );
}

/* ==================== LESSON ENGINE v2 (Blueprint architecture) ====================
   Pipeline: Lesson Planner (AI) -> LessonBlueprint -> validateBlueprint (client)
   -> lazy per-section generation (AI, validated, individually regenerable)
   -> section components rendered from a stage array (no switch statements).

   LessonBlueprint shape (single source of truth; every stage consumes it):
   { communicativeObjective, context, cefr, explanation, warmUpQuestions[],
     vocabulary[8 x {word,pos,meaning,ipa,stress,syllables,example,examples[],related[],collocations[]}],
     grammar {point,meaning,form,usage,examples[]}, pronunciation {focus,tips[]},
     mainSkill "reading"|"listening", mission, learningOutcome }
==================================================================================== */

/* ---------- Voice: TTS + speech input, both optional with graceful fallback ---------- */
function speakText(text, opts) {
  try {
    if (!window.speechSynthesis) return false;
    // Strip markdown emphasis so TTS doesn't read "star star word star star"
    const clean = String(text)
      .replace(/\*\*(.+?)\*\*/g, "$1")   // **bold**
      .replace(/__(.+?)__/g, "$1")        // __bold__
      .replace(/\*(.+?)\*/g, "$1")        // *italic*
      .replace(/_(.+?)_/g, "$1")          // _italic_
      /* Bug fix (Leo's live walkthrough): a bare " / " (e.g. "I'm happy /
         I'm sad") was read aloud as "forward slash". This app never uses
         slash for anything but an alternatives separator — never a URL,
         date, or fraction — so " / " -> " or " is always the correct
         reading, not a narrow patch for one screen. */
      .replace(/\s+\/\s+/g, " or ");
    const u = new SpeechSynthesisUtterance(clean);
    u.lang = "en-AU";
    /* Default rate, unchanged. A slower override is opt-in per call —
       contraction forms in the grammar paradigm table are hard to hear
       at the default rate, and only those pass one. */
    u.rate = (opts && typeof opts.rate === "number") ? opts.rate : 0.95;
    const voices = window.speechSynthesis.getVoices();
    const auVoices = voices.filter((v) => v.lang === "en-AU" || v.lang.startsWith("en-AU"));
    if (auVoices.length) u.voice = auVoices[text.length % auVoices.length];
    window.speechSynthesis.cancel();
    window.speechSynthesis.speak(u);
    return true;
  } catch { return false; }
}
const TTS_OK = typeof window !== "undefined" && !!window.speechSynthesis;

function useVoiceInput(onResult) {
  const recRef = React.useRef(null);
  const [listening, setListening] = useState(false);
  const [micError, setMicError] = useState(false);
  const supported = typeof window !== "undefined" && !!(window.SpeechRecognition || window.webkitSpeechRecognition);
  const start = () => {
    if (!supported || listening) return;
    setMicError(false);
    try {
      const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
      const rec = new SR();
      rec.lang = "en-AU"; rec.interimResults = false; rec.maxAlternatives = 1;
      rec.onresult = (e) => { setMicError(false); onResult(e.results[0][0].transcript); };
      rec.onend = () => setListening(false);
      rec.onerror = () => { setListening(false); setMicError(true); };
      recRef.current = rec; setListening(true); rec.start();
    } catch { setListening(false); setMicError(true); }
  };
  return { supported, listening, micError, start };
}

function MicButton({ onText }) {
  const { supported, listening, micError, start } = useVoiceInput(onText);
  if (!supported) return null;
  return (
    <>
      <button className={"mic-btn" + (listening ? " mic-on" : "")} onClick={start} aria-label="Answer by voice" title="Answer by voice">
        🎤{listening ? " Listening…" : ""}
      </button>
      {micError && <span className="muted small" style={{ marginLeft: 6 }}>Didn't catch that — try again or type it.</span>}
    </>
  );
}

/* ---------- Shared stage shell: title, purpose, uniform Skip ---------- */
/* ================================================================
   PHASE 7 — THE LESSON ARC (§1)
   ================================================================ */

/* §1.3 — one header for all seven stages. The EYEBROW does the naming,
   which frees the TITLE to teach: "GRAMMAR" above "Saying who you are"
   rather than burying the stage name in a metadata line.
   A student who cannot read the title still knows a new stage began —
   from the dots, the position, and the precedent of lesson one. The
   layout carries the meaning first. */
function StageHeader({ eyebrow, title, purpose, onSkip, stageIndex, totalStages }) {
  return (
    <div className="stage-header">
      {typeof stageIndex === "number" && totalStages > 0 && (
        <div className="step-dots" aria-hidden="true">
          {Array.from({ length: totalStages }, (_, i) => (
            <span key={i} className={"step-dot" + (i < stageIndex ? " step-dot-done" : i === stageIndex ? " step-dot-current" : "")} />
          ))}
        </div>
      )}
      <div className="sh-row">
        {eyebrow && <span className="sh-eyebrow">{eyebrow}</span>}
        {/* §4.3 — never button-styled (prominence would be an
            invitation), never absent (its absence on one stage would
            imply that stage is mandatory and the others optional). */}
        {onSkip && <button className="sh-skip" onClick={onSkip} aria-label={`Skip ${title || eyebrow || "this stage"}`}>Skip</button>}
      </div>
      {title && <h3 className="sh-title">{title}</h3>}
      {/* Absent purpose renders NOTHING — never a placeholder. */}
      {purpose && <p className="sh-purpose">{purpose}</p>}
    </div>
  );
}

/* Resolve a stage's header from the authored lesson, falling back to
   the system label. The fallback is honest — just plainer. */
function stageHeaderFor(bp, stageId, systemLabel) {
  const authored = (bp && bp.stageHeaders && bp.stageHeaders[stageId]) || null;
  return {
    eyebrow: (authored && authored.eyebrow) || String(systemLabel || "").toUpperCase(),
    title: (authored && authored.title) || systemLabel,
    purpose: (authored && authored.purpose) || null,
  };
}

/* §1.5 — resuming is a continuity moment, not an error state.
   The line names ONLY what the code holds: the stage is always held,
   so "we were in the middle of grammar" is always honest. Never "you
   left", never elapsed-time guilt. The word "back" is as far as it
   goes. */
function ResumeInterstitial({ stageLabel, stageIndex, totalStages, onContinue }) {
  return (
    <div className="resume-card">
      <div className="step-dots" aria-hidden="true">
        {Array.from({ length: totalStages }, (_, i) => (
          <span key={i} className={"step-dot" + (i < stageIndex ? " step-dot-done" : i === stageIndex ? " step-dot-current" : "")} />
        ))}
      </div>
      <p className="leo-accent text-leo resume-line">
        Welcome back. We were in the middle of {String(stageLabel || "your lesson").toLowerCase()} — let's pick it up from there.
      </p>
      <button className="primary-btn wide" onClick={onContinue}>Continue</button>
    </div>
  );
}

function SectionShell({ title, blurb, onSkip, stageIndex, totalStages, header, children }) {
  /* §1.3 — when the lesson supplies an authored header, it replaces the
     old title + metadata line. Generated lessons pass no header and
     render exactly as before. */
  if (header) {
    return (
      <Card>
        <StageHeader {...header} onSkip={onSkip} stageIndex={stageIndex} totalStages={totalStages} />
        <div className="stage-enter-delayed">{children}</div>
      </Card>
    );
  }
  return (
    <Card>
      <div className="stage-head">
        <h3>{title}</h3>
        {onSkip && <button className="skip-btn" onClick={onSkip} aria-label={`Skip ${title}`}>Skip →</button>}
      </div>
      {/* §5 Step indicator dots */}
      {typeof stageIndex === "number" && totalStages > 0 && (
        <div className="step-dots">
          {Array.from({ length: totalStages }, (_, i) => (
            <span key={i} className={"step-dot" + (i < stageIndex ? " step-dot-done" : i === stageIndex ? " step-dot-current" : "")} />
          ))}
        </div>
      )}
      {/* §2.9 Bridge line enters first */}
      {blurb && <p className="muted small stage-enter">{blurb}</p>}
      {/* §2.9 Content enters 0.2s later */}
      <div className="stage-enter-delayed">{children}</div>
    </Card>
  );
}

/* ---------- Exercise self-testing QA (mandatory before presenting to student) ---------- */
// Leo must never present the first version of anything. Before any exercise
// reaches the student, it passes through three checks:
//   1. STUDENT TEST: can this exercise actually be completed?
//   2. TEACHER TEST: is the marking fair and the content appropriate?
//   3. QUALITY TEST: does this genuinely teach something?
/* Grammar alignment: does this exercise actually practise TODAY's structure?
   We build a token set from the point, the form and the examples the student has
   just been shown, then require every question to touch it. Prefix matching
   (5 chars) tolerates the normal inflections — question/questions,
   comparative/comparatives — without needing a stemmer. */
const GRAMMAR_STOPWORDS = new Set([
  // ordinary function words
  "the", "an", "and", "or", "of", "in", "on", "at", "to", "it", "as", "so", "by",
  "this", "that", "these", "those", "with", "there", "here", "just", "very", "also", "any",
  "is", "are", "am", "was", "were", "use", "used", "using",
  // pronouns — they appear in every grammar point ever written, so they discriminate nothing
  "i", "you", "he", "she", "we", "they", "me", "him", "her", "us", "them",
  "my", "your", "his", "its", "our", "their",
  // GRAMMAR METALANGUAGE — the words we use to TALK about any structure. Left in,
  // they let a question about a completely different point "align" simply because
  // it says the word "sentence" or "verb". Removing them means the token set is
  // made of the STRUCTURE ITSELF (could, does, been, than, hoping, since…),
  // which is the only thing worth matching on.
  "sentence", "sentences", "correct", "incorrect", "complete", "completes", "choose",
  "choice", "find", "mistake", "error", "answer", "answers", "option", "options",
  "question", "questions", "word", "words", "order", "form", "forms", "verb", "verbs",
  "noun", "nouns", "subject", "structure", "grammar", "point", "which", "what",
  "please", "thanks", "grammatically",
]);
const _gramWords = (s) => (s || "").toLowerCase().split(/[^a-z']+/).map((w) => w.replace(/'/g, "")).filter((w) => w.length >= 2 && !GRAMMAR_STOPWORDS.has(w));
function grammarAlignmentTokens(bp) {
  const g = (bp && bp.grammar) || {};
  return [...new Set(_gramWords([g.point, g.form, ...(g.examples || [])].join(" ")))];
}
function alignsWithGrammar(text, tokens) {
  const words = new Set(_gramWords(text));
  for (const t of tokens) {
    if (words.has(t)) return true;
    if (t.length >= 5) { const p = t.slice(0, 5); for (const w of words) if (w.startsWith(p)) return true; }
  }
  return false;
}
const sameGrammarPoint = (a, b) => (a || "").trim().toLowerCase().replace(/[^a-z0-9 ]/g, "") === (b || "").trim().toLowerCase().replace(/[^a-z0-9 ]/g, "");

function validateSection(stageId, data, bp) {
  const problems = [];
  if (!data || typeof data !== "object") return ["section data missing"];

  if (stageId === "skill") {
    // Student test: is there a passage to read?
    if (!data.passage || data.passage.length < 30) problems.push("passage too short or missing");
    // Student test: can every question be answered?
    (data.questions || []).forEach((q, i) => {
      if (!q.stem) problems.push(`Q${i+1} has no stem`);
      if (!Array.isArray(q.options) || q.options.length < 3) problems.push(`Q${i+1} has fewer than 3 options`);
      if (!q.options.includes(q.answer)) problems.push(`Q${i+1} answer not in options`);
      if (new Set(q.options).size !== q.options.length) problems.push(`Q${i+1} has duplicate options`);
    });
    // Teacher test: are there enough questions?
    if ((data.questions || []).length < 3) problems.push("fewer than 3 valid questions");
    // Quality test: does the passage use today's vocabulary?
    if (bp && bp.vocabulary) {
      const passageLow = (data.passage || "").toLowerCase();
      const vocabHits = bp.vocabulary.filter(v => passageLow.includes(v.word.toLowerCase())).length;
      if (vocabHits < 2) problems.push("passage uses fewer than 2 of today's vocabulary items");
    }
  }

  if (stageId === "grammar") {
    // ALIGNMENT (the teacher test that matters): the explanation, the examples,
    // the practice, the answers and the feedback must all teach ONE grammar
    // point. A model that quietly drifts to a different structure — or to
    // politeness — produces an exercise that is technically valid and
    // educationally worthless. These two checks catch exactly that.
    if (bp && bp.grammar && bp.grammar.point) {
      // 1. Wholesale drift. The generator MUST declare which point it practised.
      // Requiring the echo (rather than checking it only when present) is what
      // makes this deterministic: a set that quietly practises another structure
      // either declares the wrong point and is caught here, or declares the right
      // point and is caught by the per-question check below.
      if (!data.grammarPoint) problems.push("grammar exercise did not declare its grammar point");
      else if (!sameGrammarPoint(data.grammarPoint, bp.grammar.point))
        problems.push(`grammar point drifted: taught "${bp.grammar.point}" but practised "${data.grammarPoint}"`);
      // 2. Per-question drift: each question must visibly touch today's structure.
      const tokens = grammarAlignmentTokens(bp);
      (data.questions || []).forEach((q, i) => {
        const hay = [q.stem, ...(q.options || []), q.note].join(" ");
        if (tokens.length && !alignsWithGrammar(hay, tokens))
          problems.push(`Q${i+1} does not practise today's grammar point`);
      });
    }
    (data.questions || []).forEach((q, i) => {
      if (!q.stem) problems.push(`Q${i+1} has no stem`);
      if (!Array.isArray(q.options) || q.options.length < 3) problems.push(`Q${i+1} fewer than 3 options`);
      if (!q.options.includes(q.answer)) problems.push(`Q${i+1} answer not in options`);
      if (new Set(q.options).size !== q.options.length) problems.push(`Q${i+1} duplicate options`);
      if (!q.note) problems.push(`Q${i+1} has no teaching note`);
      // Function, not form: "which sounds nicer" is not a grammar question.
      const stemLow = (q.stem || "").toLowerCase();
      if (stemLow.includes("most polite") || stemLow.includes("sounds nicer") || stemLow.includes("more polite"))
        problems.push(`Q${i+1} tests politeness not grammar`);
    });
    if ((data.questions || []).length < 3) problems.push("fewer than 3 valid grammar questions");
  }

  if (stageId === "summary") {
    ["praise", "summary", "strength", "improvement"].forEach(k => {
      if (!data[k]) problems.push(`${k} missing from summary`);
    });
    // Quality test: is the praise specific (not generic)?
    if (data.praise && /^(well done|good job|great work|nice work)\.?$/i.test(data.praise.trim()))
      problems.push("praise is generic — must be specific");
  }

  return problems;
}

/* ---------- Shared completion feedback (used by every scored activity) ----------
   Educational reasoning: completing an activity should produce a moment of
   recognised success (Self-Determination Theory — competence), but praise must
   be proportionate and adult. The message scales with performance, celebrates
   briefly, then carries the student onward so momentum is never broken.
   Technical reasoning: ONE component owns the animation, the message ladder and
   the auto-advance timer, so every stage behaves identically and there is no
   duplicated celebration logic. The timer is always escapable via the button,
   and is cleared on unmount so a Skip mid-celebration cannot double-advance. */
function completionMessage(correct, total) {
  if (typeof correct !== "number" || !total) return { title: "Nice work!", sub: "That's another step forward." };
  const ratio = correct / total;
  if (ratio >= 0.9) return { title: "Outstanding!", sub: `${correct} out of ${total} — you've really got this.` };
  if (ratio >= 0.7) return { title: "Excellent!", sub: `${correct} out of ${total} — strong work.` };
  if (ratio >= 0.5) return { title: "Well done!", sub: `${correct} out of ${total} — you're getting there.` };
  return { title: "Great effort!", sub: `${correct} out of ${total} — the ones you missed will come back for more practice.` };
}

/* §1.1 / §2b.0 — NOTHING AUTO-ADVANCES. The countdown timer and its
   progress bar are removed: the hold between the tick and Continue
   belongs to the student, who taps when ready. On a train, control is
   calm. The `delay` prop is accepted and ignored so existing call
   sites keep working; it can be dropped once none pass it. */
function StageComplete({ correct, total, message, onContinue, delay }) {
  const msg = message || completionMessage(correct, total);
  return (
    <div className="stage-complete" role="status" aria-live="polite">
      <div className="sc-tick" aria-hidden="true">
        <svg viewBox="0 0 52 52" width="56" height="56">
          <circle className="sc-tick-ring" cx="26" cy="26" r="23" fill="none" strokeWidth="2.5" />
          <path className="sc-tick-mark" fill="none" strokeWidth="3.5" strokeLinecap="round" strokeLinejoin="round" d="M15 27 l7.5 7.5 L38 19" />
        </svg>
      </div>
      <h4 className="sc-title">{msg.title}</h4>
      <p className="sc-sub">{msg.sub}</p>
      <button className="primary-btn" onClick={onContinue}>Continue</button>
    </div>
  );
}

/* ---------- Reusable MCQ block (used by Reading/Listening and Grammar) ---------- */
// Content-derived seed: stable across re-renders, different across activities.
function textSeed(str) {
  let s = 7919;
  for (const ch of String(str || "")) s = (s * 31 + ch.charCodeAt(0)) & 0x7fffffff;
  return s;
}

function shuffleOptions(options, seed) {
  const arr = [...options];
  let s = seed;
  for (let i = arr.length - 1; i > 0; i--) {
    s = (s * 1103515245 + 12345) & 0x7fffffff;
    const j = s % (i + 1);
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function McqQuiz({ questions, vocab, onVocabTap, onDone, onAdvance }) {
  const q0 = useExerciseQueue(questions);
  const [chosen, setChosen] = useState(null);
  const [shown, setShown] = useState(false);
  const [correct, setCorrect] = useState(0);
  const q = q0.current;
  // Randomise option order so the correct answer is not always first.
  const [shuffledOpts] = useState(() => questions.map((qu, i) => shuffleOptions(qu.options, i * 7919 + qu.stem.length)));
  const optsFor = (qq) => {
    const i = questions.indexOf(qq);
    return (i >= 0 && shuffledOpts[i]) || qq.options;
  };
  const pick = (opt) => {
    if (chosen || shown) return;
    setChosen(opt);
    if (opt === q.answer) setCorrect((c) => c + 1);
  };
  const showMe = () => { if (chosen) return; setShown(true); };
  const settled = !!chosen || shown;
  const wasCorrect = !!chosen && chosen === q.answer;
  const next = () => {
    q0.advance(wasCorrect);
    setChosen(null);
    setShown(false);
    if (onAdvance) onAdvance();
  };
  // Completion feedback lives in ONE place for every MCQ-based stage.
  if (q0.finished || !q) return <StageComplete correct={correct} total={questions.length} onContinue={() => onDone(correct, questions.length)} />;
  const isLast = q0.index + 1 >= q0.total;
  return (
    <div>
      {/* §4.2: dots and N of M. The old width-percentage bar is retired —
          a percentage over unequal items is a number doing a feeling's job. */}
      <ExerciseChrome index={q0.index} total={q0.total} />
      <p className="q-sentence"><VocabText text={q.stem} vocab={vocab} onTap={onVocabTap} /></p>
      <div className="mcq-opts">
        {optsFor(q).map((opt, i) => (
          <button key={i}
            className={"mcq-opt" + (settled ? (opt === q.answer ? " mcq-right" : opt === chosen ? " mcq-chosen" : " mcq-muted") : "")}
            onClick={() => pick(opt)} disabled={settled}>{opt}</button>
        ))}
      </div>
      {!settled && <ShowMeLink onShow={showMe} shown={shown} />}
      {settled && (
        <div>
          {shown
            ? <CorrectAnswerReveal answer={q.answer} note={q.note} />
            : <LeoFeedback ok={wasCorrect}>{wasCorrect ? q.note : <>The answer is <strong className="ex-answer">{q.answer}</strong>. {q.note}</>}</LeoFeedback>}
          <button className="primary-btn" onClick={next}>{isLast ? "Finish practice" : "Next \u2192"}</button>
        </div>
      )}
    </div>
  );
}

/* ==================== WARM-UP ACTIVITY SYSTEM ====================
   Educational reasoning: a warm-up exists to ACTIVATE — to switch the student
   into English, surface what they already know, and prime the exact language
   the lesson will teach. A single format repeated every day stops activating
   and starts boring; variety keeps the affective filter low and the noticing
   high. Every activity below is a recognised ELICOS warm-up type, and every one
   must be contextualised to today's scenario — a generic warm-up teaches nobody.

   Technical reasoning: twelve activity types would mean twelve components and
   twelve validators. Instead each type declares a FAMILY, and there are exactly
   three renderers (free / choice / sequence). Adding a thirteenth type is a
   one-line registry entry, not new UI. Validation is shared per family, so a
   malformed activity can never reach the student — it is filtered out, and if
   too few survive, the lesson falls back to discussion questions rather than
   breaking.
   ================================================================ */
const WARMUP_TYPES = {
  context_discussion: { family: "free",     label: "Talk about it" },
  prediction:         { family: "free",     label: "What do you think?" },
  finish_sentence:    { family: "free",     label: "Finish the sentence" },
  mini_task:          { family: "free",     label: "Mini task" },
  mcq:                { family: "choice",   label: "Choose the answer" },
  best_response:      { family: "choice",   label: "Choose the best response" },
  true_false:         { family: "choice",   label: "True or false?" },
  is_this_correct:    { family: "choice",   label: "Is this correct?" },
  spot_mistake:       { family: "choice",   label: "Spot the mistake" },
  complete_dialogue:  { family: "choice",   label: "Complete the dialogue" },
  unscramble:         { family: "sequence", label: "Unscramble the sentence" },
  order_conversation: { family: "sequence", label: "Order the conversation" },
  /* §3b — the authored warm-up shapes. Without these three registered,
     validateWarmUpActivity rejects every authored activity and the
     lesson falls back to generic discussion questions: the teacher's
     warm-up would never render. All three are "open" — they accept
     what the student offers and Leo responds, so none of them can be
     marked wrong (a warm-up activates; it does not assess). */
  image_recognition:  { family: "open",     label: "What is this?" },
  personal_reveal:    { family: "open",     label: "About you" },
  frame_drill:        { family: "open",     label: "Say it" },
};
const warmUpFamily = (t) => (WARMUP_TYPES[t] ? WARMUP_TYPES[t].family : null);

/* One activity is valid only if it can actually be COMPLETED and MARKED. */
function validateWarmUpActivity(a) {
  if (!a || typeof a !== "object") return false;
  const fam = warmUpFamily(a.type);
  if (!fam) return false;
  if (!a.prompt || typeof a.prompt !== "string") return false;
  if (fam === "free") return true;
  /* §3b — "open" activities cannot be marked wrong, so they need only
     something to answer. An image_recognition without a picture is
     still a valid question ("What country is this?" answered in
     words) — the image is support, never the task itself. */
  if (fam === "open") return true;
  if (fam === "choice") {
    if (!Array.isArray(a.options) || a.options.length < 2) return false;
    if (new Set(a.options).size !== a.options.length) return false;
    if (!a.options.includes(a.answer)) return false;
    return !!a.note;
  }
  // sequence: tokens are the CORRECT order; the student rebuilds it
  if (!Array.isArray(a.tokens) || a.tokens.length < 3 || a.tokens.length > 12) return false;
  if (a.tokens.some((t) => !t || typeof t !== "string")) return false;
  return !!a.note;
}
function validateWarmUp(activities) {
  return (Array.isArray(activities) ? activities : []).filter(validateWarmUpActivity).slice(0, 5);
}
/* Backstop: if the planner gives us nothing usable, today's warm-up is still a
   real warm-up — the blueprint's discussion questions, in the original format. */
function warmUpFallback(bp) {
  return (bp.warmUpQuestions || []).slice(0, 4).map((q) => ({
    type: "context_discussion",
    instruction: "Just chat — there are no wrong answers here.",
    prompt: q,
  }));
}

/* ---------- Renderer 1: FREE — communicative, never string-matched ---------- */
/* §3b — the "open" warm-up renderer. Nothing here can be wrong: if the
   student can't answer, Leo gives the answer warmly and moves on.

   THE COUNTRY REVEAL, and its honesty constraint: the delight is that
   the app answered their fact with their place. That only works if the
   picture genuinely exists. If the image pipeline holds nothing for
   the country they named, Leo still responds in words and NO empty
   frame renders — the code never promises a picture it does not have. */
function WarmUpOpen({ activity, vocab, onVocabTap, onDone }) {
  const [input, setInput] = useState("");
  const [answered, setAnswered] = useState(false);
  const isReveal = !!activity.revealImageByAnswer;
  const said = input.trim();
  const image = activity.image || null;
  /* Resolved from the pipeline, not assumed. Today nothing resolves a
     country image, so revealSrc is null and the words-only path runs —
     which is the honest behaviour until that pipeline exists. */
  const revealSrc = null;
  const confirm = activity.leoConfirmTemplate
    ? String(activity.leoConfirmTemplate).replace(/\{answer\}/g, said)
    : activity.leoConfirm;
  return (
    <div>
      {/* Prompt image (e.g. the Australian flag), when authored. */}
      {image && !isReveal && <LessonImage src={image.src} alt={image.alt} caption={image.alt} />}
      <p className="q-sentence">
        <VocabText text={activity.prompt} vocab={vocab} onTap={onVocabTap} />
      </p>
      {activity.frame && (
        <div className="grammar-form-box"><p className="gb-keypoint-text">{activity.frame}</p></div>
      )}
      {activity.hint && !answered && <p className="ex-hint">{activity.hint}</p>}
      {!answered ? (
        <>
          <div className="input-row">
            <input className="text-input" value={input} onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && said && setAnswered(true)}
              placeholder={"Type your answer\u2026"} {...EXERCISE_INPUT_PROPS_PROPER_NOUN} />
            <MicButton onText={(t) => setInput(t)} />
          </div>
          <div className="ex-actions">
            <button className="primary-btn" onClick={() => setAnswered(true)} disabled={!said}>Send</button>
          </div>
        </>
      ) : (
        <>
          {/* The reveal arrives into a frame that was NOT previously on
              screen — the arrival is the event. Only when it exists. */}
          {isReveal && revealSrc && <LessonImage src={revealSrc} alt={said} caption={said} />}
          {confirm && <div className="bubble bubble-bot stage-enter">{confirm}</div>}
          <button className="primary-btn wide" onClick={() => onDone(true)}>Next →</button>
        </>
      )}
    </div>
  );
}

function WarmUpFree({ activity, vocab, onVocabTap, onDone, context, cefr }) {
  const [answer, setAnswer] = useState("");
  const [sent, setSent] = useState(false);
  const [reply, setReply] = useState(null);      // { category, line }
  const settledRef = React.useRef(false);        // first result wins; the other is discarded
  const timerRef = React.useRef(null);
  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current); }, []);

  /* Whichever arrives first settles the turn. Without this a response landing
     after the timeout would swap the fallback out from under the student
     mid-read. */
  const settle = (result, failureReason) => {
    if (settledRef.current) return;
    settledRef.current = true;
    if (timerRef.current) { clearTimeout(timerRef.current); timerRef.current = null; }
    if (failureReason) console.warn("[warmup_free_response] fallback used:", failureReason);
    setReply(result);
  };

  const submit = async () => {
    const a = answer.trim();
    if (!a || sent) return;
    setSent(true);
    timerRef.current = setTimeout(
      () => settle({ category: "attempt", line: WARMUP_FALLBACK_LINE }, "timeout after 5000ms"), 5000);
    try {
      // Leo's voice, delivered by Lessons 22 July. The JSON shape is unchanged,
      // so the existing parsing, category clamp, timeout and fallback all keep
      // working. The mock reads "Context:" out of this prompt to select today's
      // pack — do not reorder or rename that field.
      const raw = await askClaude(
        `${AUSTRALIAN_SPELLING}You are Leo, an experienced Australian ELICOS teacher, replying to your student's warm-up answer. A warm-up has one job: switch the student into English and make them feel ready. Never correct grammar, spelling or pronunciation here.

Activity prompt: "${activity.prompt}"
Today's lesson context: "${context || ""}"
The student typed: "${a}"

First, classify the answer:
- "skip": no real effort — a single character, repeated characters, punctuation only, or meaningless letters.
- "minimal": a real answer, but only one or two words, or a short phrase with no detail.
- "attempt": real communicative content — the student actually said something.

Then write ONE reply line, maximum 35 words, ${cefr} English, warm Australian teacher's voice:
- skip: reply with exactly this and nothing more: No problem — let's move on.
- minimal: acknowledge the short answer warmly and connect it to today's lesson context in ONE short additional sentence that adds something — a fact, a link to today, or a light observation — WITHOUT asking a question. The student cannot reply to a follow-up here, so a question is a dead end for them. Land your line as a complete, satisfying response on its own.
- attempt: respond to something SPECIFIC the student said — name it in your reply — then connect it to today's lesson.

The generic-praise test: if your line would make equal sense no matter what the student typed, rewrite it. Never invent details the student did not give you. Never praise a skip.

${narrationGuidance(cefr, "chat")}\n\nRespond ONLY with JSON, no fences: {"category":"skip|minimal|attempt","line":"your one reply line"}`,
        { intent: "warmup_free_response" }
      );
      const d = parseJSON(raw);
      if (!d || !d.line) throw new Error("invalid response shape");
      const cat = d.category === "skip" || d.category === "minimal" ? d.category : "attempt";
      settle({ category: cat, line: d.line });
    } catch (err) {
      settle({ category: "attempt", line: WARMUP_FALLBACK_LINE }, (err && err.message) || "unknown error");
    }
  };

  return (
    <div>
      <p className="q-sentence"><VocabText text={activity.prompt} vocab={vocab} onTap={onVocabTap} /></p>
      <div className="input-row">
        <input className="text-input" placeholder="Type your answer, or use the mic…" value={answer} disabled={sent}
          onChange={(e) => setAnswer(e.target.value)} onKeyDown={(e) => e.key === "Enter" && submit()} />
        <MicButton onText={(t) => setAnswer(t)} />
      </div>
      {!sent && <button className="primary-btn" onClick={submit} disabled={!answer.trim()}>Send</button>}

      {/* A typing indicator, deliberately not a spinner: a spinner says the
          system is loading, this says someone is reading your words. */}
      {sent && !reply && (
        <WaitIndicator label="Leo is reading" />
      )}

      {reply && (
        <div>
          {/* skip gets no tick — a student who typed nothing is not congratulated.
              minimal and attempt are visually identical, so the student cannot
              read their grade off the interface; only Leo's words differ. */}
          {reply.category === "skip"
            ? <p className="text-leo wu-skip-line">{reply.line}</p>
            : <LeoFeedback ok>{reply.line}</LeoFeedback>}
          <button className="primary-btn" onClick={() => onDone(reply.category !== "skip")}>Next</button>
        </div>
      )}
    </div>
  );
}

/* ---------- Renderer 2: CHOICE — marked, with a teaching note either way ---------- */
function WarmUpChoice({ activity, vocab, onVocabTap, onDone }) {
  const [chosen, setChosen] = useState(null);
  const [opts] = useState(() => shuffleOptions(activity.options, textSeed(activity.prompt + activity.answer)));
  const ok = chosen === activity.answer;
  return (
    <div>
      <p className="q-sentence"><VocabText text={activity.prompt} vocab={vocab} onTap={onVocabTap} /></p>
      {activity.text && <p className="wu-text">{activity.text}</p>}
      <div className="mcq-opts">
        {opts.map((o, i) => (
          <button key={i} disabled={!!chosen} onClick={() => setChosen(o)}
            className={"mcq-opt" + (chosen ? (o === activity.answer ? " mcq-right" : o === chosen ? " mcq-chosen" : " mcq-muted") : "")}>{o}</button>
        ))}
      </div>
      {chosen && (
        <div>
          <LeoFeedback ok={ok}>{activity.note}</LeoFeedback>
          <button className="primary-btn" onClick={() => onDone(ok)}>Next</button>
        </div>
      )}
    </div>
  );
}

/* ---------- Renderer 3: SEQUENCE — rebuild the correct order ---------- */
function WarmUpSequence({ activity, onDone }) {
  const correct = activity.tokens;
  // A shuffle that happens to return the correct order would hand the student the
  // answer, so it is rejected and nudged. Seeded from the content, not the length,
  // so two 8-word sentences don't scramble identically.
  const [pool] = useState(() => {
    let arr = shuffleOptions(correct.map((t, i) => ({ t, i })), textSeed(correct.join(" ")));
    if (correct.length > 2 && arr.map((a) => a.t).join("|") === correct.join("|")) arr = [arr[1], arr[0], ...arr.slice(2)];
    return arr;
  });
  const [built, setBuilt] = useState([]);   // [{t,i}]
  const [checked, setChecked] = useState(null); // null | true | false
  const isLine = activity.type === "order_conversation";
  const used = new Set(built.map((b) => b.i));
  const check = () => setChecked(built.map((b) => b.t).join("|") === correct.join("|"));
  const reset = () => { setBuilt([]); setChecked(null); };
  return (
    <div>
      <p className="q-sentence">{activity.prompt}</p>
      <div className={"wu-build" + (isLine ? " wu-build-lines" : "")} aria-live="polite">
        {built.length === 0 && <span className="wu-build-empty">Tap the {isLine ? "lines" : "words"} below in the right order…</span>}
        {built.map((b, i) => (
          <button key={i} className="wu-chip wu-chip-built" disabled={checked !== null}
            onClick={() => setBuilt(built.filter((_, j) => j !== i))} aria-label={`Remove ${b.t}`}>{b.t}</button>
        ))}
      </div>
      <div className={"wu-pool" + (isLine ? " wu-build-lines" : "")}>
        {pool.filter((p) => !used.has(p.i)).map((p) => (
          <button key={p.i} className="wu-chip" disabled={checked !== null} onClick={() => setBuilt([...built, p])}>{p.t}</button>
        ))}
      </div>
      {checked === null ? (
        <div className="btn-row">
          <button className="primary-btn" onClick={check} disabled={built.length !== correct.length}>Check</button>
          {built.length > 0 && <button className="ghost-btn" onClick={reset}>Start again</button>}
        </div>
      ) : (
        <div>
          <LeoFeedback ok={checked}>
            {checked ? activity.note : `Not quite — the natural order is: “${correct.join(isLine ? " / " : " ")}”. ${activity.note}`}
          </LeoFeedback>
          <button className="primary-btn" onClick={() => onDone(checked)}>Next</button>
        </div>
      )}
    </div>
  );
}

function WarmUpActivity({ activity, vocab, onVocabTap, onDone, context, cefr }) {
  const fam = warmUpFamily(activity.type);
  if (fam === "choice") return <WarmUpChoice activity={activity} vocab={vocab} onVocabTap={onVocabTap} onDone={onDone} />;
  if (fam === "sequence") return <WarmUpSequence activity={activity} onDone={onDone} />;
  if (fam === "open") return <WarmUpOpen activity={activity} vocab={vocab} onVocabTap={onVocabTap} onDone={onDone} />;
  return <WarmUpFree activity={activity} vocab={vocab} onVocabTap={onVocabTap} onDone={onDone} context={context} cefr={cefr} />;
}

/* ---------- Stage 1: Introduction — context, objective, varied warm-up ---------- */
/* ================================================================
   PHASE 8 — READING, WARM-UP IMAGES, INTRODUCTION (§3f, §3b, §3a)
   ================================================================ */

/* §3b — the image treatment, ruled once for the product.
   Framed by SHAPE, not chrome: radius, no border, no shadow. The
   placeholder occupies the final size from the start, so the layout
   never jumps — and it is a flat block, not a shimmer, because
   nothing in this product loops while waiting.
   On failure the block persists with the caption inside it and the
   lesson proceeds: a missing photo never blocks teaching (§4.4). */
function LessonImage({ src, alt, caption }) {
  const [state, setState] = useState(src ? "loading" : "failed");
  if (!src || state === "failed") {
    return (
      <div className="li-frame li-frame-empty">
        <span className="li-caption">{caption || alt || ""}</span>
      </div>
    );
  }
  return (
    <div className="li-frame">
      <img src={src} alt={alt || ""} className={"li-img" + (state === "ready" ? " li-img-in" : "")}
        onLoad={() => setState("ready")} onError={() => setState("failed")} />
    </div>
  );
}

/* §3a — the aims moment. Leo says it, then a quiet list: his voice
   carries the relationship, the list survives being half-read on a
   train. Two or three aims maximum — more is a syllabus, not a
   lesson. Renders nothing at all when the lesson authored no aims. */
function AimsMoment({ aims }) {
  if (!aims) return null;
  const list = (aims.list || []).slice(0, 3);
  return (
    <>
      {aims.spoken && (
        <div className="bubble bubble-bot stage-enter">{aims.spoken}</div>
      )}
      {list.length > 0 && (
        <div className="aims-card stage-enter-delayed">
          {list.map((a, i) => <p key={i} className="aims-row">· {a}</p>)}
        </div>
      )}
    </>
  );
}

function IntroductionSection({ bp, vocab, onVocabTap, onSkip, onDone, header }) {
  const [idx, setIdx] = useState(-1); // -1 = the intro card
  const [score, setScore] = useState({ ok: 0, done: 0 });
  const [finished, setFinished] = useState(false);
  // The planner's activities, filtered by validation; discussion questions if none survive.
  const [activities] = useState(() => {
    const valid = validateWarmUp(bp.warmUpActivities);
    return valid.length >= 2 ? valid : warmUpFallback(bp);
  });

  const complete = (wasOk) => {
    const next = { ok: score.ok + (wasOk ? 1 : 0), done: score.done + 1 };
    setScore(next);
    if (idx + 1 < activities.length) setIdx(idx + 1);
    else setFinished(true);
  };

  if (finished) return (
    <SectionShell header={header} title="Warm-up" onSkip={onSkip}>
      <StageComplete message={{ title: "Warmed up!", sub: "You're switched into English — now let's build today's language." }}
        onContinue={() => onDone(score.done)} />
    </SectionShell>
  );

  if (idx === -1) return (
    <SectionShell header={header} title="Today's lesson" onSkip={onSkip}>
      <div className="lesson-head leo-accent" style={{ animation: "scRise .4s ease-out both" }}>
        <p className="lesson-greeting text-leo"><VocabText text={bp.explanation} vocab={vocab} onTap={onVocabTap} /></p>
      </div>
      {/* §3a — the aims moment, when the lesson authored one. */}
      <AimsMoment aims={bp.aims} />
      <button className="primary-btn wide" style={{ marginTop: "var(--space-4)", animation: "scRise .4s ease-out both", animationDelay: "0.3s" }} onClick={() => setIdx(0)}>Let's warm up</button>
    </SectionShell>
  );

  const a = activities[idx];
  const meta = WARMUP_TYPES[a.type] || WARMUP_TYPES.context_discussion;
  return (
    <SectionShell header={header} title="Warm-up" blurb={a.instruction} onSkip={onSkip}>
      <div className="wu-head">
        <span className="wu-badge">{meta.label}</span>
        <span className="muted small">{idx + 1} of {activities.length}</span>
      </div>
      <WarmUpActivity key={idx} activity={a} vocab={vocab} onVocabTap={onVocabTap} onDone={complete} context={bp.context} cefr={bp.cefr} />
    </SectionShell>
  );
}

/* ==================== REUSABLE LEARNING PRIMITIVES ====================
   Generic, exercise-type components used across multiple lesson stages.
   Each primitive renders one interaction, calls onDone when complete,
   and never knows which stage or lesson type it belongs to.
   ==================================================================== */

/* ---------- GapFillInput: a text-input exercise with answer checking ----------
   Renders a stem containing a blank (______), a text input, and a check button.
   Compares the student's answer (case-insensitive, trimmed) against one or more
   valid answers. Shows LeoFeedback on submission.

   Designed for reuse across: vocabulary complete-the-sentences, listening gap-fill,
   dictation, spelling, grammar gap-fill, translation exercises.
   ----------------------------------------------------------------------------- */
function GapFillInput({ stem, answers, note, placeholder, onDone, properNoun }) {
  const [input, setInput] = useState("");
  const [checked, setChecked] = useState(null); // null | true | false
  const [shown, setShown] = useState(false);
  const validAnswers = Array.isArray(answers) ? answers : [answers];
  /* §2b.2 acceptance surface: case-insensitive, whitespace trimmed,
     terminal punctuation ignored. Internal spelling must be exact —
     at A1, spelling IS content, so a misspelling is a wrong-moment
     with the correct spelling shown as teaching. */
  const norm = (s) => String(s || "").trim().toLowerCase().replace(/[.!?]+$/, "");
  const isCorrect = (text) => validAnswers.some((a) => norm(a) === norm(text));
  const check = () => {
    if (!input.trim() || checked !== null || shown) return;
    const ok = isCorrect(input);
    setChecked(ok);
    if (onDone) onDone(ok);
  };
  const showMe = () => {
    if (checked !== null || shown) return;
    setShown(true);
    if (onDone) onDone(false); // §2b.0 — counts as not-correct
  };
  const settled = checked !== null || shown;
  const displayStem = (stem || "").replace(/_{2,}/g, "______");
  /* §2b.2 — on a settled item the gap is filled by the correct answer
     in the teacher's colour, so the completed sentence is always the
     last thing the student sees. */
  const filledParts = settled ? displayStem.split("______") : null;
  return (
    <div className="gapfill-item">
      {settled && filledParts && filledParts.length > 1
        ? <p className="q-sentence">{filledParts[0]}<strong className="ex-answer">{validAnswers[0]}</strong>{filledParts.slice(1).join("______")}</p>
        : <p className="q-sentence">{displayStem}</p>}
      <div className="input-row">
        <input className="text-input" placeholder={placeholder || "Type the missing word\u2026"} value={input}
          disabled={settled} onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && check()}
          {...(properNoun ? EXERCISE_INPUT_PROPS_PROPER_NOUN : EXERCISE_INPUT_PROPS)} />
        {!settled && <button className="primary-btn" onClick={check} disabled={!input.trim()}>Check</button>}
      </div>
      {!settled && <ShowMeLink onShow={showMe} shown={shown} />}
      {shown && <CorrectAnswerReveal answer={validAnswers[0]} note={note} />}
      {checked !== null && (
        <LeoFeedback ok={checked}>
          {checked
            ? (note || "That's right \u2014 well done!")
            : <>The answer is <strong className="ex-answer">{validAnswers[0]}</strong>. {note || ""}</>}
        </LeoFeedback>
      )}
    </div>
  );
}

/* ---------- VocabReviewExercise: odd-one-out then complete-the-sentences ----------
   Internal sub-component used by VocabularySection when bp.vocabReviewExercises
   exists. Sequences two exercise types, tracks combined score, calls onDone.
   ----------------------------------------------------------------------------- */
function VocabReviewExercise({ exercises, vocab, onVocabTap, onDone }) {
  const [phase, setPhase] = useState("ooo"); // "ooo" | "gapfill" | "done"
  const [oooScore, setOooScore] = useState({ correct: 0, total: 0 });
  const [gfIdx, setGfIdx] = useState(0);
  const [gfCorrect, setGfCorrect] = useState(0);
  const [gfChecked, setGfChecked] = useState(false);

  const ooo = exercises.oddOneOut || [];
  const gapfill = exercises.completeSentences || [];
  const hasOoo = ooo.length > 0;
  const hasGf = gapfill.length > 0;

  // Convert odd-one-out to McqQuiz format
  const oooQuestions = React.useMemo(() => ooo.map((q) => ({
    stem: "Which word does not belong in this group?",
    options: q.options,
    answer: q.answer,
    note: q.note || "That's the odd one out.",
  })), []);

  if (phase === "ooo" && hasOoo) {
    return (
      <div>
        <h4 className="diary-label">Odd one out</h4>
        <p className="muted small">Which word does not belong?</p>
        <McqQuiz questions={oooQuestions} vocab={vocab} onVocabTap={onVocabTap}
          onDone={(correct, total) => {
            setOooScore({ correct, total });
            if (hasGf) setPhase("gapfill");
            else setPhase("done");
          }} />
      </div>
    );
  }

  if (phase === "gapfill" && hasGf) {
    const q = gapfill[gfIdx];
    return (
      <div>
        <h4 className="diary-label">Complete the sentences</h4>
        <p className="muted small">Use the vocabulary from today's lesson. Question {gfIdx + 1} of {gapfill.length}.</p>
        <GapFillInput
          key={gfIdx}
          stem={q.stem}
          answers={q.answer}
          note={q.note}
          onDone={(ok) => {
            if (ok) setGfCorrect((c) => c + 1);
            setGfChecked(true);
          }}
        />
        {/* §1.1 — nothing auto-advances. This previously jumped after
            1800ms, which is less time than an A1 student needs to read
            the feedback they just earned. */}
        {gfChecked && (
          <button className="primary-btn" onClick={() => {
            setGfChecked(false);
            if (gfIdx + 1 < gapfill.length) setGfIdx(gfIdx + 1);
            else setPhase("done");
          }}>{gfIdx + 1 < gapfill.length ? "Next \u2192" : "Finish practice"}</button>
        )}
      </div>
    );
  }

  // phase === "done" or skipped phases
  if (phase === "ooo" && !hasOoo && hasGf) { setPhase("gapfill"); return null; }
  if (phase === "ooo" && !hasOoo && !hasGf) { setPhase("done"); return null; }

  const totalCorrect = oooScore.correct + gfCorrect;
  const totalQuestions = oooScore.total + gapfill.length;
  return (
    <StageComplete correct={totalCorrect} total={totalQuestions}
      message={{ title: "Vocabulary reviewed!", sub: `${totalCorrect} out of ${totalQuestions} — those words are getting stronger.` }}
      onContinue={() => onDone(totalCorrect, totalQuestions)} />
  );
}

/* ---------- Stage 2: Vocabulary — match words to meanings ----------
   Interaction is UNCHANGED: drag a line from a word to its meaning. What is new
   is the finish — spacing, depth, motion, state feedback — plus a tap/keyboard
   path to the SAME matching model, because a drag-only exercise is unusable for
   a student with a motor impairment or a screen reader, and Leo teaches everyone.
   A short press with no movement selects a word; tapping a meaning then matches
   it. Keyboard users get the identical two-step via Enter/Space. */
/* ================================================================
   parseIPA — derive syllable count and stressed syllable from IPA
   ================================================================ */
function parseIPA(ipa) {
  if (!ipa) return null;
  const clean = ipa.replace(/^[/\[]|[/\]]$/g, "").trim();
  if (!clean) return null;
  const parts = clean.split(".");
  if (parts.length < 1) return null;
  let stressIdx = -1;
  const syllables = parts.map((p, i) => {
    if (p.includes("\u02C8")) stressIdx = i;
    return p.replace(/[\u02C8\u02CC]/g, "").trim();
  });
  if (stressIdx < 0 && syllables.length === 1) stressIdx = 0;
  return { syllables, stressIdx, count: syllables.length };
}

/* ================================================================
   PRON CARD — pronunciation-focused step-through card (§1)
   No meaning, no example, no POS. Stress pattern, L1 note, pairs.
   ================================================================ */
function PronCard({ word, ipa, index, total, pronunciation, stressLabel, onNext, onVocabTap, lastLabel, onSpoke }) {
  const [heard, setHeard] = useState("");
  const isLast = index === total - 1;
  const parsed = parseIPA(ipa);
  return (
    <div className="word-card" key={word + "-pron-" + index}>
      <div className="wc-progress">
        <span className="wc-progress-text">Sound {index + 1} of {total}</span>
        <span className="wc-dots">{Array.from({ length: total }, (_, i) => (
          <span key={i} className={"wc-dot" + (i < index ? " wc-dot-done" : i === index ? " wc-dot-current" : "")} />
        ))}</span>
      </div>
      <div className="wc-word"><VocabToken word={word} onTap={onVocabTap} /></div>
      {ipa && <div className="wc-ipa">{ipa}</div>}
      {parsed && parsed.count > 1 && parsed.stressIdx >= 0 && (
        <div className="pron-stress-row">
          {parsed.syllables.map((syl, i) => (
            <div key={i} className="pron-stress-item">
              <span className={i === parsed.stressIdx ? "pron-stress-dot-filled" : "pron-stress-dot-outline"} />
              <span className={i === parsed.stressIdx ? "pron-stress-label-stressed" : "pron-stress-label"}>{syl}</span>
            </div>
          ))}
        </div>
      )}
      {pronunciation && (pronunciation.description || pronunciation.instructions) && (
        <div className="pron-l1-note">
          <p style={{ margin: 0, fontSize: 15, lineHeight: 1.5, color: "var(--text-primary)" }}>
            {pronunciation.instructions || pronunciation.description}
          </p>
        </div>
      )}
      {pronunciation && pronunciation.correct && (
        <div className="pron-pair">
          <div className="pron-pair-correct">
            <span>{"\u2713"} {Array.isArray(pronunciation.correct) ? pronunciation.correct.join(" \u00b7 ") : pronunciation.correct}</span>
            <SpeakButton text={String(Array.isArray(pronunciation.correct) ? pronunciation.correct[0] : pronunciation.correct)} className="speak-btn-sm" />
          </div>
          {pronunciation.incorrect && (
            <div className="pron-pair-incorrect">
              <span><s>{Array.isArray(pronunciation.incorrect) ? pronunciation.incorrect.join(" \u00b7 ") : pronunciation.incorrect}</s></span>
              <SpeakButton text={String(Array.isArray(pronunciation.incorrect) ? pronunciation.incorrect[0] : pronunciation.incorrect)} className="speak-btn-sm" />
            </div>
          )}
        </div>
      )}
      {pronunciation && pronunciation.practiceWords && pronunciation.practiceWords.length > 0 && (
        <div className="wc-practise-row">
          <span className="muted small">Practise: </span>
          {pronunciation.practiceWords.map((pw, j) => (
            <span key={j}>{TTS_OK ? <button className="link-btn small" onClick={() => speakText(pw)}>{pw}</button> : <span className="small">{pw}</span>}{j < pronunciation.practiceWords.length - 1 ? " \u00b7 " : ""}</span>
          ))}
        </div>
      )}
      <div className="wc-actions">
        {TTS_OK && <button className="ghost-btn wc-action-btn" onClick={() => speakText(word)}><Volume2 size={16} aria-hidden="true" /> Hear it</button>}
        <MicButton className="ghost-btn wc-action-btn" label="\uD83C\uDF99\uFE0F Say it" onText={(t) => { setHeard(t); onSpoke?.(); }} />
      </div>
      {heard && <p className="wc-heard">I heard: "{heard}"</p>}
      <button className="primary-btn wide wc-next" onClick={onNext}>{isLast ? (lastLabel || "Continue") : "Next \u2192"}</button>
    </div>
  );
}
function PronCardSequence({ words, onComplete, onVocabTap, lastLabel, onSpoke }) {
  const [idx, setIdx] = useState(0);
  const w = words[idx];
  if (!w) return null;
  return <PronCard key={w.word + "-" + idx} word={w.word} ipa={w.ipa} index={idx} total={words.length}
    pronunciation={w._pronunciation || null} stressLabel={w.stress}
    onNext={() => { if (idx < words.length - 1) setIdx(idx + 1); else onComplete(); }}
    onVocabTap={onVocabTap} lastLabel={lastLabel} onSpoke={onSpoke} />;
}

/* ================================================================
   WORD CARD — step-through vocabulary/pronunciation card (§1–§11)
   Spec: WORD_CARD_SPECIFICATION.md. One word per screen. Tap Next.
   ================================================================ */
function WordCard({ word, ipa, pos, meaning, example, index, total, pronunciation, onNext, onVocabTap, lastLabel }) {
  const [heard, setHeard] = useState("");
  const isLast = index === total - 1;
  return (
    <div className="word-card" key={word + "-" + index}>
      {/* §4 Progress row */}
      <div className="wc-progress">
        <span className="wc-progress-text">Word {index + 1} of {total}</span>
        <span className="wc-dots">
          {Array.from({ length: total }, (_, i) => (
            <span key={i} className={"wc-dot" + (i < index ? " wc-dot-done" : i === index ? " wc-dot-current" : "")} />
          ))}
        </span>
      </div>
      {/* §3 Typography */}
      <div className="wc-word"><VocabToken word={word} onTap={onVocabTap} /></div>
      {ipa && <div className="wc-ipa">{ipa}</div>}
      {pos && <div className="wc-pos">{pos}</div>}
      <div className="wc-meaning">{meaning}</div>
      {example && <div className="wc-example">{example}</div>}
      {/* §5 Action buttons */}
      <div className="wc-actions">
        {TTS_OK && <button className="ghost-btn wc-action-btn" onClick={() => speakText(word + ". " + (example || ""))}><Volume2 size={16} aria-hidden="true" /> Hear it</button>}
        <MicButton className="ghost-btn wc-action-btn" label="\uD83C\uDF99\uFE0F Say it" onText={(t) => setHeard(t)} />
      </div>
      {heard && <p className="wc-heard">I heard: "{heard}"</p>}
      {/* §6 Pronunciation block */}
      {pronunciation && (
        <div className="wc-pron-block">
          {pronunciation.practiceWords && pronunciation.practiceWords.length > 0 && (
            <div className="wc-practise-row">
              <span className="muted small">Practise: </span>
              {pronunciation.practiceWords.map((pw, j) => (
                <span key={j}>
                  {TTS_OK ? <button className="link-btn small" onClick={() => speakText(pw)}>{pw}</button> : <span className="small">{pw}</span>}
                  {j < pronunciation.practiceWords.length - 1 ? " \u00b7 " : ""}
                </span>
              ))}
            </div>
          )}
          {(pronunciation.instructions || pronunciation.description) && (
            <p className="wc-pron-tip">{pronunciation.instructions || pronunciation.description}</p>
          )}
          {pronunciation.correct && (
            <p className="wc-pron-correct">{"\u2713"} {Array.isArray(pronunciation.correct) ? pronunciation.correct.join(" \u00b7 ") : pronunciation.correct}</p>
          )}
          {pronunciation.incorrect && (
            <p className="wc-pron-incorrect">{"\u2717"} <s>{Array.isArray(pronunciation.incorrect) ? pronunciation.incorrect.join(" \u00b7 ") : pronunciation.incorrect}</s></p>
          )}
        </div>
      )}
      {/* §5.4 Next */}
      <button className="primary-btn wide wc-next" onClick={onNext}>{isLast ? (lastLabel || "Continue") : "Next \u2192"}</button>
    </div>
  );
}

/* WordCardSequence — manages the current index through a list of word data */
function WordCardSequence({ words, onComplete, onVocabTap, lastLabel }) {
  const [idx, setIdx] = useState(0);
  const w = words[idx];
  if (!w) return null;
  return (
    <WordCard
      key={w.word + "-" + idx}
      word={w.word} ipa={w.ipa} pos={w.pos} meaning={w.meaning}
      example={w.examples && w.examples[0] ? w.examples[0] : w.example}
      index={idx} total={words.length}
      pronunciation={w._pronunciation || null}
      onNext={() => { if (idx < words.length - 1) setIdx(idx + 1); else onComplete(); }}
      onVocabTap={onVocabTap}
      lastLabel={lastLabel}
    />
  );
}

function VocabularySection({ bp, onVocabTap, leoMemory, onSkip, onDone, header }) {
  // Authored lessons declare matchVocab (a curated subset of up to 8 words for
  // the matching exercise). AI-generated lessons use the first 8 from vocabulary.
  // The full vocabulary array is always available for tokens, cards, and review.
  const items = React.useMemo(() => {
    if (bp.matchVocab && bp.matchVocab.length) {
      const all = bp.vocabulary || [];
      // matchVocab can be word strings or indices — resolve to vocabulary objects
      return bp.matchVocab.map((ref) =>
        typeof ref === "number" ? all[ref] : all.find((v) => v.word.toLowerCase() === ref.toLowerCase())
      ).filter(Boolean).slice(0, 8);
    }
    return (bp.vocabulary || []).slice(0, 8);
  }, [bp]);
  // Stable shuffle of definitions — seeded from today's context so it never
  // re-shuffles on re-render, but DOES differ between lessons.
  const [defs] = useState(() => {
    const arr = [...items];
    let s = 7919;
    for (const ch of (bp.context || "")) s = (s * 31 + ch.charCodeAt(0)) & 0x7fffffff;
    for (let i = arr.length - 1; i > 0; i--) { s = (s * 1103515245 + 12345) & 0x7fffffff; const j = s % (i + 1); [arr[i], arr[j]] = [arr[j], arr[i]]; }
    // Derangement guarantee: no position may hold its own original item — a
    // student must never be able to read row N's meaning as row N's word.
    // A Fisher-Yates shuffle CAN legitimately leave a position unmoved by
    // chance (more likely on short lists). If it does, fall back to a full
    // rotation: since every item is distinct, rotating by 1 guarantees
    // position i now holds items[(i+1) % n] — never items[i] — for n > 1.
    if (arr.length > 1 && arr.some((it, i) => it === items[i])) {
      return [...items.slice(1), items[0]];
    }
    return arr;
  });
  const [matched, setMatched] = useState({});      // word -> defIndex (0 is valid!)
  const [missed, setMissed] = useState({});        // word -> true (had a wrong attempt)
  const [selected, setSelected] = useState(null);  // word chosen by tap/keyboard
  const [done, setDone] = useState(false);
  /* Bug fix (Leo's live walkthrough): "Show the answers" used to set
     `done` directly, which jumps straight to StageComplete — the drawn
     connector lines this reveal computes never got a chance to render.
     `revealed` holds the filled-in board on screen; the student taps
     Continue when ready, which is what actually advances. */
  const [revealed, setRevealed] = useState(false);
  const [vocabPhase, setVocabPhase] = useState("cards"); // "cards" | "matching" | "review"
  const [matchScore, setMatchScore] = useState({ correct: 0, total: 0 });
  const hasReview = !!(bp.vocabReviewExercises && (bp.vocabReviewExercises.oddOneOut || bp.vocabReviewExercises.completeSentences));
  const [dragState, setDragState] = useState(null);
  const [lines, setLines] = useState([]);
  const [wrongFlash, setWrongFlash] = useState(null);
  const [justMatched, setJustMatched] = useState(null); // word -> plays the pop animation
  const gridRef = React.useRef(null);
  const wordRefs = React.useRef({});
  const defRefs = React.useRef({});
  // The drag is held in a REF as well as in state. State drives the rendered
  // line; the ref is what the logic reads, so a pointerdown/pointerup pair that
  // lands inside a single React batch can never lose the gesture.
  const dragRef = React.useRef(null);

  const getPos = (el, side) => {
    if (!el || !gridRef.current) return { x: 0, y: 0 };
    const grid = gridRef.current.getBoundingClientRect();
    const r = el.getBoundingClientRect();
    return { x: side === "right" ? r.right - grid.left : r.left - grid.left, y: r.top + r.height / 2 - grid.top };
  };

  const hitTestDef = (clientX, clientY) => {
    for (let i = 0; i < defs.length; i++) {
      const el = defRefs.current[i];
      // NB: matched[] stores a definition INDEX — 0 is a valid, falsy match.
      if (!el || matched[defs[i].word] !== undefined) continue;
      const r = el.getBoundingClientRect();
      if (clientX >= r.left - 8 && clientX <= r.right + 8 && clientY >= r.top - 8 && clientY <= r.bottom + 8) return i;
    }
    return -1;
  };

  /* The ONE matching rule — drag, tap and keyboard all come through here. */
  const attemptMatch = (word, wordIdx, defIdx) => {
    if (defIdx < 0 || matched[word] !== undefined) return;
    if (defs[defIdx].word === word) {
      const nextMatched = { ...matched, [word]: defIdx };
      setMatched(nextMatched);
      setLines((prev) => [...prev, { word, wordIdx, defIdx }]);
      setJustMatched(word);
      setTimeout(() => setJustMatched((w) => (w === word ? null : w)), 500);
      leoMemory.practiceWord(word, !missed[word]);
      setSelected(null);
      if (Object.keys(nextMatched).length === items.length) setDone(true);
    } else {
      setMissed((m) => ({ ...m, [word]: true }));
      setWrongFlash({ wordIdx, defIdx });
      setTimeout(() => setWrongFlash(null), 600);
      setSelected(null);
    }
  };

  const startDrag = (word, wordIdx, e) => {
    if (matched[word] !== undefined) return; // 0 is a valid definition index
    e.preventDefault();
    const grid = gridRef.current.getBoundingClientRect();
    const d = { word, wordIdx, x: e.clientX - grid.left, y: e.clientY - grid.top, sx: e.clientX, sy: e.clientY };
    dragRef.current = d;
    setDragState(d);
  };
  const moveDrag = (e) => {
    if (!dragRef.current || !gridRef.current) return;
    e.preventDefault();
    const grid = gridRef.current.getBoundingClientRect();
    setDragState((prev) => (prev ? { ...prev, x: e.clientX - grid.left, y: e.clientY - grid.top } : null));
  };
  const endDrag = (e) => {
    const d = dragRef.current;
    if (!d) return;
    dragRef.current = null;
    const moved = Math.hypot(e.clientX - d.sx, e.clientY - d.sy) > 6;
    if (!moved) {
      // A press with no movement is a TAP: select the word, then tap a meaning.
      setSelected((s) => (s === d.word ? null : d.word));
    } else {
      attemptMatch(d.word, d.wordIdx, hitTestDef(e.clientX, e.clientY));
    }
    setDragState(null);
  };

  const reveal = () => {
    const newMatched = {}; const newLines = []; const newMissed = { ...missed };
    items.forEach((it, wi) => {
      if (matched[it.word] === undefined) {
        leoMemory.practiceWord(it.word, false);
        // A revealed word was NOT known. It must not be scored as if it were:
        // false praise is worse than no praise, and it would quietly tell the
        // learner model this word is safe when it is the one needing most work.
        newMissed[it.word] = true;
      }
      const di = defs.findIndex((d) => d.word === it.word);
      newMatched[it.word] = di;
      newLines.push({ word: it.word, wordIdx: wi, defIdx: di });
    });
    setMatched(newMatched); setMissed(newMissed); setLines(newLines); setSelected(null); setRevealed(true);
  };

  const correct = items.filter((it) => matched[it.word] !== undefined && !missed[it.word]).length;
  const remaining = items.length - Object.keys(matched).length;

  const svgLines = lines.map((l) => {
    const from = getPos(wordRefs.current[l.wordIdx], "right");
    const to = getPos(defRefs.current[l.defIdx], "left");
    return { ...l, x1: from.x, y1: from.y, x2: to.x, y2: to.y };
  });
  const dragLine = dragState ? (() => {
    const from = getPos(wordRefs.current[dragState.wordIdx], "right");
    return { x1: from.x, y1: from.y, x2: dragState.x, y2: dragState.y };
  })() : null;
  const wrongLine = wrongFlash ? (() => {
    const from = getPos(wordRefs.current[wrongFlash.wordIdx], "right");
    const to = getPos(defRefs.current[wrongFlash.defIdx], "left");
    return { x1: from.x, y1: from.y, x2: to.x, y2: to.y };
  })() : null;

  // Vocabulary review phase: after matching, if review exercises exist, render them
  if (done && vocabPhase === "review" && hasReview) return (
    <SectionShell title="Vocabulary review" blurb="Let's check those words have stuck." onSkip={onSkip}>
      <VocabReviewExercise
        exercises={bp.vocabReviewExercises}
        vocab={(bp.vocabulary || []).map((v) => v.word)}
        onVocabTap={onVocabTap}
        onDone={(revCorrect, revTotal) => {
          const totalCorrect = matchScore.correct + revCorrect;
          const totalQuestions = matchScore.total + revTotal;
          onDone(totalCorrect, totalQuestions);
        }}
      />
    </SectionShell>
  );

  if (done) return (
    <SectionShell header={header} title="Today's vocabulary" onSkip={onSkip}>
      <StageComplete correct={correct} total={items.length}
        onContinue={() => {
          if (hasReview) {
            setMatchScore({ correct, total: items.length });
            setVocabPhase("review");
          } else {
            onDone(correct, items.length);
          }
        }} />
    </SectionShell>
  );

    // §10.1: word cards run before the matching exercise
  if (vocabPhase === "cards") return (
    <SectionShell header={header} title="Today's vocabulary" blurb="Let's meet today's words." onSkip={onSkip}>
      <WordCardSequence
        words={items}
        onComplete={() => setVocabPhase("matching")}
        onVocabTap={onVocabTap}
        lastLabel="Start matching"
      />
    </SectionShell>
  );

  return (
    <SectionShell header={header} title="Today's vocabulary"
      blurb={selected ? `“${selected}” is selected — now choose its meaning.` : "Drag a line from each word to its meaning — or tap a word, then tap its meaning."}
      onSkip={onSkip}>
      <div className="match-progress" aria-live="polite">
        <div className="match-progress-bar"><span style={{ width: `${(Object.keys(matched).length / items.length) * 100}%` }} /></div>
        <span className="muted small">{remaining} to go</span>
      </div>

      {/* Pointer Events cover mouse, touch and stylus on every supported browser
          (touchAction:none stops the page scrolling mid-drag). Do NOT add parallel
          onTouch* handlers: they double-fire alongside pointer events, and a Touch
          object has no preventDefault, which crashes on mobile. */}
      <div className="match-grid" ref={gridRef} style={{ position: "relative", touchAction: "none" }}
        onPointerMove={moveDrag} onPointerUp={endDrag} onPointerLeave={endDrag}>
        <svg className="match-lines" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", pointerEvents: "none", zIndex: 3 }}>
          {svgLines.map((l, i) => (
            <line key={"m" + i} x1={l.x1} y1={l.y1} x2={l.x2} y2={l.y2} stroke="var(--leo-green)" strokeWidth="2.5" strokeLinecap="round" opacity="0.75">
              <animate attributeName="opacity" from="0" to="0.75" dur="0.3s" fill="freeze" />
            </line>
          ))}
          {dragLine && <line x1={dragLine.x1} y1={dragLine.y1} x2={dragLine.x2} y2={dragLine.y2} stroke="var(--color-warning)" strokeWidth="3" strokeLinecap="round" strokeDasharray="6 5" opacity="0.9" />}
          {wrongLine && (
            <line x1={wrongLine.x1} y1={wrongLine.y1} x2={wrongLine.x2} y2={wrongLine.y2} stroke="var(--color-error)" strokeWidth="2.5" strokeLinecap="round" opacity="0.75">
              <animate attributeName="opacity" from="0.75" to="0" dur="0.5s" fill="freeze" />
            </line>
          )}
        </svg>

        <div className="match-col" style={{ position: "relative", zIndex: 2 }}>
          {items.map((it, i) => {
            const isMatched = matched[it.word] !== undefined;
            return (
              <button key={it.word} type="button" ref={(el) => (wordRefs.current[i] = el)}
                className={"match-word"
                  + (isMatched ? " match-done" : "")
                  + (justMatched === it.word ? " match-pop" : "")
                  + (selected === it.word ? " match-selected" : "")
                  + (dragState && dragState.word === it.word ? " match-dragging" : "")}
                disabled={isMatched}
                aria-pressed={selected === it.word}
                aria-label={isMatched ? `${it.word}, matched` : `${it.word}, select then choose its meaning`}
                onPointerDown={(e) => startDrag(it.word, i, e)}
                onClick={(e) => { if (e.detail === 0 && !isMatched) setSelected((s) => (s === it.word ? null : it.word)); }}>
                {it.word}
              </button>
            );
          })}
        </div>

        <div className="match-col" style={{ position: "relative", zIndex: 2 }}>
          {defs.map((it, i) => {
            const isMatched = matched[it.word] !== undefined;
            return (
              <button key={i} type="button" ref={(el) => (defRefs.current[i] = el)}
                className={"match-meaning" + (isMatched ? " match-done" : "") + (selected && !isMatched ? " match-target" : "")}
                disabled={isMatched}
                aria-label={isMatched ? `Meaning matched: ${it.meaning}` : selected ? `Match “${selected}” to: ${it.meaning}` : it.meaning}
                onClick={() => { if (selected) attemptMatch(selected, items.findIndex((x) => x.word === selected), i); }}>
                {it.meaning}
              </button>
            );
          })}
        </div>
      </div>

      {revealed
        ? <button className="primary-btn" onClick={() => setDone(true)}>Continue</button>
        : <button className="ghost-btn" onClick={reveal}>Show the answers</button>}
    </SectionShell>
  );
}

/* ---------- Stage 3: Pronunciation — model, listen, try ---------- */
function PronunciationSection({ bp, onVocabTap, onSkip, onDone, header, studentCountry, personalisationFacts }) {
  // Defect 4 fix: cards are built DIRECTLY from focusSections — each one
  // already carries everything a card needs (targetWord, ipa, instructions,
  // practiceWords, correct, incorrect). No backward matching onto
  // bp.vocabulary: the prompt explicitly allows a focus word to come from a
  // grammar example or functional-language phrase, not just the vocabulary
  // set, so matching against vocabulary alone silently dropped real data.
  const focusSections = bp.pronunciation && bp.pronunciation.focusSections;
  /* §3d — authored lessons carry `targets`, which may include PAIR
     items (the stress shift is the content). Without this the authored
     pronunciation stage silently fell back to bare vocabulary cards
     and the shift — the actual teaching point — never rendered. */
  const rawTargets = (bp.pronunciation && bp.pronunciation.targets) || null;
  /* Personalisation reorder (generalised, fix 4): reads any fact the
     lesson's personalisation.reads array names for pronunciation, rather
     than assuming studentCountry is always the right one. Falls back to
     studentCountry for U1L1, which predates the generalisation. Never
     fabricates IPA or stress data — reorders authored, vetted pairs only. */
  const reorderFact = React.useMemo(() => {
    const pFacts = personalisationFacts || {};
    const reads = (bp.personalisation && bp.personalisation.reads) || [];
    for (const r of reads) {
      const val = pFacts[r.fact];
      if (val && r.usedIn && r.usedIn.some((u) => /pronun/i.test(u)))
        return String(val).trim().toLowerCase();
    }
    return studentCountry ? String(studentCountry).trim().toLowerCase() : null;
  }, [bp, personalisationFacts, studentCountry]);
  const targets = React.useMemo(() => {
    if (!rawTargets || !reorderFact) return rawTargets;
    const idx = rawTargets.findIndex((t) =>
      (t.type === "pair" && (String(t.from.word).toLowerCase() === reorderFact || String(t.to.word).toLowerCase() === reorderFact)) ||
      (t.type === "single" && String(t.word).toLowerCase() === reorderFact));
    if (idx <= 0) return rawTargets;
    const reordered = rawTargets.slice();
    const [mine] = reordered.splice(idx, 1);
    reordered.unshift(mine);
    return reordered;
  }, [rawTargets, reorderFact]);
  const [done, setDone] = useState(false);
  const [everSpoke, setEverSpoke] = useState(false);
  const [pairIdx, setPairIdx] = useState(0);

  if (targets && targets.length > 0) {
    const t = targets[pairIdx];
    const isLast = pairIdx + 1 >= targets.length;
    if (!t) return null;
    return (
      <SectionShell header={header} title="Say it like a local" onSkip={onSkip}>
        <ExerciseChrome index={pairIdx} total={targets.length} label="Sound" />
        {/* Shown only when factually true: the leading pair genuinely
            matches the student's own stated country. */}
        {pairIdx === 0 && studentCountry && t.type === "pair" &&
          (String(t.from.word).toLowerCase() === String(studentCountry).toLowerCase()
            || String(t.to.word).toLowerCase() === String(studentCountry).toLowerCase()) && (
          <p className="ex-instruction">Your own country first.</p>
        )}
        {t.type === "pair"
          ? <PronPairCard pair={t} />
          : <div className="pp-card"><div className="pp-rows">
              <div className="pp-word">
                <p className="pp-word-plain">{t.word}</p>
                <div className="pp-syls">{(t.syllables || [t.word]).map((s, i) => (
                  <span key={i} className={"pp-syl" + (i === t.stressIndex ? " pp-syl-on" : "")}>{s}</span>))}</div>
                <p className="pp-ipa">{t.ipa}</p>
                <SpeakButton text={t.word} label={`Hear ${t.word}`} />
              </div>
            </div>{t.note && <p className="pp-note">{t.note}</p>}</div>}
        <button className="primary-btn wide" onClick={() => (isLast ? onDone() : setPairIdx(pairIdx + 1))}>
          {isLast ? "Finish practice" : "Next →"}
        </button>
      </SectionShell>
    );
  }

  const cards = React.useMemo(() => {
    if (focusSections && focusSections.length > 0) {
      return focusSections
        .filter((fs) => fs.targetWord)
        .map((fs) => ({ word: fs.targetWord, ipa: fs.ipa, _pronunciation: fs }));
    }
    // No focus data at all — fall back to bare vocabulary cards, same as
    // before this fix (word + IPA + Hear it + Next, no pronunciation block).
    return (bp.vocabulary || []).slice(0, 8);
  }, [bp.vocabulary, focusSections]);

  /* Fix P-2: the vocab fallback above never carries _pronunciation — a card
     from that branch has no stress row, no L1 note, no correct/incorrect
     models, no practice words. A stage titled "Say it like a local" with
     none of that is an empty shell wearing the right title. hasPronunciationContent
     is true only for cards built from focusSections (the only branch that ever
     sets _pronunciation), so it is false both when cards is empty and when every
     card came from the vocab fallback — exactly the condition to skip. Fires as
     an effect, matching this file's existing advance-in-effect convention (the
     {skipped:true} pattern above): advancing during render causes duplicate
     writes and React update-in-render errors. */
  const hasPronunciationContent = cards.some((c) => c._pronunciation);
  useEffect(() => {
    if (!hasPronunciationContent) onSkip?.();
  }, [hasPronunciationContent]);

  if (done) return (
    <SectionShell header={header} title="Say it like a local" onSkip={onSkip}>
      <StageComplete message={
        everSpoke
          ? { title: "You had a go out loud.",
              sub: "That\u2019s the part that actually changes pronunciation. Keep going with the rest of today\u2019s words \u2014 out loud, even quietly, wherever you are." }
          : { title: "That\u2019s the sounds covered.",
              sub: "You\u2019ve seen how these words are built. Pronunciation only changes once the words leave your mouth \u2014 say three of them out loud before today\u2019s over." }
      } onContinue={onDone} />
    </SectionShell>
  );

  return (
    <SectionShell header={header} title="Say it like a local"
      blurb={bp.pronunciation && bp.pronunciation.focus ? `Today\u2019s focus: ${bp.pronunciation.focus}.` : undefined}
      onSkip={onSkip}>
      <PronCardSequence
        words={cards}
        onComplete={() => setDone(true)}
        onVocabTap={onVocabTap}
        lastLabel="Continue"
        onSpoke={() => setEverSpoke(true)}
      />
    </SectionShell>
  );
}

/* ---------- Sentence frames panel (reusable) ---------- */
function SentenceFramesPanel({ frames, label }) {
  const [open, setOpen] = useState(false);
  if (!frames || !frames.length) return null;
  return (
    <div className="frames-panel">
      <button className="ghost-btn wide" onClick={() => setOpen(!open)}>
        {open ? "Hide" : "Show"} {label || "sentence frames"}
      </button>
      {open && (
        <div className="frames-list">
          {frames.map((f, i) => (
            <div key={i} className="frame-item">
              <p className="frame-text">{f.frame}</p>
              {f.example && <p className="frame-example muted small">e.g. {f.example}</p>}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/* ---------- Stage 4: Speaking — conversation, discussion, critical thinking ---------- */
/* ================================================================
   PHASE 9 — SPEAKER SYSTEM, PAIR CARD, LISTENING (§4.1, §3d, §3g)
   ================================================================ */

/* §4.1 — one speaker component, product-wide. lucide Volume2, not the
   emoji: emoji is Leo's VOICE, not UI chrome.

   When TTS is unavailable the button DOES NOT RENDER. Never a disabled
   speaker — a dead control teaches the student to stop trying
   controls, and a pronunciation card without sound still teaches
   stress and IPA.

   No persistent played-state: hearing again is always equally invited. */
function SpeakButton({ text, label, className, rate }) {
  const [playing, setPlaying] = useState(false);
  if (!TTS_OK || !text) return null;
  const speak = () => {
    setPlaying(true);
    speakText(text, rate ? { rate } : undefined);
    /* The utterance has no reliable end event across browsers, so the
       dimmed state is time-boxed rather than pretending to track it. */
    setTimeout(() => setPlaying(false), Math.min(6000, 900 + String(text).length * 55));
  };
  return (
    <button type="button" className={"speak-btn" + (className ? " " + className : "") + (playing ? " speak-btn-on" : "")}
      onClick={speak} aria-label={label || `Hear "${text}"`}>
      <Volume2 size={20} aria-hidden="true" />
    </button>
  );
}

/* §3d — the pronunciation pair card. The stress SHIFT is the content,
   so both words share ONE card and the shift is drawn. The syllable
   that GAINS the stress renders in --marker-orange: the marker points
   at what moved (§2a.4's rule). One card is one item in the sequence. */
function PronPairCard({ pair }) {
  if (!pair || !pair.from || !pair.to) return null;
  const row = (w, highlightShift) => (
    <div className="pp-word">
      {/* Bug fix (Leo's live walkthrough, 2nd pass): the plain word was
          spoken by the button but never shown — a student saw only the
          syllable/IPA breakdown with no way to know which word it was. */}
      <p className="pp-word-plain">{w.word}</p>
      <div className="pp-dots" aria-hidden="true">
        {(w.syllables || []).map((s, i) => (
          <span key={i} className={"pp-dot" + (i === w.stressIndex ? (highlightShift ? " pp-dot-moved" : " pp-dot-on") : "")} />
        ))}
      </div>
      <div className="pp-syls">
        {(w.syllables || []).map((s, i) => (
          <span key={i} className={"pp-syl" + (i === w.stressIndex ? (highlightShift ? " pp-syl-moved" : " pp-syl-on") : "")}>{s}</span>
        ))}
      </div>
      <p className="pp-ipa">{w.ipa}</p>
      <SpeakButton text={w.word} label={`Hear ${w.word}`} />
    </div>
  );
  /* The stress only "moves" if the index actually changes — otherwise
     orange would claim a shift that did not happen. */
  const moved = pair.from.stressIndex !== pair.to.stressIndex;
  return (
    <div className="pp-card">
      <div className="pp-rows">
        {row(pair.from, false)}
        <span className="pp-arrow" aria-hidden="true">&rarr;</span>
        {row(pair.to, moved)}
      </div>
      {pair.note && <p className="pp-note">{pair.note}</p>}
    </div>
  );
}

/* §3g — the listening player.
   NO SCRUBBER: a scrubber invites hunting for the answer inside the
   audio; at A1 the utterance is the unit, so replay is whole-utterance.

   NO REPLAY COUNT, overruling the brief with reasoning that Genesis
   ratified: a counter is a score in disguise — a student who has
   played four times reads "4" as their failure whatever tone it is set
   in, and the app has no pedagogical use for them seeing it. The
   POLICY is displayed instead, as permission. */
function ListeningPlayer({ text, onPlayed }) {
  const [playing, setPlaying] = useState(false);
  const [playedOnce, setPlayedOnce] = useState(false);
  if (!TTS_OK) {
    return (
      <div className="lp-card">
        <p className="muted small">Audio isn't available on this device, so the transcript is below instead.</p>
      </div>
    );
  }
  const play = () => {
    if (playing) {
      /* Pausing mid-utterance is allowed; resuming restarts the
         utterance, because the utterance is the unit. */
      if (window.speechSynthesis) window.speechSynthesis.cancel();
      setPlaying(false);
      return;
    }
    setPlaying(true);
    setPlayedOnce(true);
    speakText(String(text || "").replace(/\n/g, ". "));
    if (onPlayed) onPlayed();
    setTimeout(() => setPlaying(false), Math.min(60000, 1200 + String(text || "").length * 55));
  };
  return (
    <div className="lp-card">
      <button className="lp-play" onClick={play} aria-label={playing ? "Pause the audio" : (playedOnce ? "Play again" : "Play the audio")}>
        {playing ? <span className="lp-glyph">&#10073;&#10073;</span> : <span className="lp-glyph">&#9654;</span>}
      </button>
      <p className="lp-label">{playedOnce ? "Play again" : "Play the audio"}</p>
      {/* This line IS the display of unlimited replays — permission,
          without the surveillance a counter would bring. */}
      <p className="lp-permission">Listen as many times as you like.</p>
    </div>
  );
}

/* §3e — the AUTHORED speaking stage.
   The generic free conversation below is right for generated lessons.
   An authored lesson carries a designed sequence: a scenario, ordered
   turns, a repeat-after-me model before each student turn, and ONE
   sentence frame visible per turn.

   The one-frame rule is not cosmetic. The lesson plan states it
   prevents the stage's main error — reaching for "I'm ___" during the
   country turn and producing "I'm Brazil". Showing all three frames at
   once actively causes the mistake the teacher designed against. */
function AuthoredSpeaking({ bp, onSkip, onDone, header }) {
  const turns = bp.speakingTurns || [];
  const [idx, setIdx] = useState(0);
  const [thread, setThread] = useState([]);
  const [input, setInput] = useState("");
  const [busy, setBusy] = useState(false);
  const [replied, setReplied] = useState(false);
  const turn = turns[idx];
  const name = (bp._studentName || "").trim();

  if (!turn) {
    return (
      <SectionShell header={header} title="Speaking practice" onSkip={onSkip}>
        <StageComplete correct={turns.length} total={turns.length}
          message={{ title: "Nicely done", sub: "You introduced yourself — name, country and how you feel." }}
          onContinue={() => onDone(thread.filter((t) => t.role === "you").length, thread)} />
      </SectionShell>
    );
  }

  const prompt = turn.leoPromptTemplate
    ? String(turn.leoPromptTemplate).replace(/\{name\}/g, name || "there")
    : turn.leoPrompt;

  const send = async () => {
    if (!input.trim() || busy) return;
    const said = input.trim();
    setThread((t) => t.concat([{ role: "you", text: said }]));
    setInput("");
    setBusy(true);
    try {
      /* The authored correction bank is the teacher's own per-turn
         guidance. Passing it means Leo corrects the way this lesson
         says to correct, rather than improvising. */
      const bank = (bp.speakingCorrectionBank || [])
        .filter((c) => c.turn === turn.id || c.turn === "any")
        .map((c) => `- If they say ${c.studentSays} -> ${c.leoResponds}`)
        .join("\n");
      const raw = await askClaude(
        `${AUSTRALIAN_SPELLING}You are Leo, an ELICOS teacher. Scenario: ${bp.speakingScenario || bp.context}.\n` +
        `You asked: "${prompt}". The student answered: "${said}".\n` +
        `The target for this turn is: ${turn.frame}. They may answer in full or short form; BOTH are accepted.\n` +
        (bank ? `Correction guidance authored by their teacher — follow it:\n${bank}\n` : "") +
        `Reply warmly in ONE or TWO short sentences, max 20 words. If they need the form, model it and invite one more try. Never say "Wrong". Plain text only.`,
        { intent: "speaking_reply" }
      );
      setThread((t) => t.concat([{ role: "leo", text: String(raw || "").trim() }]));
      setReplied(true);
    } catch {
      setThread((t) => t.concat([{ role: "leo", text: "I couldn't reply just then — but I heard you. Let's keep going.", _failed: true }]));
      setReplied(true);
    } finally { setBusy(false); }
  };

  const next = () => { setIdx(idx + 1); setThread([]); setInput(""); setReplied(false); };

  return (
    <SectionShell header={header} title="Speaking practice" onSkip={onSkip}>
      <ExerciseChrome index={idx} total={turns.length} label="Turn" />
      {bp.speakingScenario && idx === 0 && <p className="ex-instruction">{bp.speakingScenario}</p>}
      <div className="bubble bubble-bot">
        {prompt}
        <SpeakButton text={prompt} />
      </div>
      {/* Repeat-after-me: the model comes BEFORE the student's turn. */}
      {turn.repeatAfterMe && !replied && (
        <div className="grammar-form-box">
          <p className="gb-keypoint-text">Repeat after me: <strong className="ex-answer">{turn.repeatAfterMe}</strong></p>
        </div>
      )}
      {/* Authored images for this turn (e.g. happy / sad), when present. */}
      {turn.images && !replied && (
        <div className="turn-images">
          {turn.images.map((im, i) => (
            <div key={i} className="turn-image-slot">
              <LessonImage src={im.src} alt={im.alt} caption={im.alt} />
            </div>
          ))}
        </div>
      )}
      <div className="speak-thread">
        {thread.map((t, i) => (
          <div key={i} className={"speak-turn " + (t.role === "leo" ? "speak-leo" : "speak-you")}>
            <p>{t.text}</p>
            {t.role === "leo" && !t._failed && <SpeakButton text={t.text} />}
          </div>
        ))}
        {busy && <Spinner label="Leo is listening…" />}
      </div>
      {!replied ? (
        <>
          {/* ONE frame for THIS turn — unless the lesson explicitly
              turns the rule off, in which case every frame shows and
              the current one leads. The authored flag decides. */}
          {turn.frame && (
            <FrameChips
              frames={bp.speakingOneFramePerTurn === false
                ? [{ frame: turn.frame }].concat(turns.filter((t) => t.frame && t.frame !== turn.frame).map((t) => ({ frame: t.frame })))
                : [{ frame: turn.frame }]}
              onInsert={(f) => setInput((v) => (v ? v + " " : "") + String(f).replace(/_+/g, "").trim())} />
          )}
          <div className="input-row">
            <input className="text-input" value={input} placeholder="Say or type your reply…"
              onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => e.key === "Enter" && send()}
              disabled={busy} {...EXERCISE_INPUT_PROPS_PROPER_NOUN} />
            <MicButton onText={(t) => setInput(t)} />
          </div>
          <div className="ex-actions">
            <button className="primary-btn" onClick={send} disabled={busy || !input.trim()}>Reply</button>
          </div>
        </>
      ) : (
        <button className="primary-btn wide" onClick={next}>
          {idx + 1 >= turns.length ? "Finish speaking" : "Next →"}
        </button>
      )}
    </SectionShell>
  );
}

function SpeakingSection({ bp, memory, vocab, onVocabTap, onSkip, onDone, header }) {
  /* §3e — an authored lesson runs its designed sequence; a generated
     lesson runs the free conversation below, unchanged. */
  if (bp.speakingTurns && bp.speakingTurns.length) {
    return <AuthoredSpeaking bp={bp} onSkip={onSkip} onDone={onDone} header={header} />;
  }
  const notes = bp._teacherNotes ? bp._teacherNotes.slice(0, 200) : "";
  // Capability: use discussion questions as prompts when available
  const discussionQs = bp.discussionQuestions || [];
  const hasDiscussion = discussionQs.length > 0;
  const hasCriticalThinking = !!(bp.criticalThinkingTask && bp.criticalThinkingTask.prompt);
  const speakFrames = bp.sentenceFrames && bp.sentenceFrames.speaking;
  const discFrames = bp.sentenceFrames && bp.sentenceFrames.discussion;
  const ctFrames = bp.sentenceFrames && bp.sentenceFrames.criticalThinking;

  const opener = hasDiscussion
    ? `Let's discuss: ${discussionQs[0]}`
    : `Let's practise for real. Imagine we're in this situation: ${bp.context}. I'll start — tell me what you would say first.`;
  const [turns, setTurns] = useState([{ role: "leo", text: opener }]);
  const [input, setInput] = useState("");
  const [thinking, setThinking] = useState(false);
  const [phase, setPhase] = useState("speak"); // "speak" | "critical" | "done"
  const leoTurns = turns.filter((t) => t.role === "leo").length;
  const youTurns = turns.filter((t) => t.role === "you").length;

  const send = async () => {
    const said = input.trim(); if (!said || thinking) return;
    const next = [...turns, { role: "you", text: said }];
    setTurns(next); setInput(""); setThinking(true);
    try {
      const convo = next.map((t) => (t.role === "leo" ? "Teacher: " : "") + t.text).join("\n");
      const discussionCtx = hasDiscussion ? `\nDiscussion questions to explore: ${discussionQs.join("; ")}` : "";
      const raw = await askClaude(
        `You are Leo, one of Australia's best ELICOS teachers, in a speaking practice about "${bp.context}" with your student (${memory}).\nObjective: ${bp.communicativeObjective}\nPredicted difficulties: ${(bp.predictedDifficulties || []).join("; ")}\nFinal task they are building toward: ${bp.finalTask || bp.communicativeObjective}\nEmotional objective: ${bp.emotionalObjective || "build confidence"}${discussionCtx}\n\nBehave like a real teacher: respond to WHAT they said, sound curious and warm, ask ONE genuine follow-up question. Encourage communication over perfection. If they make a predicted mistake, gently recast it — but never interrupt the flow. Keep it to 2-3 natural sentences.\n\n${convo}\n\nThe student just said: "${said}"\n\nReply as the teacher in plain text only.${narrationGuidance(bp.cefr, "corrective")}`,
        { intent: "speaking_reply" }
      );
      setTurns((t) => [...t, { role: "leo", text: raw }]);
    } catch {
      setTurns((t) => [...t, { role: "leo", text: "Good — keep going! What would you say next?" }]);
    }
    setThinking(false);
  };

  if (phase === "done") return (
    <SectionShell header={header} title="Speaking practice" onSkip={onSkip}>
      {/* Part B rev 2. "Excellent!" was awarded before anything was known and
          fired for "s". "N turns of REAL CONVERSATION" attached a fabricated
          adjective to a true number — a count is observation, its quality is
          not. The count now appears ONCE, and every screen ends with a next
          step rather than a verdict. youTurns is the only thing knowable here;
          nothing about content, ever. */}
      <StageComplete message={
        youTurns === 0
          ? { title: "Speaking practice",
              sub: "No turns this time. Speaking is the one part of English that only moves when you actually use it — it's here whenever you're ready." }
          : youTurns === 1
          ? { title: "You spoke once.",
              sub: "Speaking is the hardest skill to practise on your own. Next time, stay in for one turn longer than feels comfortable — that's where it grows." }
          : { title: `You spoke ${youTurns} times.`,
              sub: "Speaking is the hardest skill to practise on your own. Next time, aim for one more turn than today — that's how the habit builds." }
      }
        onContinue={() => onDone(youTurns, turns)} />
    </SectionShell>
  );

  // Capability: critical thinking task after speaking conversation
  if (phase === "critical" && hasCriticalThinking) {
    const ct = bp.criticalThinkingTask;
    return (
      <SectionShell title="Critical thinking" blurb="Use your English to solve a real problem." onSkip={() => setPhase("done")}>
        <p className="passage">{ct.prompt}</p>
        {ct.questions && ct.questions.map((q, i) => (
          <p key={i} className="small" style={{ marginTop: 4 }}>• {q}</p>
        ))}
        <SentenceFramesPanel frames={ctFrames} label="sentence frames" />
        <div style={{ marginTop: 12 }}>
          <div className="input-row">
            <input className="text-input" placeholder="Share your ideas…" value={input}
              onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => e.key === "Enter" && send()} />
            <MicButton onText={(t) => setInput(t)} />
          </div>
          <div className="speak-thread" style={{ marginTop: 8 }}>
            {turns.filter((_, i) => i > 0 || phase === "critical").map((t, i) => (
              <div key={i} className={"speak-turn " + (t.role === "leo" ? "speak-leo" : "speak-you")}>
                
                <p><VocabText text={t.text} vocab={vocab} onTap={onVocabTap} /></p>
              </div>
            ))}
            {thinking && <Spinner label="Leo is thinking…" />}
          </div>
          <div className="btn-row">
            <button className="primary-btn" onClick={send} disabled={thinking || !input.trim()}>Reply</button>
            <button className="ghost-btn" onClick={() => setPhase("done")}>Finish</button>
          </div>
        </div>
      </SectionShell>
    );
  }

  return (
    <SectionShell header={header} title="Speaking practice" blurb="Answer out loud with the mic, or type. This is about communicating, not being perfect." onSkip={onSkip}>
      {/* Capability: sentence frames scaffold when available */}
      {/* §3e — frames are persistent chips above the input, tap to
          insert, dismissible as a group for this session only. The old
          show/hide panel made scaffolding a decision with a cost; at A1
          the frames must simply be there. */}
      <div className="speak-thread">
        {turns.map((t, i) => (
          <div key={i} className={"speak-turn " + (t.role === "leo" ? "speak-leo" : "speak-you")}>
            
            <p><VocabText text={t.text} vocab={vocab} onTap={onVocabTap} /></p>
            {t.role === "leo" && <SpeakButton text={t.text} />}
          </div>
        ))}
        {thinking && <Spinner label="Leo is listening…" />}
      </div>
      <FrameChips frames={speakFrames || discFrames} onInsert={(f) => setInput((v) => (v ? v + " " : "") + String(f).replace(/_+/g, "").trim())} />
      <div className="input-row">
        <input className="text-input" placeholder="Say or type your reply…" value={input}
          onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => e.key === "Enter" && send()} />
        <MicButton onText={(t) => setInput(t)} />
      </div>
      <div className="btn-row">
        <button className="primary-btn" onClick={send} disabled={thinking || !input.trim()}>Reply</button>
        {/* §3e — finishing is available, never pushed. The authored
            minimum decides when it appears; 3 is the fallback for
            generated lessons, which carry no such figure. */}
        {leoTurns >= (bp.speakingMinExchanges || 3) && (
          <button className="ghost-btn" onClick={() => {
            if (hasCriticalThinking) setPhase("critical");
            else setPhase("done");
          }}>
            {hasCriticalThinking ? "Move to critical thinking" : "Finish speaking practice"}
          </button>
        )}
      </div>
    </SectionShell>
  );
}

/* ---------- Stage 5: Reading / Listening ----------
   Capability-driven: renders reading, listening, or both based on
   available content. Listening gap-fill uses GapFillInput when
   bp.listeningGapFill exists; otherwise falls back to MCQ comprehension.
   ------------------------------------------------------------------ */
function ListeningGapFillExercise({ gaps, onDone }) {
  const [idx, setIdx] = useState(0);
  const [correct, setCorrect] = useState(0);
  const [finished, setFinished] = useState(false);
  if (finished) return (
    <StageComplete correct={correct} total={gaps.length}
      message={{ title: "Listening complete!", sub: `${correct} out of ${gaps.length} — your ears are getting sharper.` }}
      onContinue={() => onDone(correct, gaps.length)} />
  );
  const g = gaps[idx];
  return (
    <div>
      <p className="muted small">Fill in the blank — {idx + 1} of {gaps.length}</p>
      <GapFillInput
        key={idx}
        stem={g.context}
        answers={g.answer}
        onDone={(ok) => {
          if (ok) setCorrect((c) => c + 1);
          setTimeout(() => {
            if (idx + 1 < gaps.length) setIdx(idx + 1);
            else setFinished(true);
          }, 1600);
        }}
      />
    </div>
  );
}

function SkillSection({ bp, section, vocab, onVocabTap, onSkip, onDone, header }) {
  /* §3f — the read-first gate and the scroll anchor. The anchor brings
     each new question to the top of the viewport, which is what keeps
     the passage exactly one upward flick away. Instant under reduced
     motion: the movement is a convenience, never information. */
  const [hasRead, setHasRead] = useState(false);
  const questionsRef = React.useRef(null);
  const scrollToQuestions = React.useCallback(() => {
    const el = questionsRef.current;
    if (!el || !el.scrollIntoView) return;
    const reduce = typeof window !== "undefined" && window.matchMedia
      && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    el.scrollIntoView({ behavior: reduce ? "auto" : "smooth", block: "start" });
  }, []);
  const isListening = bp.mainSkill === "listening";
  const hasListening = !!(bp.listeningScript || bp.listeningGapFill);
  const hasReading = !!(section && section.passage);
  // Capability: dual mode when both reading and listening content exist
  const isDual = hasReading && hasListening;
  const [phase, setPhase] = useState("reading"); // "reading" | "listening"
  const [readScore, setReadScore] = useState({ correct: 0, total: 0 });
  const [revealed, setRevealed] = useState(!isListening && !isDual);
  const [playedOnce, setPlayedOnce] = useState(false);
  const listenScript = bp.listeningScript || (section && section.passage) || "";

  // Phase: reading first, then listening (if dual)
  if (isDual && phase === "listening") {
    return (
      <SectionShell header={header} title="Listening" blurb="Listen carefully and fill in the missing words." onSkip={onSkip}>
        {/* §3g — whole-utterance replay, no scrubber, no count. */}
        <ListeningPlayer text={listenScript} onPlayed={() => setPlayedOnce(true)} />
        {bp.listeningGapFill ? (
          <ListeningGapFillExercise gaps={bp.listeningGapFill}
            onDone={(c, t) => onDone(readScore.correct + c, readScore.total + t)} />
        ) : (
          <div>
            <p className="passage"><VocabText text={listenScript} vocab={vocab} onTap={onVocabTap} /></p>
            <button className="primary-btn" onClick={() => onDone(readScore.correct, readScore.total)}>Continue</button>
          </div>
        )}
      </SectionShell>
    );
  }

  return (
    <SectionShell header={header} title={isListening ? "Listening" : "Reading"} blurb={isListening ? "Listen first for the general idea, then answer. You can replay as often as you like." : "Skim it once for the main idea, then read again for detail."} onSkip={onSkip}>
      {isListening ? (
        <div className="listen-box">
          {/* §3g — one 56px control, whole-utterance replay, permission
              line instead of a count. */}
          <ListeningPlayer text={section.passage} onPlayed={() => setPlayedOnce(true)} />
          {(revealed || !TTS_OK) ? (
            <p className="passage"><VocabText text={section.passage} vocab={vocab} onTap={onVocabTap} /></p>
          ) : (
            playedOnce && <button className="ghost-btn" onClick={() => setRevealed(true)}>Show transcript</button>
          )}
        </div>
      ) : (
        <p className="passage"><VocabText text={section.passage} vocab={vocab} onTap={onVocabTap} /></p>
      )}
      {/* §3f — one thing at a time: the passage renders alone first.
          Only after the student says they've read it do the questions
          arrive, with the passage retained above — re-reading is the
          task working, and it must cost one flick, not a decision. */}
      {!isListening && !hasRead ? (
        <button className="primary-btn wide" onClick={() => setHasRead(true)}>I've read it →</button>
      ) : (
        <div ref={questionsRef}>
          <AuthoredExerciseRunner
            exercises={bp.readingExercises}
            fallbackQuestions={section.questions}
            bp={bp} vocab={vocab} onVocabTap={onVocabTap}
            onAdvance={scrollToQuestions}
            onDone={(c, t) => {
              if (isDual) {
                setReadScore({ correct: c, total: t });
                setPhase("listening");
              } else {
                onDone(c, t);
              }
            }} />
        </div>
      )}
    </SectionShell>
  );
}

/* ---------- Stage 6: Grammar — meaning, form, usage, then practice ---------- */
/* ================================================================
   PHASE 2 — GRAMMAR PRESENTATION (Master Design Spec §2a)

   Authored lessons arrive with STRUCTURED grammar: subjects, a
   paradigm, labelled patterns. The existing prose treatment
   (Meaning / Form / When to use) was designed for GENERATED prose and
   remains the treatment for generated lessons — gram-ref-table is
   untouched. These blocks render only when bp.grammarBlocks exists.

   §2a.4 rules --marker-orange's defining role, once, for the product:
   orange is the teacher's marker pen — it annotates and points AT
   language; it never judges it and it never IS the language.
   ================================================================ */

/* §2a.2 — Block 1. Icon supports, never carries: the meaning is always
   also present in words, so the row survives the icon not loading and
   a screen reader never loses it (§4.5). */
/* The authored lesson uses all seven subjects, so the map covers more
   than the spec's three: "it = a thing" must not render as a person. */
const GRAM_SUBJECT_ICONS = { User, UserCheck, Users, Box };
function GrammarBlockSubjects({ block }) {
  if (!block || !Array.isArray(block.rows) || !block.rows.length) return null;
  return (
    <div className="gb-block">
      <p className="gram-section-label">{block.label || "WHO WE'RE TALKING ABOUT"}</p>
      <div className="gb-subject-rows">
        {block.rows.map((r, i) => {
          const Icon = GRAM_SUBJECT_ICONS[r.icon] || User;
          return (
            <div key={i} className="gb-subject-row">
              <Icon size={20} className="gb-subject-icon" aria-hidden="true" />
              <span className="gb-subject-word">{r.subject}</span>
              <span className="gb-subject-gloss">{r.gloss}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

/* §2a.3 — Block 2, the paradigm table: the whiteboard photo the student
   keeps. The hierarchy IS the teaching — the eye lands on what the
   mouth should say, so the short form is the largest, greenest thing
   in the box. Screenshot-clean: no controls inside the frame except
   the per-row speaker, which is the one thing a still image can't do. */
function GrammarBlockParadigm({ block }) {
  if (!block || !Array.isArray(block.rows) || !block.rows.length) return null;
  const heads = block.columnHeads || {};
  return (
    <div className="gb-block">
      <p className="gram-section-label">{block.label || "THE PATTERN"}</p>
      <div className="gb-paradigm">
        <div className="gb-para-heads" aria-hidden="true">
          <span className="gb-para-head">{heads.full || "Full"}</span>
          <span className="gb-para-head">{heads.short || "Short \u2014 say this one"}</span>
          <span className="gb-para-head gb-para-head-sound" />
        </div>
        {block.rows.map((r, i) => (
          <div key={i} className="gb-para-row">
            <span className="gb-para-full">{r.full}</span>
            <span className="gb-para-short">{r.short}</span>
            <span className="gb-para-sound">
              {/* Bug fix (Leo's live walkthrough, 2nd pass): contraction
                  forms (he's/she's/it's, etc.) played too fast to hear.
                  Applied to every row — the whole "short" column is
                  contractions, not just the three examples reported. */}
              <SpeakButton text={r.short} label={`Hear ${r.short}`} className="speak-btn-sm" rate={0.7} />
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

/* §2a.4 — Block 3. The category chip is orange because it POINTS at
   the language; the target form inside the sentence is green because
   it IS the language. */
function GrammarBlockPatterns({ block }) {
  if (!block || !Array.isArray(block.rows) || !block.rows.length) return null;
  return (
    <div className="gb-block">
      <p className="gram-section-label">{block.label || "WHAT COMES AFTER"}</p>
      {block.rows.map((r, i) => {
        const parts = r.target ? String(r.sentence).split(r.target) : null;
        return (
          <div key={i} className="gb-pattern-row">
            <span className="gb-pattern-sentence">
              {parts && parts.length > 1
                ? <>{parts[0]}<strong className="gb-pattern-target">{r.target}</strong>{parts.slice(1).join(r.target)}</>
                : r.sentence}
            </span>
            {r.category && <span className="gb-pattern-chip">{r.category}</span>}
          </div>
        );
      })}
    </div>
  );
}

/* Supporting authored blocks — rendered when present, never faked. */
function GrammarBlockWordClasses({ block }) {
  if (!block) return null;
  const row = (label, d) => d ? (
    <div className="gb-wc-row">
      <span className="gb-wc-term">{label}</span>
      <span className="gb-wc-def">{d.definition}{d.examples && d.examples.length ? ": " : ""}
        {d.examples && d.examples.length ? <em className="gb-wc-eg">{d.examples.join(", ")}</em> : null}</span>
    </div>
  ) : null;
  return (
    <div className="gb-block">
      <p className="gram-section-label">{block.label || "NOUN AND ADJECTIVE"}</p>
      {row("Noun", block.noun)}
      {row("Adjective", block.adjective)}
    </div>
  );
}

function GrammarBlockKeyPoint({ block }) {
  if (!block) return null;
  return (
    <div className="gb-block">
      <p className="gram-section-label">{block.label || "THE KEY POINT"}</p>
      <div className="grammar-form-box">
        <p className="gb-keypoint-text">{block.text}</p>
        {Array.isArray(block.pairs) && block.pairs.length > 0 && (
          <div className="gb-keypoint-pairs">
            {block.pairs.map((p, i) => (
              <span key={i} className="gb-keypoint-pair">
                <strong className="gb-pattern-target">{p.short}</strong> = {p.full}
              </span>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

function GrammarBlockQuestions({ block }) {
  if (!block) return null;
  return (
    <div className="gb-block">
      <p className="gram-section-label">{block.label || "QUESTIONS"}</p>
      {block.rule && <p className="gb-rule-line">{block.rule}</p>}
      {(block.transforms || []).map((t, i) => (
        <div key={i} className="gb-transform">
          <span className="gb-transform-from">{t.statement}</span>
          <span className="gb-transform-arrow" aria-hidden="true">&rarr;</span>
          <span className="gb-transform-to">{t.question}</span>
        </div>
      ))}
    </div>
  );
}

/* The blocks, in teaching order. Used by both the step-through (one
   per screen) and the stacked view (all at once), so the two can never
   drift apart. */
function grammarBlockList(blocks) {
  if (!blocks) return [];
  const out = [];
  if (blocks.subjects)    out.push({ key: "subjects",    node: <GrammarBlockSubjects block={blocks.subjects} /> });
  if (blocks.paradigm)    out.push({ key: "paradigm",    node: <GrammarBlockParadigm block={blocks.paradigm} /> });
  if (blocks.wordClasses) out.push({ key: "wordClasses", node: <GrammarBlockWordClasses block={blocks.wordClasses} /> });
  if (blocks.patterns)    out.push({ key: "patterns",    node: <GrammarBlockPatterns block={blocks.patterns} /> });
  if (blocks.keyPoint)    out.push({ key: "keyPoint",    node: <GrammarBlockKeyPoint block={blocks.keyPoint} /> });
  if (blocks.questions)   out.push({ key: "questions",   node: <GrammarBlockQuestions block={blocks.questions} /> });
  return out;
}

/* §2a.5 — the board, reachable from every exercise without leaving it.
   Reuses the VocabCardSheet mechanism (handle, scroll area,
   tap-outside-to-close) so the gesture is one the student already
   knows. The sheet closes onto exactly where they were. */
/* Bug fix (Leo's live walkthrough, 2nd pass): "Review the board" did not
   return the student to their place on close, contrary to §2a.5's
   spec ("closes onto exactly where they were"). Root cause: the sheet's
   fixed-position overlay has no body-scroll lock, which on real phones
   lets the background page's scroll position drift while the sheet is
   open — closing it then drops the student somewhere other than where
   they tapped from. This is the SAME overlay mechanism VocabCardSheet
   uses, so both sheets get the fix; a shared bug in a shared mechanism
   left half-fixed is still the bug.
   The lock captures the exact scroll position on open and explicitly
   restores it on close — a guarantee, not a hope. */
function useBodyScrollLock(active) {
  const savedY = React.useRef(0);
  React.useEffect(() => {
    if (!active || typeof document === "undefined") return;
    savedY.current = window.scrollY || window.pageYOffset || 0;
    const body = document.body;
    const prevPosition = body.style.position;
    const prevTop = body.style.top;
    const prevWidth = body.style.width;
    body.style.position = "fixed";
    body.style.top = "-" + savedY.current + "px";
    body.style.width = "100%";
    return () => {
      body.style.position = prevPosition;
      body.style.top = prevTop;
      body.style.width = prevWidth;
      window.scrollTo(0, savedY.current);
    };
  }, [active]);
}

function GrammarBoardSheet({ blocks, onClose }) {
  const list = grammarBlockList(blocks);
  useBodyScrollLock(list.length > 0);
  if (!list.length) return null;
  return (
    <div className="vocab-overlay" onClick={onClose} role="dialog" aria-modal="true" aria-label="The board">
      <div className="vocab-sheet" onClick={(e) => e.stopPropagation()}>
        <div className="vocab-sheet-handle" />
        {/* Bug fix (Leo's live walkthrough): tap-outside and swipe-down
            both worked, but neither is discoverable — the student had no
            visible way back to the exercise. This button is additive;
            the gestures still work exactly as before. */}
        <button type="button" className="vocab-sheet-close" onClick={onClose} aria-label="Back to the exercise">
          &larr; Back to the exercise
        </button>
        <div className="vocab-sheet-scroll">
          <div className="grammar-card">{list.map((b) => <div key={b.key}>{b.node}</div>)}</div>
        </div>
      </div>
    </div>
  );
}

/* The quiet link that opens it. Ghost by design — reference material
   must be reachable, never advertised. */
function ReviewBoardLink({ onOpen }) {
  return <button type="button" className="gb-review-link" onClick={onOpen}>Review the board</button>;
}

/* §2a.5 — step-through on FIRST presentation (one block per screen,
   each getting the student's whole attention), stacked on re-visit
   (a returning student re-reads; only a first-time student is walked).
   The signal is held completion state, which the code already has. */
function GrammarPresentation({ blocks, alreadySeen, onDone }) {
  const list = grammarBlockList(blocks);
  const [step, setStep] = useState(0);
  if (!list.length) return null;
  if (alreadySeen) {
    return (
      <div className="grammar-card">
        {list.map((b) => <div key={b.key} className="stage-enter">{b.node}</div>)}
        <button className="primary-btn" onClick={onDone}>Practise it</button>
      </div>
    );
  }
  const isLast = step + 1 >= list.length;
  return (
    <div className="grammar-card">
      <ExerciseChrome index={step} total={list.length} label="Board" />
      <div key={list[step].key} className="stage-enter">{list[step].node}</div>
      <button className="primary-btn" onClick={() => (isLast ? onDone() : setStep(step + 1))}>
        {isLast ? "Practise it" : "Next \u2192"}
      </button>
    </div>
  );
}


/* ================================================================
   PHASE 3 — TAP EXERCISE TYPES (Master Design Spec §2b.1, §2b.6)

   Both types share one interaction: tap a chip, the sentence completes.
   No confirm step — with a small option set the tap IS the decision.

   SPEC DEVIATION, deliberate and flagged: §2b.1 specifies TWO chips.
   The authored A1 lesson's Ex1 offers THREE (Am / Is / Are), which is
   the correct pedagogy for the be paradigm — a two-way choice cannot
   test a three-way distinction. The renderer therefore handles 2-4
   options. Everything else follows the spec exactly.
   ================================================================ */

/* The completed sentence, with the answer landing in the gap in the
   teacher's colour (§2b.1, §2c.2). Before the answer, the gap is an
   underline roughly the width of the word that will fill it — the
   student can see how much is missing. */
function GapSentence({ stem, filled }) {
  const parts = String(stem || "").split(/_{2,}|\(\s*[^)]*\/[^)]*\s*\)/);
  if (parts.length < 2) {
    return <p className="ex-sentence">{stem}{filled ? <> <strong className="ex-answer">{filled}</strong></> : null}</p>;
  }
  return (
    <p className="ex-sentence">
      {parts[0]}
      {filled
        ? <strong className="ex-answer">{filled}</strong>
        : <span className="ex-gap" aria-label="missing word" />}
      {parts.slice(1).join("")}
    </p>
  );
}

/* Shared tap-chip body for §2b.1 and §2b.6.
   Correct: the chosen word lands in the gap; chips disappear.
   Wrong:   the CORRECT word fills the gap in green; the student's chip
            stays visible at 40% — no strikethrough, no red, no shake.
   No retry within the item: with a short option list a retry is a coin
   flip, not learning. The item re-attempts later via the Phase 1 queue. */
function TapChoiceItem({ item, options, onSettled, settled, chosen, shown, onPick, onShowMe, accepted }) {
  const answer = item.answer;
  const list = accepted || [answer];
  const isCorrect = list.indexOf(chosen) !== -1;
  /* If the student chose an answer the teacher also accepts, the
     sentence completes with THEIR word — replacing it with the primary
     answer would imply theirs was not the one that counted. */
  const fill = settled ? (isCorrect && chosen ? chosen : answer) : null;
  return (
    <>
      <GapSentence stem={item.stem} filled={fill} />
      {!settled && (
        <div className="ex-chips">
          {options.map((opt, i) => (
            <button key={i} className="ex-chip" onClick={() => onPick(opt)}>{opt}</button>
          ))}
        </div>
      )}
      {settled && chosen && !isCorrect && (
        <div className="ex-chips">
          <button className="ex-chip ex-chip-muted" disabled>{chosen}</button>
        </div>
      )}
      {!settled && <ShowMeLink onShow={onShowMe} shown={shown} />}
    </>
  );
}

/* §2b.1 — Type 1. Choose the correct form (recognition). */
function ChooseFormExercise({ exercise, onDone }) {
  const items = exercise.items || [];
  const q = useExerciseQueue(items);
  const [chosen, setChosen] = useState(null);
  const [shown, setShown] = useState(false);
  const [correct, setCorrect] = useState(0);
  const item = q.current;
  if (q.finished || !item) {
    return <StageComplete correct={correct} total={items.length} onContinue={() => onDone(correct, items.length)} />;
  }
  const options = item.options || exercise.options || [];
  const settled = !!chosen || shown;
  /* An item the teacher marked as having more than one correct answer
     must accept every one of them. Without this, a student choosing a
     teacher-approved answer is told they are wrong — the app
     contradicting the teacher. */
  const accepted = [item.answer].concat(item.alsoAccept || []);
  const wasCorrect = accepted.indexOf(chosen) !== -1;
  const pick = (opt) => { if (settled) return; setChosen(opt); if (accepted.indexOf(opt) !== -1) setCorrect((c) => c + 1); };
  const next = () => { q.advance(wasCorrect); setChosen(null); setShown(false); };
  return (
    <div className="ex-item">
      <ExerciseChrome index={q.index} total={q.total} />
      <TapChoiceItem item={item} options={options} settled={settled} chosen={chosen} shown={shown}
        accepted={accepted} onPick={pick} onShowMe={() => { setShown(true); }} />
      {settled && (
        <>
          {shown
            ? <CorrectAnswerReveal answer={item.answer} note={item.note || exercise.note} />
            : <LeoFeedback ok={wasCorrect}>{item.note || exercise.note || (wasCorrect ? "That's it." : null)}</LeoFeedback>}
          <button className="primary-btn" onClick={next}>
            {q.index + 1 >= q.total ? "Finish practice" : "Next \u2192"}
          </button>
        </>
      )}
    </div>
  );
}

/* §2b.6 — Type 6. Country or nationality (pattern discrimination).
   Type 1's interaction PLUS the accumulating evidence list, which is
   the entire point of the type: at the end the rule is not asserted by
   Leo, it is PROVEN by the student's own answers sitting beneath it. */
function CountryNationalityExercise({ exercise, onDone }) {
  const items = exercise.items || [];
  const q = useExerciseQueue(items);
  const [chosen, setChosen] = useState(null);
  const [shown, setShown] = useState(false);
  const [correct, setCorrect] = useState(0);
  const [evidence, setEvidence] = useState({ left: [], right: [] });
  const cols = exercise.evidenceColumns || { left: "FROM + COUNTRY", right: "BE + NATIONALITY" };
  const item = q.current;

  /* The payoff sits between the last item and the tick: the authored
     rule, above the evidence the student just built. Derived from the
     queue being finished — never set during render. */
  if (q.finished || !item) {
    if (!exercise.ruleLine) {
      return <StageComplete correct={correct} total={items.length} onContinue={() => onDone(correct, items.length)} />;
    }
    return (
      <div className="ex-item">
        <div className="grammar-form-box">
          <p className="gb-keypoint-text">{exercise.ruleLine}</p>
        </div>
        <EvidenceList cols={cols} evidence={evidence} />
        <button className="primary-btn" onClick={() => onDone(correct, items.length)}>Finish practice</button>
      </div>
    );
  }

  const options = item.options || exercise.options || [];
  const settled = !!chosen || shown;
  const wasCorrect = chosen === item.answer;
  const pick = (opt) => {
    if (settled) return;
    setChosen(opt);
    if (opt === item.answer) setCorrect((c) => c + 1);
  };
  const next = () => {
    /* The completed sentence files into its column — the CORRECT
       sentence, whatever the student chose, because the list is the
       evidence for the rule and must not teach the wrong pattern. */
    const side = item.column === "right" ? "right" : "left";
    const sentence = String(item.stem || "").replace(/\(\s*[^)]*\/[^)]*\s*\)/, item.answer).replace(/\?$/, "?");
    setEvidence((e) => ({ ...e, [side]: e[side].concat([{ text: sentence, target: item.answer }]) }));
    q.advance(wasCorrect);
    setChosen(null);
    setShown(false);
  };
  return (
    <div className="ex-item">
      <ExerciseChrome index={q.index} total={q.total} />
      <TapChoiceItem item={item} options={options} settled={settled} chosen={chosen} shown={shown}
        onPick={pick} onShowMe={() => { setShown(true); }} />
      {settled && (
        <>
          {shown
            ? <CorrectAnswerReveal answer={item.answer} note={item.note} />
            : <LeoFeedback ok={wasCorrect}>{item.note || (wasCorrect ? "That's it." : null)}</LeoFeedback>}
          <button className="primary-btn" onClick={next}>
            {q.index + 1 >= q.total ? "See the pattern" : "Next \u2192"}
          </button>
        </>
      )}
      <EvidenceList cols={cols} evidence={evidence} />
    </div>
  );
}

/* The two-column evidence list. Persists across the whole set and
   scrolls with the page; the active item stays put above it. */
function EvidenceList({ cols, evidence }) {
  if (!evidence.left.length && !evidence.right.length) return null;
  const col = (label, rows) => (
    <div className="ev-col">
      <p className="gram-section-label">{label}</p>
      {rows.map((r, i) => {
        const parts = r.target ? String(r.text).split(r.target) : null;
        return (
          <p key={i} className="ev-line stage-enter">
            {parts && parts.length > 1
              ? <>{parts[0]}<strong className="ev-target">{r.target}</strong>{parts.slice(1).join(r.target)}</>
              : r.text}
          </p>
        );
      })}
    </div>
  );
  return (
    <div className="ev-list">
      {col(cols.left, evidence.left)}
      {col(cols.right, evidence.right)}
    </div>
  );
}

/* Dispatcher. Routes an authored exercise to its renderer when one is
   built, and returns null when it is not — the caller then falls back
   to the Phase 0 MCQ adapter. Adding a type in a later phase is one
   line here; nothing else changes. */
const EXERCISE_RENDERERS = {
  choose_the_form: ChooseFormExercise,
  country_or_nationality: CountryNationalityExercise,
  gap_fill_typed: GapFillExercise,
  write_the_contraction: ContractionExercise,
  own_word: OwnWordExercise,
  word_order: WordOrderExercise,
  correct_the_mistake: CorrectMistakeExercise,
  ask_leo: AskLeoExercise,
  answer_leo: AskLeoExercise,
  /* Phase 10 */
  match_question_answer: MatchQuestionAnswerExercise,
  /* match_halves: identical {left, right} field shape as match_question_answer —
     alias, not a new renderer. Fixes silent-discard: items previously failed
     both EXERCISE_RENDERERS and the MCQ fallback (no {stem, answer}). */
  match_halves: MatchQuestionAnswerExercise,
  write_the_question: WriteTheQuestionExercise,
  /* Structural mismatch fixes */
  sort_into_groups: SortIntoGroupsExercise,
  build_the_sentence: BuildTheSentenceExercise,
  /* Reading-stage shapes. Each maps onto an interaction the student has
     already met, which is why they are adapters rather than new
     renderers: one interaction language across the product. */
  true_false: TrueFalseExercise,
  who_is_it: ChooseFormExercise,
  complete_from_text: GapFillExercise,
  yes_no_questions: GapFillExercise,
  about_you: OwnWordExercise,
};
/* bp is passed through because the conversation types read the
   lesson's sentence frames; the other renderers ignore it. */
function renderAuthoredExercise(exercise, onDone, bp) {
  if (!exercise || !exercise.exerciseType) return null;
  const R = EXERCISE_RENDERERS[exercise.exerciseType];
  if (!R) return null;
  return <R exercise={exercise} bp={bp} onDone={onDone} />;
}

/* Runs an authored lesson's grammar practice. Exercises whose renderer
   is built run in their authored order; everything not yet built is
   still covered by the Phase 0 MCQ adapter, so no authored content is
   silently dropped while the remaining types are under construction.
   As each phase lands, exercises move from the fallback into their own
   renderer with no change here. */
function AuthoredGrammarPractice({ bp, section, vocab, onVocabTap, onDone }) {
  /* Active exercises with registered renderers, PLUS deferred exercises
     that now have renderers (Phase 10 / structural fixes). U1L1's
     question-form deferred items (match_question_answer, write_the_question,
     ask_leo) will be skipped here because those types ARE registered — but
     their content is held for Unit 3 by the content ruling, so they were
     deliberately NOT activated in the active exercises array. Only the
     content that was deferred purely due to missing renderers (build_the_sentence,
     own_word with multi-blank) gets promoted. */
  const activeExercises = (bp.grammarExercises || []).filter((ex) => EXERCISE_RENDERERS[ex.exerciseType]);
  const promotedDeferred = (bp.grammarDeferredExercises || []).filter((ex) =>
    EXERCISE_RENDERERS[ex.exerciseType] &&
    /* Only promote exercises deferred purely because of a missing renderer.
       Items with deferredForUnit set were held by a content ruling, not a
       missing renderer — they stay archived. U1L1's question-form exercises
       carry deferredForUnit:3 and must remain held until Unit 3 is authored. */
    !ex.deferredForUnit
  );
  const authored = activeExercises.concat(promotedDeferred);
  const [step, setStep] = useState(0);
  const [score, setScore] = useState({ correct: 0, total: 0 });
  const finishAll = (c, t) => onDone(score.correct + c, score.total + t);
  if (step < authored.length) {
    const ex = authored[step];
    return (
      <div key={ex.exerciseType + step}>
        {ex.title && <p className="ex-ex-title">{ex.title}</p>}
        {renderAuthoredExercise(ex, (c, t) => {
          setScore((s) => ({ correct: s.correct + c, total: s.total + t }));
          setStep(step + 1);
        }, bp)}
      </div>
    );
  }
  const remaining = (section.questions || []).filter((qq) => !EXERCISE_RENDERERS[qq._exerciseType]);
  if (!remaining.length) {
    return <StageComplete correct={score.correct} total={score.total} onContinue={() => onDone(score.correct, score.total)} />;
  }
  return <McqQuiz questions={remaining} vocab={vocab} onVocabTap={onVocabTap} onDone={finishAll} />;
}

/* ================================================================
   PHASE 4 — TYPED EXERCISE TYPES (§2b.2, §2b.4, §2b.7)

   Typed production, where the keyboard itself can mark a student
   wrong. Every input here carries EXERCISE_INPUT_PROPS (Phase 1),
   except Type 7, where the student types a real proper noun and the
   keyboard genuinely helps.
   ================================================================ */

/* Shared acceptance surface (§2b.2), so all three types agree:
   case-insensitive, whitespace trimmed, terminal punctuation ignored,
   both apostrophe forms equal. Internal spelling must be exact — at A1
   spelling IS content, so a misspelling is a wrong-moment with the
   correct spelling shown as teaching, never a silent pass. */
function normaliseTypedAnswer(s) {
  return String(s || "")
    .trim()
    .toLowerCase()
    .replace(/[\u2018\u2019\u02BC\u0060\u00B4]/g, "'")   // curly/backtick → straight
    .replace(/[.!?]+$/, "")
    .replace(/\s+/g, " ");
}
function typedAnswerMatches(input, answers) {
  const list = Array.isArray(answers) ? answers : [answers];
  const got = normaliseTypedAnswer(input);
  return list.some((a) => normaliseTypedAnswer(a) === got);
}

/* §2b.2 — Type 2. Gap-fill, typed (cued production).
   GapFillInput (migrated in Phase 1) is the base; this wraps it as a
   set with the shared chrome and the re-queue rule. */
function GapFillExercise({ exercise, onDone }) {
  const items = exercise.items || [];
  const q = useExerciseQueue(items);
  const [correct, setCorrect] = useState(0);
  const [settledOk, setSettledOk] = useState(null);
  const item = q.current;
  if (q.finished || !item) {
    return <StageComplete correct={correct} total={items.length} onContinue={() => onDone(correct, items.length)} />;
  }
  const next = () => { q.advance(settledOk === true); setSettledOk(null); };
  return (
    <div className="ex-item" key={q.index}>
      <ExerciseChrome index={q.index} total={q.total} />
      <GapFillInput
        stem={item.stem}
        answers={[item.answer].concat(item.alsoAccept || [])}
        note={item.note || exercise.note}
        onDone={(ok) => { setSettledOk(ok); if (ok) setCorrect((c) => c + 1); }}
      />
      {settledOk !== null && (
        <button className="primary-btn" onClick={next}>
          {q.index + 1 >= q.total ? "Finish practice" : "Next \u2192"}
        </button>
      )}
    </div>
  );
}

/* §2b.4 — Type 4. Write the contraction (transformation).
   The student types ONLY the contracted form: retyping the rest is
   typing practice, not grammar, and a typo in the untargeted half
   would mark a correct transformation wrong.
   The source words carry a --marker-orange underline — the marker pen
   points at what changes (§2a.4's rule at work). */
function ContractionExercise({ exercise, onDone }) {
  const items = exercise.items || [];
  const q = useExerciseQueue(items);
  const [input, setInput] = useState("");
  const [checked, setChecked] = useState(null);
  const [shown, setShown] = useState(false);
  const [correct, setCorrect] = useState(0);
  const item = q.current;
  if (q.finished || !item) {
    return <StageComplete correct={correct} total={items.length} onContinue={() => onDone(correct, items.length)} />;
  }
  const settled = checked !== null || shown;
  const source = String(item.stem || "");
  const target = item.target || "";
  const parts = target ? source.split(target) : [source];
  const check = () => {
    if (!input.trim() || settled) return;
    const ok = typedAnswerMatches(input, [item.answer].concat(item.alsoAccept || []));
    setChecked(ok);
    if (ok) setCorrect((c) => c + 1);
  };
  const next = () => { q.advance(checked === true); setInput(""); setChecked(null); setShown(false); };
  return (
    <div className="ex-item" key={q.index}>
      <ExerciseChrome index={q.index} total={q.total} />
      {/* Source: the words that change carry the marker underline. */}
      <p className="ex-sentence">
        {parts.length > 1
          ? <>{parts[0]}<span className="ex-marked">{target}</span>{parts.slice(1).join(target)}</>
          : source}
      </p>
      {/* Target line: the input sits inline, so the line reads as a
          sentence with a blank rather than a form field. */}
      <p className="ex-sentence">
        {settled
          ? <strong className="ex-answer">{item.answer}</strong>
          : <input className="ex-inline-input" value={input} onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && check()} aria-label="Write the short form"
              {...EXERCISE_INPUT_PROPS} />}
        {item.rest ? <span> {item.rest}</span> : null}
      </p>
      {!settled && (
        <>
          <div className="ex-actions"><button className="primary-btn" onClick={check} disabled={!input.trim()}>Check</button></div>
          <ShowMeLink onShow={() => setShown(true)} shown={shown} />
        </>
      )}
      {settled && (
        <>
          {shown
            ? <CorrectAnswerReveal answer={item.answer} note={item.note} />
            : <LeoFeedback ok={checked}>{checked ? (item.note || "That's it.") : <>The answer is <strong className="ex-answer">{item.answer}</strong>. {item.note || ""}</>}</LeoFeedback>}
          <button className="primary-btn" onClick={next}>
            {q.index + 1 >= q.total ? "Finish practice" : "Next \u2192"}
          </button>
        </>
      )}
    </div>
  );
}

/* §2b.7 — Type 7. Complete with your own word (personalisation).
   THERE IS NO WRONG. Leo responds to the actual answer in a bubble —
   the first bubble the student meets in the exercise system,
   deliberately foreshadowing speaking.

   The design contract on the response: it MUST include the student's
   word, MUST include the full model sentence, and MUST NOT evaluate
   the fact. "Beautiful" is warmth; "that's correct" would be false
   authority over the student's own life.

   Autocorrect is ON here — the one deliberate exception to §2b.2's
   off-rule. The student is typing a real proper noun and the keyboard
   helping with "Brazil" is help, not sabotage. */
function OwnWordExercise({ exercise, onDone }) {
  const items = exercise.items || [];
  const [idx, setIdx] = useState(0);
  /* Fix 3: multi-blank support. inputs is an array, one slot per blank.
     Single-blank items use inputs[0] only, identical to before. */
  const [inputs, setInputs] = useState([""]);
  const [reply, setReply] = useState(null);
  const [busy, setBusy] = useState(false);
  const item = items[idx];

  /* Count blanks in the current item's stem. */
  const blanks = React.useMemo(() => {
    const matches = String(item ? item.stem : "").match(/_{2,}/g);
    return matches ? matches.length : 1;
  }, [item]);

  /* Reset inputs when the item changes. */
  React.useEffect(() => {
    setInputs(Array(blanks).fill(""));
  }, [idx, blanks]);

  if (!item) {
    return <StageComplete correct={items.length} total={items.length} onContinue={() => onDone(items.length, items.length)} />;
  }

  /* Build the model sentence by filling blanks left-to-right. */
  const buildModel = (vals) => {
    let s = String(item.stem || "");
    vals.forEach((v) => { s = s.replace(/_{2,}/, v.trim() || "_"); });
    return s;
  };
  const allFilled = inputs.every((v) => v.trim());
  const modelSentence = buildModel(inputs);

  const submit = async () => {
    if (!allFilled || busy || reply) return;
    setBusy(true);
    try {
      const filledWith = inputs.length === 1 ? inputs[0].trim() : inputs.map((v) => v.trim()).join(", ");
      const raw = await askClaude(
        `${AUSTRALIAN_SPELLING}You are Leo, an ELICOS teacher. Your A1 student completed "${item.stem}" with: "${filledWith}".\n` +
        `Reply in ONE short sentence, then the full sentence they built in bold.\n` +
        `RULES: include their word(s); include the full sentence "${modelSentence}" with the target form in **bold**; be warm; do NOT judge whether their answer is right or wrong — it is their own life, not a test. Max 20 words. Plain text only.`,
        { intent: "own_word_reply" }
      );
      setReply({ text: String(raw || "").trim() });
    } catch {
      setReply({ fallback: true });
    } finally { setBusy(false); }
  };

  const next = () => { setIdx(idx + 1); setInputs([""]); setReply(null); };
  const setInput = (i, v) => setInputs((prev) => { const n = prev.slice(); n[i] = v; return n; });

  return (
    <div className="ex-item" key={idx}>
      <ExerciseChrome index={idx} total={items.length} />
      {/* For multi-blank, show a GapSentence per blank filled so far,
          or a static display once replied. */}
      <GapSentence stem={item.stem} filled={reply ? inputs[0].trim() : null} />
      {item.hint && !reply && <p className="ex-hint">{item.hint}</p>}
      {!reply && (
        <>
          {inputs.map((val, i) => (
            <div className="input-row" key={i} style={{ marginTop: i > 0 ? "var(--space-2)" : undefined }}>
              {blanks > 1 && <span className="ex-hint" style={{ minWidth: "3ch", textAlign: "right" }}>{i + 1}.</span>}
              <input className="text-input" value={val}
                placeholder={"Type here\u2026"}
                onChange={(e) => setInput(i, e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && i === inputs.length - 1 && submit()}
                disabled={busy} {...EXERCISE_INPUT_PROPS_PROPER_NOUN} />
            </div>
          ))}
          <div className="ex-actions" style={{ marginTop: "var(--space-3)" }}>
            <button className="primary-btn" onClick={submit} disabled={!allFilled || busy}>
              {busy ? "\u2026" : "Send"}
            </button>
          </div>
        </>
      )}
      {reply && !reply.fallback && (
        <div className="bubble bubble-bot stage-enter">{reply.text}</div>
      )}
      {reply && reply.fallback && (
        <p className="ex-reveal text-leo">
          <strong className="ex-answer">{modelSentence}</strong>
        </p>
      )}
      {reply && (
        <button className="primary-btn" onClick={next}>
          {idx + 1 >= items.length ? "Finish practice" : "Next \u2192"}
        </button>
      )}
    </div>
  );
}

/* ================================================================
   PHASE 5 — TYPES 3 AND 5 (§2b.3, §2b.5)
   The two bespoke interactions.
   ================================================================ */

/* §2b.3 — Type 3. Word ordering (syntax awareness).
   TAP-TO-BUILD, not drag: drag demands two-handed precision and a
   stable surface; the design target is one thumb on a moving train.
   Tap gives identical cognitive work — choose the next word — with
   zero motor tax. */
function WordOrderExercise({ exercise, onDone }) {
  const items = exercise.items || [];
  const q = useExerciseQueue(items);
  const [built, setBuilt] = useState([]);      // [{tok, from}]
  const [pool, setPool] = useState(null);
  const [checked, setChecked] = useState(null);
  const [attempt, setAttempt] = useState(1);
  const [shown, setShown] = useState(false);
  const [correct, setCorrect] = useState(0);
  const item = q.current;

  /* Pool is shuffled once per item. Derived lazily so a re-queued item
     is genuinely re-shuffled rather than reappearing pre-solved. */
  const tokens = item ? (item.tokens || []) : [];
  const activePool = pool === null
    ? shuffleOptions(tokens.map((t, i) => ({ tok: t, id: i })), textSeed((item && item.answer) || "") + attempt)
    : pool;

  if (q.finished || !item) {
    return <StageComplete correct={correct} total={items.length} onContinue={() => onDone(correct, items.length)} />;
  }

  const settled = checked !== null || shown;
  const takeTile = (t) => {
    if (settled) return;
    setBuilt(built.concat([t]));
    setPool(activePool.filter((x) => x.id !== t.id));
  };
  const returnWord = (t) => {
    if (settled) return;
    setBuilt(built.filter((x) => x.id !== t.id));
    setPool(activePool.concat([t]));
  };
  const backspace = () => {
    if (settled || !built.length) return;
    returnWord(built[built.length - 1]);
  };
  const sentenceOf = (arr) => arr.map((x) => x.tok).join(" ").replace(/\s+([?.!,])/g, "$1");
  const check = () => {
    if (settled) return;
    const ok = typedAnswerMatches(sentenceOf(built), [item.answer].concat(item.alsoAccept || []));
    setChecked(ok);
    if (ok) setCorrect((c) => c + 1);
  };
  const tryAgain = () => {
    /* One retry: their first submission was informative, and a second
       attempt at ORDERING is genuine practice — unlike Type 1, where a
       retry on a short option list is a coin flip. */
    setBuilt([]); setPool(null); setChecked(null); setAttempt(attempt + 1);
  };
  const next = () => {
    q.advance(checked === true);
    setBuilt([]); setPool(null); setChecked(null); setShown(false); setAttempt(1);
  };
  const poolEmpty = activePool.length === 0;

  return (
    <div className="ex-item" key={q.index + "-" + attempt}>
      <ExerciseChrome index={q.index} total={q.total} />
      <p className="ex-instruction">Make the sentence:</p>
      {/* The assembly line looks increasingly like a sentence, because
          that is the point. Assembled words are words, not tiles. */}
      <div className={"wo-line" + (checked === true ? " wo-line-ok" : "")}>
        {built.length === 0
          ? <span className="wo-placeholder">Tap the words in order</span>
          : built.map((t) => (
              <button key={t.id} className="wo-word" onClick={() => returnWord(t)} disabled={settled}>{t.tok}</button>
            ))}
        {built.length > 0 && !settled && (
          <button className="wo-back" onClick={backspace} aria-label="Remove the last word">&#9003;</button>
        )}
      </div>
      {!settled && (
        <div className="wo-pool">
          {activePool.map((t) => (
            <button key={t.id} className="wo-tile" onClick={() => takeTile(t)}>{t.tok}</button>
          ))}
        </div>
      )}
      {/* Production deserves a deliberate submit, unlike Type 1's
          recognition tap — so Check appears only once the pool empties. */}
      {!settled && poolEmpty && (
        <div className="ex-actions stage-enter"><button className="primary-btn" onClick={check}>Check</button></div>
      )}
      {!settled && <ShowMeLink onShow={() => setShown(true)} shown={shown} />}
      {settled && (
        <>
          {shown
            ? <CorrectAnswerReveal answer={item.answer} note={item.note} />
            : checked
              ? <LeoFeedback ok>{item.note || "That's the order."}</LeoFeedback>
              : <LeoFeedback ok={false}>
                  {/* Their sentence stays above; the model sits here.
                      The difference IS the teaching — no red, no strike. */}
                  The order is <strong className="ex-answer">{item.answer}</strong>. {item.note || ""}
                </LeoFeedback>}
          {checked === false && attempt === 1 && !shown
            ? <button className="ghost-btn wide" onClick={tryAgain}>Try again</button>
            : <button className="primary-btn" onClick={next}>{q.index + 1 >= q.total ? "Finish practice" : "Next \u2192"}</button>}
        </>
      )}
    </div>
  );
}

/* §2b.5 — Type 5. Correct the mistake (noticing → repair).
   The most valuable type, and the one that must feel most like a
   teacher at the board. Two steps with a DESIGNED MOMENT between:
   notice, be told you noticed right, THEN repair. The pause is the
   design, not a delay. */
function CorrectMistakeExercise({ exercise, onDone }) {
  const items = exercise.items || [];
  const q = useExerciseQueue(items);
  const [noticed, setNoticed] = useState(false);   // the wrong span is marked
  const [misses, setMisses] = useState(0);         // wrong notices this item
  const [pressed, setPressed] = useState(null);
  const [repair, setRepair] = useState("");
  const [checked, setChecked] = useState(null);
  const [shown, setShown] = useState(false);
  const [correct, setCorrect] = useState(0);
  const item = q.current;
  if (q.finished || !item) {
    return <StageComplete correct={correct} total={items.length} onContinue={() => onDone(correct, items.length)} />;
  }

  /* Tokenise the sentence and locate the wrong span as WHOLE tokens.
     The span may be more than one word ("You are" → "Are you"), so the
     match is contiguous-run, not single-token equality. */
  const toks = String(item.stem || "").split(/\s+/);
  const wrongToks = String(item.wrongWord || "").split(/\s+/);
  const bare = (s) => String(s).replace(/[?.!,]+$/, "");
  let spanStart = -1;
  for (let i = 0; i <= toks.length - wrongToks.length; i++) {
    if (wrongToks.every((w, j) => bare(toks[i + j]) === bare(w))) { spanStart = i; break; }
  }
  const inSpan = (i) => spanStart >= 0 && i >= spanStart && i < spanStart + wrongToks.length;
  /* The repair replaces the whole span, but the LAST token of that span
     may carry the sentence's punctuation ("Japan." -> "Brazil"). Carry
     it across, or the sentence heals into something that is no longer
     correct English — which is the one thing this exercise must never
     teach. */
  const spanTail = spanStart >= 0
    ? (String(toks[spanStart + wrongToks.length - 1] || "").match(/[?.!,]+$/) || [""])[0]
    : "";
  const healedText = String(item.answer || "") + spanTail;

  const tapWord = (i) => {
    if (noticed || shown) return;
    if (inSpan(i)) { setNoticed(true); setPressed(null); return; }
    /* A wrong notice marks nothing permanent. The hint points at the
       CATEGORY, never the answer. */
    setPressed(i);
    const next = misses + 1;
    setMisses(next);
    /* Second wrong notice: Leo circles it for them and the repair still
       happens — that half is what produces language. */
    if (next >= 2) setNoticed(true);
  };
  const settled = checked !== null || shown;
  const check = () => {
    if (!repair.trim() || settled) return;
    const ok = typedAnswerMatches(repair, [item.answer].concat(item.alsoAccept || []));
    setChecked(ok);
    if (ok && misses === 0) setCorrect((c) => c + 1);
  };
  const next = () => {
    q.advance(checked === true && misses === 0);
    setNoticed(false); setMisses(0); setPressed(null); setRepair(""); setChecked(null); setShown(false);
  };
  const options = item.options || exercise.options;

  return (
    <div className="ex-item" key={q.index}>
      <ExerciseChrome index={q.index} total={q.total} />
      <p className="ex-instruction">{noticed ? "What should it be?" : "Find the word that's wrong \u2014 tap it:"}</p>
      {/* A sentence lightly cut apart — not buttons, not tiles. */}
      <div className="cm-sentence">
        {toks.map((t, i) => {
          const marked = noticed && inSpan(i);
          const healed = marked && settled;
          /* When the span heals, the repair replaces it as ONE word —
             the remaining tokens of a multi-word span are dropped, not
             rendered as empty buttons. */
          if (healed && i !== spanStart) return null;
          return (
            <button key={i}
              className={"cm-word" + (marked ? " cm-word-marked" : "") + (healed ? " cm-word-healed" : "") + (pressed === i ? " cm-word-pressed" : "")}
              onClick={() => tapWord(i)} disabled={noticed || shown}>
              {healed ? healedText : t}
            </button>
          );
        })}
      </div>
      {/* The moment between: told you noticed right, before repairing. */}
      {noticed && !settled && misses === 0 && <p className="cm-beat stage-enter">That's the one.</p>}
      {noticed && !settled && misses > 0 && (
        <p className="cm-beat stage-enter">
          {"Here it is \u2014 that's " + (item.hintWord || exercise.hintWord || "the one") + "."}
        </p>
      )}
      {!noticed && pressed !== null && (
        <p className="cm-hint stage-enter">
          {/* Bug fix: this used to hardcode "look at the verb", which
              was only ever true for Unit 1 Lesson 1's am/is/are
              mistakes. Later lessons introduced article and possessive
              mistakes, and the hint kept saying "verb" regardless —
              actively misdirecting the student. Now reads the item's
              or exercise's authored category; falls back to a phrase
              that's never wrong instead of one that's specifically
              wrong. */}
          Not that one. Look at {item.hintWord || exercise.hintWord || "the other word"}.
        </p>
      )}
      {noticed && !settled && (
        <>
          {options && options.length >= 2
            ? <div className="ex-chips">
                {options.map((o, i) => (
                  <button key={i} className="ex-chip" onClick={() => { setRepair(o); setChecked(typedAnswerMatches(o, [item.answer])); if (typedAnswerMatches(o, [item.answer]) && misses === 0) setCorrect((c) => c + 1); }}>{o}</button>
                ))}
              </div>
            : <div className="ex-actions">
                <input className="ex-inline-input" value={repair} onChange={(e) => setRepair(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && check()} aria-label="Write the correction"
                  {...EXERCISE_INPUT_PROPS} />
                <button className="primary-btn" onClick={check} disabled={!repair.trim()}>Check</button>
              </div>}
          <ShowMeLink onShow={() => setShown(true)} shown={shown} />
        </>
      )}
      {settled && (
        <>
          {shown
            ? <CorrectAnswerReveal answer={item.answer} note={item.note} />
            : <LeoFeedback ok={checked}>
                {checked ? (item.note || "That's it \u2014 the sentence is right now.")
                         : <>It should be <strong className="ex-answer">{item.answer}</strong>. {item.note || ""}</>}
              </LeoFeedback>}
          <button className="primary-btn" onClick={next}>{q.index + 1 >= q.total ? "Finish practice" : "Next \u2192"}</button>
        </>
      )}
    </div>
  );
}

/* ================================================================
   PHASE 6 — TYPE 8 + SPEAKING DELTAS (§2b.8, §3e)

   One build serving two stages. The continuity is deliberate and
   total: the student practises the CONVERSATION SURFACE here with
   scaffolding, then meets the identical surface in speaking without
   it. Same bubbles, same input row, same mic parity.

   DIRECTION NOTE. §2b.8 specifies Leo asking and the student
   answering. The authored lesson's Ex9 INVERTS this: the student
   asks, Leo answers — because in a 1-to-1 app Leo is the partner, and
   that is where genuine QUESTION production comes from. Both
   directions are the same surface with the roles swapped, so this
   component serves both rather than shipping a second renderer with
   no content behind it.
   ================================================================ */

/* §3e — sentence frames as persistent chips above the input.
   At A1 the frames are scaffolding and must survive the whole
   conversation; an adult who has stopped needing them may clear the
   row. Dismissal is SESSION-ONLY — scaffolding decisions belong to
   the syllabus, not to one impatient afternoon. */
function FrameChips({ frames, onInsert }) {
  const [dismissed, setDismissed] = useState(false);
  if (!frames || !frames.length || dismissed) return null;
  return (
    <div className="frame-chips">
      <div className="frame-chips-row">
        {frames.map((f, i) => (
          <button key={i} className="frame-chip" onClick={() => onInsert(f.frame || f)}>{f.frame || f}</button>
        ))}
      </div>
      <button className="frame-chips-x" onClick={() => setDismissed(true)} aria-label="Hide the sentence frames">&times;</button>
    </div>
  );
}

/* §2b.8 — the bridge to conversation. Bubbles, mic parity, and the
   model answer gated behind an attempt: production first is the
   pedagogy, and the design enforces it by simple absence. */
function AskLeoExercise({ exercise, bp, onDone }) {
  const items = exercise.items || [];
  const studentAsks = !!exercise.studentAsks;
  const [idx, setIdx] = useState(0);
  const [turns, setTurns] = useState([]);
  const [input, setInput] = useState("");
  const [busy, setBusy] = useState(false);
  const [attempted, setAttempted] = useState(false);
  const [example, setExample] = useState(null);
  const item = items[idx];

  if (!item) {
    /* Conversation doesn't tick per turn — it responds. The
       set-complete tick still closes the whole set. */
    return <StageComplete correct={items.length} total={items.length} onContinue={() => onDone(items.length, items.length)} />;
  }

  const send = async () => {
    if (!input.trim() || busy) return;
    const said = input.trim();
    setTurns((t) => t.concat([{ role: "you", text: said }]));
    setInput("");
    setAttempted(true);
    setBusy(true);
    try {
      const prompt = studentAsks
        ? `${AUSTRALIAN_SPELLING}You are Leo, an ELICOS teacher in Australia. Your A1 student asked you: "${said}".\n` +
          `${item.leoGuidance ? "Guidance: " + item.leoGuidance + "\n" : ""}` +
          `Answer their question honestly and briefly as yourself. Then, if their question had a small error, model the correct question with the target form in **bold** — warmly, never as a correction notice. Max 25 words. Plain text only.`
        : `${AUSTRALIAN_SPELLING}You are Leo, an ELICOS teacher. You asked your A1 student: "${item.stem}". They answered: "${said}".\n` +
          `Reply warmly to WHAT THEY SAID in one or two short sentences, with the target form in **bold**. If they made an error, recast it correctly inside your reply — never interrupt the flow with a correction notice. Max 25 words. Plain text only.`;
      const raw = await askClaude(prompt, { intent: "ask_leo_reply" });
      setTurns((t) => t.concat([{ role: "leo", text: String(raw || "").trim() }]));
    } catch {
      /* Honest failure: Leo does not invent a reply he never computed.
         The student's turn still counts and the path forward is named. */
      setTurns((t) => t.concat([{ role: "leo", text: "I couldn't reply just then \u2014 but I heard you. Let's keep going.", _failed: true }]));
    } finally { setBusy(false); }
  };

  const next = () => { setIdx(idx + 1); setTurns([]); setInput(""); setAttempted(false); setExample(null); };
  const frames = (bp && bp.sentenceFrames && bp.sentenceFrames.speaking) || [];

  return (
    <div className="ex-item" key={idx}>
      <ExerciseChrome index={idx} total={items.length} label={studentAsks ? "Question" : "Question"} />
      {/* When the student asks, the prompt IS their line to produce —
          shown as an instruction, not as a Leo bubble he already said. */}
      {studentAsks
        ? <p className="ex-instruction">Ask Leo: <strong className="ex-answer">{item.stem}</strong></p>
        : <div className="bubble bubble-bot">
            {item.stem}
            <SpeakButton text={item.stem} />
          </div>}

      <div className="speak-thread">
        {turns.map((t, i) => (
          <div key={i} className={"speak-turn " + (t.role === "leo" ? "speak-leo" : "speak-you")}>
            <p>{t.text}</p>
            {t.role === "leo" && !t._failed && TTS_OK && (
              <SpeakButton text={t.text} />
            )}
          </div>
        ))}
        {busy && <Spinner label="Leo is listening…" />}
      </div>

      {!turns.some((t) => t.role === "leo") && (
        <>
          {frames.length > 0 && <FrameChips frames={frames} onInsert={(f) => setInput((v) => (v ? v + " " : "") + f.replace(/_+/g, "").trim())} />}
          <div className="input-row">
            <input className="text-input" value={input} placeholder={studentAsks ? "Type your question\u2026" : "Type or speak\u2026"}
              onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => e.key === "Enter" && send()}
              disabled={busy} {...EXERCISE_INPUT_PROPS} />
            <MicButton onText={(t) => setInput(t)} />
            <button className="primary-btn" onClick={send} disabled={busy || !input.trim()}>Send</button>
          </div>
          {/* §2b.8 — model answer AFTER attempting, never before. */}
          {attempted && !example && !studentAsks && (
            <button className="ex-showme" onClick={() => setExample(item.model || item.answer || null)}>Show an example</button>
          )}
        </>
      )}
      {example && <div className="bubble bubble-bot stage-enter">For example: {example}</div>}
      {turns.some((t) => t.role === "leo") && (
        <button className="primary-btn" onClick={next}>
          {idx + 1 >= items.length ? "Finish practice" : "Next \u2192"}
        </button>
      )}
    </div>
  );
}

/* §2b — True/false is a two-chip choice wearing different clothes.
   Adapting it here rather than writing a fourth near-identical
   renderer keeps one interaction language across the product. */
function TrueFalseExercise({ exercise, onDone }) {
  const adapted = {
    ...exercise,
    options: ["True", "False"],
    items: (exercise.items || []).map((it) => ({
      ...it,
      options: ["True", "False"],
      answer: it.answer === true || String(it.answer).toLowerCase() === "true" ? "True" : "False",
    })),
  };
  return <ChooseFormExercise exercise={adapted} onDone={onDone} />;
}

/* Runs a list of authored exercises through their renderers in the
   authored order, falling through to the MCQ adapter for shapes with
   no renderer yet. Shared by the grammar and reading stages so neither
   can silently drop authored content the other renders. */
function AuthoredExerciseRunner({ exercises, fallbackQuestions, bp, vocab, onVocabTap, onDone, onAdvance }) {
  const runnable = (exercises || []).filter((ex) => EXERCISE_RENDERERS[ex.exerciseType]);
  const [step, setStep] = useState(0);
  const [score, setScore] = useState({ correct: 0, total: 0 });
  if (step < runnable.length) {
    const ex = runnable[step];
    return (
      <div key={ex.exerciseType + step}>
        {ex.title && <p className="ex-ex-title">{ex.title}</p>}
        {ex.instruction && <p className="ex-instruction">{ex.instruction}</p>}
        {renderAuthoredExercise(ex, (c, t) => {
          setScore((s) => ({ correct: s.correct + c, total: s.total + t }));
          setStep(step + 1);
          if (onAdvance) onAdvance();
        }, bp)}
      </div>
    );
  }
  /* Shapes with a renderer are excluded from the fallback, or their
     items would be asked twice. */
  const remaining = (fallbackQuestions || []).filter((q) => !EXERCISE_RENDERERS[q._exerciseType]);
  if (!remaining.length) {
    return <StageComplete correct={score.correct} total={score.total} onContinue={() => onDone(score.correct, score.total)} />;
  }
  return <McqQuiz questions={remaining} vocab={vocab} onVocabTap={onVocabTap} onAdvance={onAdvance}
    onDone={(c, t) => onDone(score.correct + c, score.total + t)} />;
}

/* ================================================================
   PHASE 10 — MATCH_QUESTION_ANSWER AND WRITE_THE_QUESTION
   Plus the five structural-mismatch fixes (sort_into_groups,
   build_the_sentence, multi-blank own_word, personalisation
   reorder generalisation, vocab ceiling raised to 12).
   ================================================================ */

/* §2b — match_question_answer: tap a question, then tap its answer.
   Same interaction as the existing vocabulary matcher (tap-first,
   tap-second) at exercise scale. Pairs are shuffled once on load so
   the correct answer is never always in the same position.
   The chrome is the same as every other exercise type: dots, tick,
   Show me, silent re-queue-once. */
function MatchQuestionAnswerExercise({ exercise, onDone }) {
  const items = exercise.items || [];
  const q = useExerciseQueue(items);
  const [selectedLeft, setSelectedLeft] = useState(null);
  const [settled, setSettled] = useState(null); // null | {ok, chosen}
  const [shown, setShown] = useState(false);
  const [correct, setCorrect] = useState(0);
  const item = q.current;

  /* Shuffle the right-hand options once per item so position doesn't
     signal the answer. Include all items' right sides to give a
     realistic distractor set, not just the current item. */
  const allRights = React.useMemo(
    () => shuffleOptions(items.map((it, i) => ({ text: it.right, idx: i })), items.length * 7),
    [items]
  );

  if (q.finished || !item) {
    return <StageComplete correct={correct} total={items.length} onContinue={() => onDone(correct, items.length)} />;
  }

  const isCorrect = settled && settled.chosen === item.right;
  const showMe = () => { if (settled) return; setShown(true); };
  const pickRight = (text) => {
    if (settled || shown) return;
    const ok = text === item.right;
    setSettled({ ok, chosen: text });
    if (ok) setCorrect((c) => c + 1);
  };
  const next = () => {
    q.advance(isCorrect);
    setSelectedLeft(null); setSettled(null); setShown(false);
  };

  return (
    <div className="ex-item">
      <ExerciseChrome index={q.index} total={q.total} label="Pair" />
      {/* The question is fixed on the left; the student picks from the
          shuffled right-hand column. */}
      <p className="ex-sentence">{item.left}</p>
      <div className="mqa-rights">
        {allRights.map((r, i) => {
          const isChosen = settled && settled.chosen === r.text;
          const isAnswer = settled && r.text === item.right;
          return (
            <button key={i}
              className={"mqa-opt" + (settled ? (isAnswer ? " mqa-correct" : isChosen ? " mqa-chosen" : " mqa-muted") : "")}
              onClick={() => pickRight(r.text)}
              disabled={!!settled || shown}>
              {r.text}
            </button>
          );
        })}
      </div>
      {!settled && <ShowMeLink onShow={showMe} shown={shown} />}
      {shown && <CorrectAnswerReveal answer={item.right} />}
      {settled && (
        <>
          <LeoFeedback ok={isCorrect}>
            {isCorrect ? "That's the pair." : <>The answer is <strong className="ex-answer">{item.right}</strong>.</>}
          </LeoFeedback>
          <button className="primary-btn" onClick={next}>
            {q.index + 1 >= q.total ? "Finish practice" : "Next \u2192"}
          </button>
        </>
      )}
    </div>
  );
}

/* §2b — write_the_question: given an answer, write the question.
   Typed production. The acceptance surface is the same as GapFillInput
   (normalised, case-insensitive, punctuation-tolerant) but here the
   student is producing a whole sentence rather than a gap-fill word,
   so the stem shows the given ANSWER and the input is above it.
   alsoAccept is respected — U1L1's Ex7 item 6 accepts two forms. */
function WriteTheQuestionExercise({ exercise, onDone }) {
  const items = exercise.items || [];
  const q = useExerciseQueue(items);
  const [input, setInput] = useState("");
  const [checked, setChecked] = useState(null);
  const [shown, setShown] = useState(false);
  const [correct, setCorrect] = useState(0);
  const item = q.current;

  if (q.finished || !item) {
    return <StageComplete correct={correct} total={items.length} onContinue={() => onDone(correct, items.length)} />;
  }

  const answers = [item.answer].concat(item.alsoAccept || []);
  const settled = checked !== null || shown;
  const ok = checked === true;

  const check = () => {
    if (!input.trim() || settled) return;
    const isOk = typedAnswerMatches(input, answers);
    setChecked(isOk ? true : false);
    if (isOk) setCorrect((c) => c + 1);
  };

  const next = () => {
    q.advance(ok);
    setInput(""); setChecked(null); setShown(false);
  };

  return (
    <div className="ex-item" key={q.index}>
      <ExerciseChrome index={q.index} total={q.total} label="Question" />
      <p className="ex-instruction">Write the question for this answer:</p>
      {/* The given answer is the prompt — shown clearly so the student
          can work backwards to the question. */}
      <div className="grammar-form-box">
        <p className="gb-keypoint-text">{item.given}</p>
      </div>
      {settled
        ? <p className="ex-sentence"><strong className="ex-answer">{answers[0]}</strong></p>
        : (
          <>
            <div className="input-row">
              <input className="text-input" value={input}
                placeholder={"Type the question\u2026"}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && check()}
                disabled={settled} {...EXERCISE_INPUT_PROPS} />
              <button className="primary-btn" onClick={check} disabled={!input.trim()}>Check</button>
            </div>
            <ShowMeLink onShow={() => setShown(true)} shown={shown} />
          </>
        )}
      {shown && <CorrectAnswerReveal answer={answers[0]} note={item.alsoAccept && item.alsoAccept.length ? `Also correct: ${item.alsoAccept.join(", ")}` : null} />}
      {checked !== null && (
        <LeoFeedback ok={ok}>
          {ok ? "That's the question." : <>The question is <strong className="ex-answer">{answers[0]}</strong>.</>}
        </LeoFeedback>
      )}
      {settled && (
        <button className="primary-btn" onClick={next}>
          {q.index + 1 >= q.total ? "Finish practice" : "Next \u2192"}
        </button>
      )}
    </div>
  );
}

/* ================================================================
   STRUCTURAL MISMATCH FIX 1: sort_into_groups
   Used in U1L2 (a/an) and U2L1 (man/woman/both).
   Tap-to-bucket: items start in a pool, tapping one moves it into
   the currently-selected bucket. No wrong/right on individual taps —
   the whole set is submitted at once.
   ================================================================ */
function SortIntoGroupsExercise({ exercise, onDone }) {
  const groups = exercise.groups || [];
  const items = exercise.items || [];
  /* Shuffle the item pool once on load. */
  const [pool, setPool] = useState(() => shuffleOptions(items.map((it, i) => ({ ...it, id: i })), items.length * 13));
  const [buckets, setBuckets] = useState(() => Object.fromEntries(groups.map(g => [g, []])));
  const [checked, setChecked] = useState(false);
  const [correct, setCorrect] = useState(0);

  const allPlaced = pool.length === 0;

  const placeItem = (item, group) => {
    setPool(p => p.filter(x => x.id !== item.id));
    setBuckets(b => ({ ...b, [group]: b[group].concat([item]) }));
  };
  const returnItem = (item, group) => {
    if (checked) return;
    setBuckets(b => ({ ...b, [group]: b[group].filter(x => x.id !== item.id) }));
    setPool(p => p.concat([item]));
  };

  const check = () => {
    if (!allPlaced || checked) return;
    let c = 0;
    groups.forEach(g => { buckets[g].forEach(it => { if (it.group === g) c++; }); });
    setCorrect(c);
    setChecked(true);
  };

  if (checked) {
    return (
      <div className="ex-item">
        <div className="sig-buckets">
          {groups.map(g => (
            <div key={g} className="sig-bucket">
              <p className="gram-section-label">{g}</p>
              {buckets[g].map((it, i) => (
                <span key={i} className={"sig-word " + (it.group === g ? "sig-correct" : "sig-wrong")}>{it.word}</span>
              ))}
            </div>
          ))}
        </div>
        <StageComplete correct={correct} total={items.length}
          onContinue={() => onDone(correct, items.length)} />
      </div>
    );
  }

  return (
    <div className="ex-item">
      <ExerciseChrome index={pool.length} total={items.length} label="Sorted" />
      <p className="ex-instruction">{exercise.instruction || "Tap a word, then tap the right group."}</p>
      {/* Pool: words waiting to be sorted. */}
      <div className="sig-pool">
        {pool.map((it, i) => (
          /* Tapping a pool word opens a picker inline rather than a
             separate UI — the bucket buttons appear below the word
             and the student taps one to place it. */
          <PoolWord key={it.id} item={it} groups={groups} onPlace={placeItem} />
        ))}
      </div>
      {/* Buckets: words already placed. */}
      <div className="sig-buckets">
        {groups.map(g => (
          <div key={g} className="sig-bucket sig-bucket-live">
            <p className="gram-section-label">{g}</p>
            {buckets[g].map((it, i) => (
              <button key={i} className="sig-word sig-placed" onClick={() => returnItem(it, g)}>{it.word}</button>
            ))}
          </div>
        ))}
      </div>
      {allPlaced && (
        <div className="ex-actions stage-enter">
          <button className="primary-btn" onClick={check}>Check</button>
        </div>
      )}
    </div>
  );
}

/* Tap a pool word → group buttons appear immediately below it. Tap a
   group → the word moves there. Keeps everything in one thumb zone. */
function PoolWord({ item, groups, onPlace }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="sig-pool-item">
      <button className={"sig-word" + (open ? " sig-word-open" : "")} onClick={() => setOpen(o => !o)}>
        {item.word}
      </button>
      {open && (
        <div className="sig-picker stage-enter">
          {groups.map((g, i) => (
            <button key={i} className="sig-group-btn" onClick={() => { onPlace(item, g); setOpen(false); }}>{g}</button>
          ))}
        </div>
      )}
    </div>
  );
}

/* ================================================================
   STRUCTURAL MISMATCH FIX 2: build_the_sentence
   Given a bare "subject / noun" cue, the student types the full
   sentence using 'be' + a/an (or have got, or possessives).
   Typed production. The "/" in the cue must NOT be read by TTS as
   "forward slash" — TTS is not offered here since the cue is
   structured, not a natural sentence to hear.
   ================================================================ */
function BuildTheSentenceExercise({ exercise, onDone }) {
  const items = exercise.items || [];
  const q = useExerciseQueue(items);
  const [input, setInput] = useState("");
  const [checked, setChecked] = useState(null);
  const [shown, setShown] = useState(false);
  const [correct, setCorrect] = useState(0);
  const item = q.current;

  if (q.finished || !item) {
    return <StageComplete correct={correct} total={items.length} onContinue={() => onDone(correct, items.length)} />;
  }

  const answers = [item.answer].concat(item.alsoAccept || []);
  const settled = checked !== null || shown;

  const check = () => {
    if (!input.trim() || settled) return;
    const ok = typedAnswerMatches(input, answers);
    setChecked(ok ? true : false);
    if (ok) setCorrect((c) => c + 1);
  };

  const next = () => {
    q.advance(checked === true);
    setInput(""); setChecked(null); setShown(false);
  };

  return (
    <div className="ex-item" key={q.index}>
      <ExerciseChrome index={q.index} total={q.total} label="Sentence" />
      <p className="ex-instruction">{exercise.instruction || "Make a full sentence."}</p>
      {/* The cue is a bare "subject / noun" pair — shown in the form
          box to distinguish it clearly from a sentence to correct. */}
      <div className="grammar-form-box">
        <p className="gb-keypoint-text">{item.given}</p>
      </div>
      {settled
        ? <p className="ex-sentence"><strong className="ex-answer">{answers[0]}</strong></p>
        : (
          <>
            <div className="input-row">
              <input className="text-input" value={input}
                placeholder={"Type the sentence\u2026"}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && check()}
                disabled={settled} {...EXERCISE_INPUT_PROPS} />
              <button className="primary-btn" onClick={check} disabled={!input.trim()}>Check</button>
            </div>
            <ShowMeLink onShow={() => setShown(true)} shown={shown} />
          </>
        )}
      {shown && <CorrectAnswerReveal answer={answers[0]} note={item.note} />}
      {checked !== null && (
        <LeoFeedback ok={checked === true}>
          {checked ? (item.note || "That's it.") : <>The sentence is <strong className="ex-answer">{answers[0]}</strong>. {item.note || ""}</>}
        </LeoFeedback>
      )}
      {settled && (
        <button className="primary-btn" onClick={next}>
          {q.index + 1 >= q.total ? "Finish practice" : "Next \u2192"}
        </button>
      )}
    </div>
  );
}

function GrammarSection({ bp, section, vocab, onVocabTap, onSkip, onDone, header }) {
  const g = bp.grammar || {};
  const hasPractice = section.questions && section.questions.length >= 3 && !section.explanationOnly;
  const [practising, setPractising] = useState(false);
  const [boardOpen, setBoardOpen] = useState(false);
  /* §2a — authored lessons carry structured blocks; generated lessons do
     not. The DATA decides the treatment, never a type flag, so every
     generated lesson renders exactly as it does today. */
  const blocks = bp.grammarBlocks;
  const hasBlocks = grammarBlockList(blocks).length > 0;
  /* §2a.5 — walked through the first time, stacked on re-visit. The
     signal is held state: a stage already recorded as presented means
     this student has been walked through it before. */
  const alreadySeen = !!(section && section.presented);

  if (!practising && hasBlocks) return (
    <SectionShell header={header} title={`Grammar: ${g.point}`} blurb="One point, straight from today's situation — never grammar for its own sake." onSkip={onSkip}>
      <GrammarPresentation
        blocks={blocks}
        alreadySeen={alreadySeen}
        onDone={() => (hasPractice ? setPractising(true) : onDone(0, 0))}
      />
    </SectionShell>
  );

  if (practising && hasBlocks) return (
    <SectionShell header={header} title={`Grammar: ${g.point}`} onSkip={onSkip}>
      <AuthoredGrammarPractice bp={bp} section={section} vocab={vocab} onVocabTap={onVocabTap} onDone={onDone} />
      {/* §2a.5 — reference reachable without leaving the task. */}
      <ReviewBoardLink onOpen={() => setBoardOpen(true)} />
      {boardOpen && <GrammarBoardSheet blocks={blocks} onClose={() => setBoardOpen(false)} />}
    </SectionShell>
  );

  return <GrammarSectionGenerated bp={bp} section={section} vocab={vocab} onVocabTap={onVocabTap} onSkip={onSkip} onDone={onDone} practising={practising} setPractising={setPractising} />;
}

/* The GENERATED-lesson grammar treatment — prose Meaning/Form/Usage plus
   gram-ref-table. Untouched by Phase 2 (spec §2a.1: it stays for the
   content shape it fits). */
function GrammarSectionGenerated({ bp, section, vocab, onVocabTap, onSkip, onDone, practising, setPractising }) {
  const g = bp.grammar || {};
  const hasPractice = section.questions && section.questions.length >= 3 && !section.explanationOnly;
  if (!practising) return (
    <SectionShell header={header} title={`Grammar: ${g.point}`} blurb="One point, straight from today's situation — never grammar for its own sake." onSkip={onSkip}>
      <div className="grammar-card">
        <p className="gram-section-label">Meaning</p>
        <p><VocabText text={g.meaning} vocab={vocab} onTap={onVocabTap} /></p>
        <p className="gram-section-label">The form</p>
        <div className="grammar-form-box"><span className="gram-form">{g.form}</span></div>
        <p className="gram-section-label">When to use it</p>
        <p><VocabText text={g.usage} vocab={vocab} onTap={onVocabTap} /></p>
        {(g.examples || []).map((ex, i) => (
          <div key={i} className="grammar-example">
            <span className="grammar-example-bar" />
            <VocabText text={ex} vocab={vocab} onTap={onVocabTap} />
          </div>
        ))}
      </div>
      {/* Grammar reference table — settled tokens (§2.6) */}
      {g.reference && g.reference.length > 0 && (
        <div className="gram-ref-table" style={{ overflowX: "auto", marginTop: 12 }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "13.5px" }}>
            <thead>
              <tr>
                <th style={{ textAlign: "left", padding: "8px 10px", borderBottom: "2px solid var(--leo-green)", color: "var(--text-primary)", fontWeight: 700 }}>Function</th>
                <th style={{ textAlign: "left", padding: "8px 10px", borderBottom: "2px solid var(--leo-green)", color: "var(--text-primary)", fontWeight: 700 }}>Form</th>
                <th style={{ textAlign: "left", padding: "8px 10px", borderBottom: "2px solid var(--leo-green)", color: "var(--text-primary)", fontWeight: 700 }}>Example</th>
              </tr>
            </thead>
            <tbody>
              {g.reference.map((row, i) => (
                <tr key={i}>
                  <td style={{ padding: "7px 10px", borderBottom: "1px solid var(--divider)", fontWeight: 600, color: "var(--text-primary)" }}>{row.function}</td>
                  <td style={{ padding: "7px 10px", borderBottom: "1px solid var(--divider)" }}><span className="gram-form">{row.form}</span></td>
                  <td style={{ padding: "7px 10px", borderBottom: "1px solid var(--divider)", fontStyle: "italic", opacity: 0.8 }}>{row.example}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      {hasPractice
        ? <button className="primary-btn" onClick={() => setPractising(true)}>Practise it</button>
        : <button className="primary-btn" onClick={() => onDone(0, 0)}>Continue</button>}
    </SectionShell>
  );
  return (
    <SectionShell header={header} title={`Grammar: ${g.point}`} onSkip={onSkip}>
      <McqQuiz questions={section.questions} vocab={vocab} onVocabTap={onVocabTap} onDone={onDone} />
    </SectionShell>
  );
}

/* ================================================================
   W-01 WHITEBOARD GRAMMAR — BoardFrame + GrammarBoard
   Phase 1 partial build. Renderer only; planner does not emit boards yet.
   Every current lesson renders on the existing prose fallback (unchanged).
   When the planner starts emitting valid boards, this surface takes over.
   ================================================================ */

/* BoardFrame — the v3 rounded rect + tray, same shape as WhiteboardLogo.
   One shape, two scales, one identity. Board stroke is 2.5px --marker-black;
   logo stroke is 2px --leo-green. */
function BoardFrame({ children, width }) {
  const w = width || "100%";
  return (
    <div className="wb-board" style={{ width: w }}>
      <svg viewBox="-5 -5 810 602" className="wb-board-svg" role="presentation" aria-hidden="true"
        style={{ width: "100%", height: "auto", display: "block" }}>
        {/* v4 §2.1: frame and tray are discrete objects with a 12-unit gap between them. */}
        <rect x="0" y="0" width="800" height="560" rx="30"
          fill="var(--board-face)" stroke="var(--marker-black)" strokeWidth="2.5"
          vectorEffect="non-scaling-stroke" />
        {/* v4 §2.2: tray drawn after frame. No occlusion — the gap separates them. */}
        <rect x="60" y="572" width="680" height="20" rx="10"
          fill="var(--board-face)" stroke="var(--marker-black)" strokeWidth="2.5"
          vectorEffect="non-scaling-stroke" />
      </svg>
      <div className="wb-board-content">{children}</div>
    </div>
  );
}

/* Hand imperfection (§4.3). Block-level, deterministic, subtle.
   Each element gets ±1.2° rotation and ±1px baseline offset, derived from
   textSeed() of its own text. Same board, same seed, same render — a board
   that shimmers between sessions is a Continuity Integrity defect. */
function _boardImperfection(text) {
  const seed = textSeed(String(text || ""));
  const rot = ((seed % 240) - 120) / 100; // ±1.2°
  const yOff = ((seed >> 8) % 200 - 100) / 100; // ±1px
  return { transform: `rotate(${rot.toFixed(2)}deg) translateY(${yOff.toFixed(1)}px)` };
}

/* Hand-drawn wavering line. 2-3 shallow curve segments approximating a
   straight line — never ruler-straight, never scribble. Deterministic. */
function _waverPath(x1, y1, x2, y2, seed) {
  const dx = x2 - x1, dy = y2 - y1;
  const s = textSeed(String(seed || "") + x1);
  const mid1x = x1 + dx * 0.33, mid2x = x1 + dx * 0.66;
  const wobble = 2.5;
  const w1 = ((s % 100) - 50) / 50 * wobble;
  const w2 = (((s >> 7) % 100) - 50) / 50 * wobble;
  return `M ${x1} ${y1} Q ${mid1x} ${y1 + dy * 0.33 + w1}, ${x1 + dx * 0.5} ${y1 + dy * 0.5} Q ${mid2x} ${y1 + dy * 0.66 + w2}, ${x2} ${y2}`;
}

/* Role → CSS class mapping (§5.1) */
const _ROLE_CLASS = { plain: "wb-plain", structure: "wb-structure", target: "wb-target", model: "wb-model" };
function _roleClass(role) { return _ROLE_CLASS[role] || "wb-plain"; }

/* RoleSpan — a span of text with a grammar role, rendered through VocabText
   so tap-to-learn survives onto the board (§5.6). */
function RoleSpan({ text, role, vocab, onVocabTap }) {
  return <span className={_roleClass(role)}><VocabText text={text} vocab={vocab || []} onTap={onVocabTap} /></span>;
}

/* ---- Element renderers, one per §6.1 type ---- */

function BoardTitle({ el, idx }) {
  const imp = _boardImperfection(el.text);
  return (
    <div className="wb-el wb-title" style={{ ...imp, animationDelay: (idx * 130) + "ms" }}>
      <span className="wb-title-text">{el.text}</span>
      <svg className="wb-title-underline" height="6" aria-hidden="true">
        <path d={_waverPath(0, 3, 200, 3, el.text)} stroke="var(--marker-blue)" strokeWidth="2.5" fill="none" />
      </svg>
    </div>
  );
}

function BoardRule({ el, idx, vocab, onVocabTap }) {
  const imp = _boardImperfection((el.pieces || []).map(p => p.text).join(" "));
  return (
    <div className="wb-el wb-rule" style={{ ...imp, animationDelay: (idx * 130) + "ms" }}>
      {(el.pieces || []).map((p, i) => <RoleSpan key={i} text={p.text} role={p.role} vocab={vocab} onVocabTap={onVocabTap} />)}
    </div>
  );
}

function BoardFormula({ el, idx, vocab, onVocabTap }) {
  const imp = _boardImperfection((el.boxes || []).map(b => b.text).join("+"));
  const joiner = el.joiner || "+";
  return (
    <div className="wb-el wb-formula" style={{ ...imp, animationDelay: (idx * 130) + "ms" }}>
      {(el.boxes || []).map((box, i) => (
        <React.Fragment key={i}>
          {i > 0 && <span className="wb-formula-join">{joiner}</span>}
          <span className={`wb-formula-box ${_roleClass(box.role)}`}>
            <RoleSpan text={box.text} role={box.role} vocab={vocab} onVocabTap={onVocabTap} />
          </span>
        </React.Fragment>
      ))}
    </div>
  );
}

function BoardSubTable({ el, idx, vocab, onVocabTap }) {
  const imp = _boardImperfection((el.slots || []).map(s => s.label).join(" "));
  return (
    <div className="wb-el wb-subtable" style={{ ...imp, animationDelay: (idx * 130) + "ms" }}>
      <div className="wb-subtable-grid" style={{ gridTemplateColumns: `repeat(${(el.slots || []).length}, 1fr)` }}>
        {(el.slots || []).map((slot, si) => (
          <div key={si} className={`wb-slot ${slot.target ? "wb-slot-target" : ""}`}>
            {el.numbered && <span className="wb-slot-num">{si + 1}</span>}
            <span className="wb-slot-label">{slot.label}</span>
            <div className="wb-slot-items">
              {(slot.items || []).map((item, ii) => (
                <div key={ii} className="wb-slot-item">
                  <RoleSpan text={item} role={slot.target ? "target" : "plain"} vocab={vocab} onVocabTap={onVocabTap} />
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
      {el.example && (
        <div className="wb-subtable-example wb-model">
          <VocabText text={el.example} vocab={vocab || []} onTap={onVocabTap} />
        </div>
      )}
    </div>
  );
}

function BoardExample({ el, idx, vocab, onVocabTap }) {
  const imp = _boardImperfection((el.spans || []).map(sp => sp.text).join(" "));
  return (
    <div className="wb-el wb-example" style={{ ...imp, animationDelay: (idx * 130) + "ms" }}>
      <span className="wb-example-text">
        {(el.spans || []).map((sp, i) => <RoleSpan key={i} text={sp.text} role={sp.role} vocab={vocab} onVocabTap={onVocabTap} />)}
      </span>
      {el.mark === "tick" && <span className="wb-mark wb-mark-tick" aria-label="correct">✓</span>}
      {el.mark === "cross" && <span className="wb-mark wb-mark-cross" aria-label="incorrect">✗</span>}
    </div>
  );
}

function BoardContrast({ el, idx, vocab, onVocabTap }) {
  const fromText = (el.from && el.from.spans || []).map(sp => sp.text).join(" ");
  const toText = (el.to && el.to.spans || []).map(sp => sp.text).join(" ");
  const imp = _boardImperfection(fromText + toText);
  return (
    <div className="wb-el wb-contrast" style={{ ...imp, animationDelay: (idx * 130) + "ms" }}>
      <div className="wb-contrast-from">
        {(el.from && el.from.spans || []).map((sp, i) => <RoleSpan key={i} text={sp.text} role={sp.role} vocab={vocab} onVocabTap={onVocabTap} />)}
      </div>
      <svg className="wb-contrast-arrow" width="40" height="24" aria-hidden="true">
        <path d={_waverPath(4, 12, 32, 12, fromText)} stroke="var(--marker-orange)" strokeWidth="2" fill="none" />
        <polygon points="30,6 38,12 30,18" fill="var(--marker-orange)" />
      </svg>
      <div className="wb-contrast-to">
        {(el.to && el.to.spans || []).map((sp, i) => <RoleSpan key={i} text={sp.text} role={sp.role} vocab={vocab} onVocabTap={onVocabTap} />)}
      </div>
    </div>
  );
}

function BoardNote({ el, idx }) {
  const imp = _boardImperfection(el.text);
  return (
    <div className="wb-el wb-note" style={{ ...imp, animationDelay: (idx * 130) + "ms" }}>
      <svg className="wb-note-bubble" viewBox="0 0 200 50" aria-hidden="true">
        <path d={_waverPath(10, 5, 190, 5, el.text + "top")} stroke="var(--marker-orange)" strokeWidth="1.5" fill="none" />
        <path d={_waverPath(190, 5, 190, 40, el.text + "right")} stroke="var(--marker-orange)" strokeWidth="1.5" fill="none" />
        <path d={_waverPath(190, 40, 10, 40, el.text + "bottom")} stroke="var(--marker-orange)" strokeWidth="1.5" fill="none" />
        <path d={_waverPath(10, 40, 10, 5, el.text + "left")} stroke="var(--marker-orange)" strokeWidth="1.5" fill="none" />
      </svg>
      <span className="wb-note-text">{el.text}</span>
    </div>
  );
}

const _BOARD_RENDERERS = {
  title: BoardTitle, rule: BoardRule, formula: BoardFormula,
  subTable: BoardSubTable, example: BoardExample, contrast: BoardContrast, note: BoardNote,
};

/* GrammarBoard — renders one or more boards inside BoardFrame.
   §7: the whole surface is a figure with role="img" semantics. The prose
   fields (meaning, form, usage, examples) serve as the screen-reader
   alternative — one source of truth, already correct. */
function GrammarBoard({ boards, grammar, vocab, onVocabTap }) {
  const g = grammar || {};
  const captionId = "wb-caption-" + textSeed(g.point || "grammar");
  // Build a connected prose caption from the existing fields — one paragraph,
  // not four labelled fields. A screen reader reading "Meaning: X. Form: Y."
  // hears an outline; a connected paragraph hears a caption. Composed from the
  // same prose fields the fallback renders, so one source of truth.
  const caption = [
    g.point && `Today's grammar point is ${g.point}.`,
    g.meaning && `It means ${g.meaning}.`,
    g.form && `The form is: ${g.form}.`,
    g.usage && `Use it ${g.usage}.`,
    ...(g.examples || []).map((ex) => `For example: ${ex}.`),
  ].filter(Boolean).join(" ");

  return (
    <div className="wb-boards" role="figure" aria-labelledby={captionId}>
      {/* Visually hidden but present for screen readers — the caption the
          figure points at. Inline style, no external sr-only class dependency. */}
      <div id={captionId} style={{
        position: "absolute", width: "1px", height: "1px",
        padding: 0, margin: "-1px", overflow: "hidden",
        clip: "rect(0,0,0,0)", whiteSpace: "nowrap", border: 0,
      }}>{caption}</div>
      {boards.map((board, bi) => (
        <BoardFrame key={bi}>
          <div className="wb-writing-band" aria-hidden="true">
            {(board.elements || []).map((el, ei) => {
              const Renderer = _BOARD_RENDERERS[el.type];
              return Renderer ? <Renderer key={ei} el={el} idx={ei} vocab={vocab} onVocabTap={onVocabTap} /> : null;
            })}
          </div>
        </BoardFrame>
      ))}
    </div>
  );
}

/* ---------- Stage 7: Summary — praise, growth, mission, tomorrow ---------- */
function SummarySection({ bp, section, vocab, onVocabTap, onFinish }) {
  const s = section;
  return (
    <div className="summary-flow">
      {/* §2.2.1 Drawn tick */}
      <div className="sc-tick-wrap" style={{ animation: "scRise .4s ease-out both" }}>
        <svg className="sc-tick" viewBox="0 0 52 52"><circle className="sc-tick-ring" cx="26" cy="26" r="22" fill="none" strokeWidth="2.5" /><path className="sc-tick-mark" fill="none" strokeWidth="3.5" strokeLinecap="round" strokeLinejoin="round" d="M15 27l7 7 15-15" /></svg>
      </div>
      <h3 className="summary-heading" style={{ animation: "scRise .4s ease-out both", animationDelay: "0.5s", opacity: 0 }}>That's today done</h3>
      <p className="text-leo summary-praise" style={{ animation: "scRise .4s ease-out both", animationDelay: "0.8s", opacity: 0 }}><VocabText text={s.praise} vocab={vocab} onTap={onVocabTap} /></p>
      <div className="card summary-built" style={{ animation: "scRise .4s ease-out both", animationDelay: "1.1s", opacity: 0 }}>
        <p className="gram-section-label">What you built today</p>
        <p className="muted"><VocabText text={s.summary} vocab={vocab} onTap={onVocabTap} /></p>
      </div>
      <div style={{ animation: "scRise .4s ease-out both", animationDelay: "1.4s", opacity: 0 }}>
        <p className="text-leo"><strong>{"\uD83D\uDCAA"} Your strength:</strong> {s.strength}</p>
        <p className="text-leo"><strong>{"\uD83C\uDFAF"} One thing to work on:</strong> {s.improvement}</p>
      </div>
      <div className="mission-box" style={{ animation: "scRise .4s ease-out both", animationDelay: "1.7s", opacity: 0 }}>
        <span className="mission-icon">{"\uD83C\uDF0F"}</span><p><VocabText text={bp.mission} vocab={vocab} onTap={onVocabTap} /></p>
      </div>
      {s.tomorrowPreview && <p className="lesson-tomorrow" style={{ animation: "scRise .4s ease-out both", animationDelay: "2.0s", opacity: 0 }}><strong>Next time:</strong> {s.tomorrowPreview}</p>}
      <button className="primary-btn wide" style={{ marginTop: "var(--space-5)", animation: "scRise .4s ease-out both", animationDelay: "2.3s", opacity: 0 }} onClick={onFinish}>Finish lesson</button>
    </div>
  );
}

/* ---------- Blueprint JSON shape (single source of truth) ----------
   Every planner call that must return a blueprint — the first attempt,
   the fix-retry and the post-review revision — restates this exact shape.
   askClaude() is stateless, so a retry that doesn't restate the shape
   cannot possibly succeed. */
// CEFR productive-language constraints. RATIFIED by Lessons_ASKLEO, 26 July 2026
// (cefr-constraints-v1.md, MD5 5afcd36a61c1b6e79cf22d25bd16d362). A1 ratified with
// amendments; A2-C2 authored by Lessons. Governs PRODUCTIVE target language only,
// not receptive reading/listening (i+1). C2 is authored but RESERVED — CEFR_ORDER
// does not include it, so it is unreachable until the picker extends. Do not edit
// without a Lessons ruling.
